insert into public.courses
    (code, name, hours, description, exclusions, breadth, prereq_tree)
values
    ('NMC368H1', 'Coptic Art & Archaeology', '24L', 'A survey of Coptic art, archaeology and architecture. The course will cover aspects of the religious, civil and daily life of the Copts: their houses, religious architecture, funerary monuments, art and artefacts', null, 1, null::jsonb),
    ('NMC369H1', 'Archaeology of Mesopotamia II: States and Empires', '36L', 'A comprehensive survey class on the archaeology of Mesopotamia during historic time periods (Sumer, Assyria, and Babylon; 2300 – 333 BC), covering the rise of the Akkadian Empire, the Neo-Sumerian “renaissance” of the Ur III State, Hammurapi’s Babylon, the Late Bronze Age under Kassite and Mittani rule, the rise and dominance of Assyria, and the splendor and fall of Babylon. This class will focus on the area of modern-day Iraq but also will consult materials from western Iran, eastern Syria, and southeastern Turkey.', 'NMC363H1', 3, '{"operator": "AND", "items": ["NMC102H1"]}'::jsonb),
    ('NMC370H1', 'History of Ancient Israel', '24L', 'The course is concerned with the political and cultural history of ancient Israel and the Hebrew people from origin stories set in the pre-monarchic period to early Roman Palestine. Israel is the land that bequeathed the Bible, the Jewish people, and hosted the birth of Christianity. Much of its history witnessed hostile interactions with imperial forces, from Babylon to Rome. While the focus is on key people, events, and essential chronology, the course also addresses critical questions concerning the use of sources (primary among which is the Hebrew Bible/Old Testament); differences between ancient history-writing and modern history-writing; and the assumptions and methods involved in reconstructing historical events.', null, 3, '{"operator": "AND", "items": ["NMC104H1", "NMC252H1"]}'::jsonb),
    ('NMC371H1', 'Topics in Hebrew Bible', '24S', 'This course will cover various aspects of the Hebrew Bible, from the study of a book (e.g., Genesis), a group of books (e.g., the Prophetic books) to a topic (e.g., women in the Bible).', null, 1, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('NMC372H1', 'Islam and Muslims in the Balkans', '24L', 'The Balkans has been in contact with Islam and inhabited by Muslims for six centuries. Nowadays it is the home of over eight million Muslims of various ethnic backgrounds who constitute the second largest religious group in the region. This course examines the history of Islam, Muslims, and Muslim culture in the Balkans from the Ottoman conquest in the fourteenth century until the present day while placing it in a wider transregional context. Topics covered include formation of Muslim communities, Sufi groups, the Muslims and the Balkan national imagination, responses to modernity, Muslims as minorities, Muslim experiences in communist states, and the breakup of Yugoslavia.', 'HIS306H1', 3, '{"operator": "OR", "items": ["NMC103H1", "NMC273Y1", "NMC278H1", "NMC377Y1", "NMC355H1", "NMC386H1"]}'::jsonb),
    ('NMC373H1', 'Modern Iran', '24L', 'This course covers the history of Iran from the early modern period to the present. Following an overview of the Safavid revolution and the empire it created (1501–1722), we examine the political upheavals experienced in post-Safavid Iran throughout the 18th century that culminated in the rise of the Qajar polity. This review of early modern Iranian history will set the stage for our investigation of the defining moments in the modern history of Iran, including the Constitutional Revolution (1905–1911), the subsequent toppling of the Qajar dynasty, and the establishment of Pahlavi rule under Reza Shah. We then focus on the events leading up to and including the Islamic Revolution of 1979 and the making of the Islamic Republic. The course concludes with an exploration of society and culture in contemporary Iran.', null, 3, null::jsonb),
    ('NMC375H1', 'Conversion to Islam in Medieval History', '24S', 'How did Islam spread in the world? The question has puzzled historians for years. For centuries after the rise of Islam, much of the Middle East was still largely comprised of diverse communities of non-Muslims. This course on the complex history of “Islamization” examines when, how, and why various societies became majority Muslim, through a close look at case studies and sources from across the medieval world including Spain, North Africa, Central Asia and India. Topics covered include religious tolerance, polemic, cultural assimilation, minority identities, interreligious marriages, children of mixed families, and the contentious issues of apostasy and forced conversion.', null, 3, '{"operator": "OR", "items": ["NMC103H1", "NMC273Y1"]}'::jsonb),
    ('NMC376H1', 'History of Islamic Spain and North Africa (640-1492)', '24L', 'Muslim conquest of North Africa and Spain, history of Spain under Muslim rule to 1492. Attention given to institutional and cultural development, Islamic Spain''s relations with the Islamic east and neighbours in Europe.', null, 3, '{"operator": "AND", "items": ["NMC273Y1"]}'::jsonb),
    ('NMC378H1', 'Modern Arab History', '36L', 'A thematic treatment of the Arab lands of the Middle East and North Africa from 1700 onward, focusing on the Ottoman and colonial periods.', null, 3, '{"operator": "AND", "items": ["NMC278H1"]}'::jsonb),
    ('NMC379H1', 'Capital, Technology, and Utopia in the Modern Middle East', '12L/12S', 'How does the workings of capital intersect with technological innovation and political visions in the modern Middle East? This course approaches this question through critical reading in the histories of capitalism, crisis, science, politics, and intersections between cultural history and technology studies using the Middle East as a starting point for the study of global phenomena. We will examine the ways in which constructions like race and ethnicity, gender, and the human/non-human divide have mediated the social and spatial expansion of capital in the region, especially through technological infrastructure and utopias between the late 18th and the 21st centuries.', null, 3, '{"operator": "AND", "items": [{"credits": 0.5, "department": null}]}'::jsonb),
    ('NMC380H1', 'Religion in the Ancient Near East', '48S', 'This course examines a variety of different sources of evidence for religion in the ancient Near East, especially in Mesopotamia, the Levant, and Anatolia, including original written sources, archaeological evidence and iconography. Where possible, the focus will be on reading primary Near Eastern texts, and interpreting them within their contemporary social and political context. We also will discuss links between ancient Near Eastern texts and material that later came to be incorporated into Jewish, Christian and Islamic religious texts.', null, 2, '{"operator": "AND", "items": [{"credits": 3.0, "department": null}]}'::jsonb),
    ('NMC381H1', 'Modern Islamic Thought', '24L', 'Survey of major intellectual trends in the Islamic tradition, particularly those identified with Middle Eastern Muslim thinkers, from the early 19th century to the present. Topics include reformism, modernism, hermeneutics, feminism, Islamism, and liberal and progressive trends in contemporary Muslim thought. Readings in English translation.', null, 2, '{"operator": "AND", "items": ["NMC103H1"]}'::jsonb),
    ('NMC384H1', 'Marking Time: Legal Issues and Personal Status in Judaism', '24S', 'This course will examine certain aspects of status and family law in Judaism, as well as Zoroastrianism, Eastern Christianity, and Islam. We will review some literature in legal theory to test its applicability to religious-based law. Our main topics include virginity (marital age, proof of virginity or its absence, rape or seduction of virgins, economics and theology of virginity); menstrual laws (impurity, punishment, sexuality, purification); mysticism (practitioners, purity requirements, theology); and sexuality (marriageability, prohibited partners, sex acts). Sectarian approaches to these legal issues will be examined, for example, how biblical law is interpreted in Qumran, by the rabbis, and how these topics are addressed by Zoroastrian law, the Eastern Church Fathers and the Four Schools in Islamic law.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('NMC386H1', 'Muslims, Christians, and Jews in the Ottoman Empire', '24L', 'Although ruled by a Muslim dynasty and frequently characterized as an Islamic empire, the Ottoman state was inhabited by diverse religious and ethnic populations, many of them non-Muslim. This course examines how the Ottoman Empire governed and organized its subjects, Muslims and non-Muslims alike, of various ethnic backgrounds. It explores the relations among these communities and their interactions with the state, raising questions about tolerance, co-existence, conflict, loyalty, and identity. By looking into a selection of topics from the wide territorial span of the Ottoman Empire (Anatolia, the Balkans, and the Arab Middle East) the course seeks to provide insights into the organization, functioning, and transformation of a multi-confessional state and society in the premodern and modern eras.', null, 3, null::jsonb),
    ('NMC387H1', 'Women, Gender, and Sexuality in the Ottoman Empire', '24L', 'The course explores key aspects of the history of women, gender, and sexuality in the Ottoman Empire from the early fourteenth century until the empire''s collapse over the course of the First World War. It examines the experiences of women of various social and religious backgrounds, and the transformation of concepts and expressions of sexuality. Topics include gender and law, the harem as a social and political institution, discourses of sexuality, reproductive politics, women''s movements, labour history, fashion, and gendered experiences of displacement, violence, and war.', null, 3, '{"operator": "AND", "items": [{"credits": 2.0, "department": null}]}'::jsonb),
    ('NMC388H1', 'The Rise of the Ottomans', '24L', 'A survey of the Ottoman Turks from their late 13th–early 14th century origins on the frontiers of the Seljuk, Mongol, and Byzantine empires to their establishment of an Islamic empire. Topics include the principalities known as beyliks that came into being in Anatolia as the above empires declined, the nature of the early Ottoman beylik, conquests in the Balkans, the destruction of the early Ottoman state by Timur and its rebirth, and Mehmed II''s conquest of Constantinople. Coverage includes Ottoman institutions, economy, society, and culture.', 'NMC377Y1', 3, null::jsonb),
    ('NMC389H1', 'The Ottoman Empire in its Classical Age', '24L', 'A survey of the Ottoman Empire in the 16th and 17th centuries. From the victory by Selim I the Grim over Safavid Iran and conquest of Syria and Egypt to the resplendent age of Süleyman the Magnificent to the internal and external challenges that forced transformation or decline. Topics include wars in Europe, the Mediterranean and Black Seas, and with Iran; internally, the rise of the harem and “sultanate of the women,” rebellions in Anatolia, military reform, religious controversies, and art and architecture. The endpoint is the Treaty of Karlowitz (1699) when the expansion of the empire ended.', 'NMC377Y1', 3, null::jsonb),
    ('NMC394H1', 'Persianate Art and Architecture', '24L', 'Covering art and material culture in the eastern Islamic lands from the late 13th century to the modern period. Objects from the collections of Islamic art in the Royal Ontario Museum will also be studied.', null, 1, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('NMC395H1', 'Iconography of the Art and Material Culture of the Islamic World', '24S', 'The art and material culture of the Islamic world is rich in iconography - from Persian paintings to Afghan war rugs - with complex layers of meaning that are not necessarily understood at first glance. Such imagery can be comprehended through numerous lenses, from pre-Islamic concepts and literary themes to politically-driven motivations or religious beliefs and practices. Through a series of case studies of examples of painting, ceramics, metalwork, textiles, and contemporary art, the course examines the meanings behind the iconography on objects from across the Middle East and Central Asia, dating from the medieval period to the present day.', null, 1, null::jsonb),
    ('NMC396H1', 'The Art of the Qur''an', '24L', 'The holy Qur''an, believed by Muslims to be the Word of God, has been a source of creative and artistic inspiration for Muslims around the world and through the ages. The language and interpretation of the Qur''an have engaged the minds of artists, craftspeople, and patrons of the arts as much as the minds of theologians and jurists. This course explores expressions of the Qur''an through a wide range of visual and material culture–from illuminated manuscripts to the use of the sacred text on coins, amulets, architecture, ceramics, metalwork, textiles, and modern and contemporary works of art. The course will include visits to the Royal Ontario Museum to examine Qur''ans in its Islamic collection.', null, 1, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('NMC398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC445H1', 'Sacred versus Secular Space: Mesopotamian Architecture in Context', '36L', 'When and where did the first buildings come about? Learn how some 10,000 years ago, the first permanent dwellings were constructed in the ancient Near East. Discover how the agricultural revolution and the domestication of animals resulted in the formation of villages during the Neolithic period (9,000–5,000 BC) with house types that grew in size and complexity. Observe how religious architecture evolved from simple, household-based cultic installations to large public complexes that dominated cities during the Uruk and Early Dynastic periods (4,000–2,300 BC). See how the rise and manifestation of powerful political leaders is reflected in the development, layout and decoration of their palaces. Beyond a typological approach to architecture, this course will also address challenges created by environmental conditions and limitations in available building materials. While focusing on Mesopotamia and Syria, it will also incorporate examples from Iran, Anatolia and the Levant.', null, 3, null::jsonb),
    ('NMC446H1', 'The Babylonian City', '24L', 'Ancient Mesopotamia is well known as the birthplace of some of the world''s earliest cities. This course investigates the physical form of the city in 2nd and 1st millennium BC Babylonia (southern Mesopotamia) as the setting for the daily activities of its inhabitants. It examines the key components of the Babylonian city: houses; neighbourhoods and city districts; palaces; temples and ziggurats; streets and alleys; shops and markets; city walls, gates, and moats, as well as canals, orchards and gardens. The course emphasizes the reading and critical evaluation of written sources in translation, including selected royal inscriptions, topographical texts, and legal and administrative documents. It also considers ways of approaching the study of ancient cities and addresses the integration of textual and archaeological evidence. The focus is on investigating the relationship between Babylonian city form and contemporary social structure.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC447H1', 'The Neo-Assyrian Empire', '24L', 'The course offers a detailed introduction to the Neo-Assyrian empire and how it functioned, based on study of a representative selection of written sources (in translation). It examines Assyrian kingship, imperial administration, and daily life as reflected in the texts, including the royal inscriptions, official correspondence, astrological reports, and everyday legal and administrative documents. The course studies a cross-section of Assyrian society taking into account various perspectives, from the king and his highest officials and court scholars to the lowest-ranking subjects and deportees. It also investigates the economic basis of the Assyrian empire, including taxation and tribute, booty from military conquest, specialist craft production, and agriculture. The course emphasizes the historical evaluation and interpretation of the primary written sources.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC449H1', 'Mesopotamian Society and Economy', '24L', 'This course presents a thematic overview of Mesopotamian society and economy from the third millennium to the 1st millennium BC. The emphasis is on critical evaluation of the primary sources (in translation), such as everyday legal contracts and the so-called “Laws”. It also explores different approaches to the study of ancient social structures and economies. Topics include: freedom, slavery, and social class; ethnicity; women, children, and the elderly; marriage, family, and household; crime and punishment, and the judicial system; the priesthood; palace and temple, private and state; merchants and trade; money, markets, and prices, and the question of whether there was a market economy; labour and wages; land ownership and tenure, and wealth and social inequality.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC450H1', 'Research Seminar on Ancient Jewish Literature', '24S', 'A seminar focusing on the critical analysis of the Hebrew Bible and related ancient Jewish texts. Literary genre and critical topics will vary according to instructor''s research interests. Focus will be given to developing research skills by working with accepted critical methodologies. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('NMC452H1', 'Iranian Modernity', '36S', 'This course explores competing conceptions of Iranian modernity within a comparative historical framework on “multiple modernities.” A major theme is the exploration of the temporality and historicity in discussions of Iranian modernity.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC454H1', 'Mapping the Ottoman World', '24S', 'This highly visual course explores the history of cartography in the Ottoman World between the 15th and 20th centuries. Focusing on the social life of images, it examines how the Ottomans and their rivals governed the territory through navigation, astronomy, architecture, property, and geographical surveys. From religious to scientific visualizations, maps make history. Yet not long ago, they were rare and strange technical objects, and their value as historical source has shifted again and again. Each week illuminates moments of this story by centering on a topic including empire, image, boundaries, print, reform, visualization, infrastructure, spatial literacy, map wars, and verticality.', 'NMC471H1 (Advanced Topics in Near and Middle Eastern Civilizations: Mapping the Ottoman World), offered in Fall 2021', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('NMC459H1', 'Advanced Data Science Applications in Archaeology', '12P/24S', 'Digital technology and “big data” are transforming not only the ways in which archaeologists present and communicate their research, but also increasingly the ways they collect and analyze data. Modern archaeology is also becoming progressively more multi-disciplinary, and reliant on the analysis of growing bodies of disparate forms of data, both archaeological data and data from related fields. This course exposes students to common approaches to the analysis of archaeological data (e.g. settlement scaling theory, summed probability distributions, agent-based modelling, etc.) and helps them develop hands-on skills in these critical techniques in archaeological data analysis. Where possible, this course will focus on case studies from the Near Eastern world.', null, 3, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["NMC268H1", "ARH312Y1"]}]}'::jsonb),
    ('NMC460H1', 'The Archaeology of Borders in Egypt and the Ancient Near East', '24S', 'Borders impact all kinds of aspects of our daily lives, and the same was true for peoples in the ancient Near East. This course will analyze premodern societies from the perspective of these boundaries, from “natural” geographic boundaries to the strict registers of action that define the aesthetics of Pharaonic and Near Eastern art. Using cutting edge theoretical approaches developed by anthropologists, geographers, art historians, and archaeologists to study modern (and ancient) border-making, this course will investigate Pharaonic and Near Eastern societies through the prism of the political, cultural, administrative, and economic boundaries they created and maintained.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('NMC461H1', 'The History and Archaeology of the Horn of Africa and South Arabia', '24S', 'The cultures of the Horn of Africa and South West Arabia, separated by the Red Sea, have long been intertwined. This course explores the history and archaeology from the emergence of the hominids in Ethiopia, to the rise of the Sabean and Axumite kingdoms, until the Middle Ages, highlighting their interactions and the roles they played in the development of their respected cultures.', 'NMC461Y1', 3, '{"operator": "OR", "items": ["NMC260H1", "NMC262H1"]}'::jsonb),
    ('NMC462H1', 'Polarized-light Microscopy in Archaeology I: Foundations', '24L/24P', 'This course provides students with training in the use of polarized-light microscopy in the examination of archaeological materials, particularly pottery (ceramic petrology). Students will apply the knowledge they gain from lectures to hands-on work with materials in the lab, covering instruction in crystallography, optics, mineralogy, lithology, and other aspects of the petrology of ceramics and other materials. Labs comprise eight three-hour sessions during the term, working with the polarized-light microscope to examine and analyze thin-sections. No prior knowledge of geology is required. Students should plan to take  NMC470H1 Polarized-light Microscopy in Archaeology II: Applications, in the following term to complete their training.', 'NMC462Y1', 5, '{"operator": "AND", "items": ["NMC264H1"]}'::jsonb),
    ('NMC463H1', 'Warfare: The Archaeology of Conflict in the Ancient Near East', '36L', 'When did humans start fighting each other, and how far back can we trace the history of warfare? This course investigates the origin, nature, and manifestation of military conflicts in the ancient Near East and studies their impact on political, economic, and social developments in the region. Following a review of the relevant terminology (e.g., “warfare” vs “skirmish”) in archaeological literature, we will investigate the archaeological and historical data for a time span that extends from 9,000 to 300 BC. Evidence from archaeological sites (notably violent destructions of ancient settlements) will be compared with available artistic representations of warfare in sculpture, reliefs, inlays, and glyptics, complemented by textual accounts. While the course focuses on Mesopotamia, evidence from Syria, Turkey, Iran, the Levant, and Egypt will also be included.', null, 3, '{"operator": "AND", "items": ["NMC260H1"]}'::jsonb),
    ('NMC464H1', 'The Archaeology of Stuff at the ROM', '36P', 'Hands-on analysis of actual materials from the Middle and Near East, including Egypt, Iraq, Iran, Syria, and Turkey. Students learn the techniques by which archaeologists understand objects from the past: what they are made of, how they were made, and what they reveal about the people who made them.', 'NMC369Y1', 1, '{"operator": "AND", "items": ["NMC264H1"]}'::jsonb),
    ('NMC465H1', 'Ceramic Analysis', '6P/36S', 'A survey of methods of classification and analysis (form, fabric and style) involved in the study of archaeological ceramics, and the use of ceramics to infer patterns of production, distribution, and social organization; linking research questions with appropriate analytical techniques.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["ARH312Y1", "NMC260H1", "NMC262H1", "NMC264H1", "NMC360H1", "NMC361H1", "NMC464H1"]}]}'::jsonb),
    ('NMC466H1', 'Near Eastern Ceramics', '36S', 'An introduction to the basic corpus of Near Eastern ceramics, from the invention of pottery production in the Neolithic until the Persian period, utilizing existing collections at the University and in the Royal Ontario Museum.', null, 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"operator": "OR", "items": ["ARH312Y1", "NMC260H1", "NMC262H1", "NMC264H1", "NMC360H1", "NMC361H1", "NMC464H1", "NMC465H1"]}]}'::jsonb),
    ('NMC467H1', 'Seminar in Egyptian Archaeology I', '24S', 'Seminar focuses on the social and cultural development of Egypt from the Predynastic Period through the Middle Kingdom, engaging with major theories regarding social complexity, state formation, urbanism, social organization, and regionalism. An independent research project and hands-on experience with artifacts at the ROM are important features of the course.', null, 1, '{"operator": "OR", "items": ["NMC101H1", "NMC343H1"]}'::jsonb),
    ('NMC468H1', 'Seminar in Egyptian Archaeology II', '24S', 'Seminar focuses on the social and cultural development of Egypt from the Middle Kingdom through the Ptolemaic Period, engaging with major theories regarding urbanism, ethnicity, core-periphery relationships, cultural interaction, and social organization. An independent research project and hands-on experience with artifacts at the ROM are important features of the course.', null, 1, '{"operator": "OR", "items": ["NMC101H1", "NMC344H1"]}'::jsonb),
    ('NMC469Y1', 'Medieval Middle Eastern Ceramics', '72S', 'An introduction to the ceramics of the Middle or Near East from the time of Alexander until recent times. A particular emphasis will be the elite glazed wares of the mediaeval and Islamic periods. Apart from providing a history of the production of ceramics and their social and archaeological context, this course is intended to train archaeologists and art-historians in the fundamental field recognition and identification of the various types and their production origins, and the course will rely heavily on the collections of the ROM.', null, 3, '{"operator": "AND", "items": ["NMC260H1", "NMC262H1", {"credits": 0.5, "department": null}]}'::jsonb),
    ('NMC470H1', 'Polarized-light Microscopy in Archaeology II: Applications', '24L/24P', 'This course explores further applications of polarized-light microscopy in the examination of archaeological materials, particularly pottery (ceramic petrology). The focus is on foundational research and case-studies of materials from around the world with particular attention to material culture from the Middle East, Central America, and East Asia, where University of Toronto researchers have worked, ranging in date from the Neolithic period to the modern day. Class and lab discussions will include critical examination of the application and integration of ceramic petrology in archaeological research design and how petrology can address relevant research questions successfully. Labs comprise eight three-hour sessions during the term, working with the polarized-light microscope to examine and analyze thin-sections.', 'NMC462Y1', 5, '{"operator": "AND", "items": ["NMC462H1"]}'::jsonb),
    ('NMC471H1', 'Advanced Topics in Near and Middle Eastern Civilizations', '24S', 'An advanced seminar organized around readings on a topic selected by the instructor.', null, 3, null::jsonb),
    ('NMC472H1', 'Theory & Method in Middle East Studies', '24S', 'Examines current theoretical and methodological trends in the study of the Near/Middle East. A seminar course, it consists of presentations, discussions, lectures, guest speakers, and documentaries. No previous knowledge of methodology required. Special attention will be paid to the politics, culture, political economy, gender, and ethics of various research practices. Intended for 4th year students only.', null, 3, null::jsonb),
    ('NMC473H1', 'Intellectuals of the Modern Arab World', '24S', 'The course is designed to re-examine the role of intellectuals in the Arab world and political events that shaped their thinking. It introduces the life and thought of some leading thinkers of the Arab world and relates their thought to the lived experience of political, social, economic and cultural change in the Middle East.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": ["NMC278H1", "NMC377Y1", "NMC378H1"]}]}'::jsonb),
    ('NMC474H1', 'The Archaeology of Death', '36S', 'Death is an unavoidable part of the human experience, and each culture has its own unique ways of handling the loss of family and community members and conceptualizing the relationships between the living and the dead. This course represents an intensive education in the archaeology of death. Participants in this class will read a variety of theoretical and methodological literature outlining several approaches to reconstructing the ways that people have disposed of the dead throughout history, and will use these frameworks to examine in detail the primary archaeological data for mortuary practices from sites in the ancient Near East.', null, 1, '{"operator": "OR", "items": ["ANT200Y1", "NMC260H1", "NMC262H1"]}'::jsonb),
    ('NMC475H1', 'Orientalism & Occidentalism', '24S', 'This course probes the contemporaneous formation of modern Oriental Studies in Europe and the emergence of discourses on Europe (Ifranj/Farang) in the Middle East from the eighteenth century to the present. Special emphasis will be devoted to encounters between scholars in Western Europe, Iran, India, and the Ottoman Empire. This seminar-style course explains that Orientals gazed and returned the gaze, and in the process of cultural looking, they, like their Occidental counterparts, exoticized and eroticized the Farangi-Other. In the interplay of looks between Orientals and Occidentals, there was no steady position of spectatorship, no objective observer, and no aperspectival position. Intended for upper year students.', null, 3, null::jsonb),
    ('NMC476H1', 'Politics of Archaeology in the Modern Middle East', '24S', 'This course examines the role nineteenth and twentieth-century archaeology played in Middle Eastern politics, the culture of colonialism and in nationalist struggles. The course will first familiarize the students with the diplomatic and intellectual context of the formation of archaeology as a field of study in Europe and analyse the role archaeology played in the production of knowledge about the Middle East. Next, the course will examine the archaeological practices on the ground (and underground) and inquire what happens in the contact zone between foreign and local archaeologists. Finally, we will trace the ways in which emergent nationalist discourse challenge, appropriate and imitate the historical narratives of Western archaeology.', null, 3, null::jsonb),
    ('NMC477H1', 'Modern Turkey', '24S', 'The course examines the history of modern Turkey from the beginning of the 20th century until the present day. Topics include transition from empire to nation-state; the establishment of the Turkish republic; the Kemalist reforms and legacy; nationalism and nation-building; Islam and politics; gender and sexuality; as well as recent political, social, and cultural developments. The course seeks to situate the history of Turkey in a broader regional context and introduces students to some historiographical debates. In seminar discussions, students are encouraged to explore topics from a critical post-nationalist perspective and to think about current events in a historical context.', null, 3, null::jsonb),
    ('NMC478H1', 'Modern Arab Societies', '24S', 'A weekly seminar built around thematic readings of social and economic history of the modern Arab world. Sometimes, the course is geographically extensive, encompassing the predominantly Arabic-speaking lands of North Africa and the Middle East from Morocco in the west to Iraq in the east. At other times, the course focuses on a more narrowly defined geographic region—one country or a group of countries in the Arabic-speaking lands. Readings and discussions emphasize the experiences of broad sectors of the population, not just of elites. This framework of “history from below” also invites scrutiny of historically-marginalized populations (“subalterns”), or at least of silences in the literature about these populations.', null, 3, '{"operator": "AND", "items": ["NMC378H1"]}'::jsonb),
    ('NMC479H1', 'Nationalism in the Arab World', '24S', 'A seminar that critically examines the types and varieties of national expression in Arab societies of the Middle East and North Africa, through a reading of common texts and students'' individual research projects.', null, 3, '{"operator": "AND", "items": ["NMC378H1"]}'::jsonb),
    ('NMC480H1', 'Structural Development of the Iranian Languages', '24S', 'This interdisciplinary course focuses on the structural development and contrastive analysis of Iranian languages including Dari, Farsi, Tajiki, Balochi, Kurdish, Pashto, and Zazaki. The lectures begin with an overview of ancient and medieval Iranian languages and then describe modern Iranian languages'' historical and structural development. The course also examines the role of language in maintaining cultural identity and demonstrates the type and mechanism of the development of Iranian languages. The lecture materials are based on texts and articles written by theoretical linguists, sociolinguists, typologists, and descriptive and historical linguists.', 'NML463H1', 1, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC484H1', 'Gender Issues in Jewish Law', '36S', 'Among the topics addressed in this course in various years are the requirement for women divorced or widowed (either from betrothal or marriage) to wait three months before remarriage to determine paternity or for pregnant or nursing women to protect the fetus or infant; legal disabilities for women in marriage and divorce (consent, unilateral acquisition, power differentials, exit options); legal status according to age (fetus, infant, before and after age six, approaching legal majority, legal majority, anomalies); sexuality (age, sexual acts and their legal repercussions, prohibitions, consent, intergenerational sexual connections, homosexuality); rabbinic ordination of women in the various streams of Judaism; and abortion (contraception, status of embryo or fetus, viability, reasons). These issues will be discussed in terms of gender and modern law.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('NMC491H1', 'Mesopotamian Material Culture: Art versus Artifact', '36L', 'What is an artifact, and to what degree does it represent art? At what point in the evolution of ancient human society does art emerge? What does it express, what is its purpose, and who are the agents that create and propagate it? This course addresses these questions by examining artifacts from the Palaeolithic to the Iron Age (15,000-300 BC). Students will learn to categorize works of ancient Near Eastern art using descriptive (materials, size, object type) as well as interpretive (iconography, style, themes) parameters, in order to engage critically with art-historical studies. Techniques of reading visual narratives will be exemplified by discussing selected examples in detail, showing ways of identifying a messenger and the message that they are trying to convey, the selective inclusion or omission of elements within a visual narrative, and the possible propagandistic intent in doing so.', null, 1, null::jsonb),
    ('NMC495Y1', 'Independent Studies', null, 'The student must obtain the consent of an appropriate full-time NMC faculty member to supervise the proposed topic, which is subject to approval by the Associate Chair, Undergraduate. The course application form is available from the NMC Undergraduate Administrator. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC496H1', 'Independent Studies', null, 'The student must obtain the consent of an appropriate full-time NMC faculty member to supervise the proposed topic, which is subject to approval by the Associate Chair, Undergraduate. The course application form is available from the NMC Undergraduate Administrator. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC497H1', 'Independent Studies', null, 'The student must obtain the consent of an appropriate full-time NMC faculty member to supervise the proposed topic, which is subject to approval by the Associate Chair, Undergraduate. The course application form is available from the NMC Undergraduate Administrator. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('NMC499Y1', 'Senior Thesis', null, 'A 40-60 page (15,000-20,000 word) research paper (100% of the final mark) written under the supervision of a full-time NMC faculty member. Not eligible for CR/NCR option.', 'NMC495Y1/ NMC496H1/ NMC497H1 may not be taken in the same session', null, null::jsonb),
    ('NML110Y1', 'Elementary Standard Arabic', '96L/24T', 'This course is designed for students with no prior knowledge of Arabic. It places equal emphasis on the development of all language skills: reading, writing, listening, and speaking. The learning philosophy underlying this approach is that proficiency in a foreign language is best achieved through consistent, deliberate, and systematic practice. From the outset, students are strongly encouraged to develop the habit of consistently practicing learned material.', 'Native speakers/ NML210Y1', 1, null::jsonb),
    ('NML155H1', 'Elementary Modern Hebrew I', '48L', 'See  MHB155H1 in Religion.', null, null, null::jsonb),
    ('NML156H1', 'Elementary Modern Hebrew II', '48L', 'See  MHB156H1 in Religion.', null, null, null::jsonb),
    ('NML210Y1', 'Intermediate Standard Arabic I', '96L/24T', 'This course assumes active knowledge of the content covered in NML110Y. It places equal emphasis on the development of all language skills. As the course progresses, students are introduced to the fundamentals of Arabic morphology and syntax. This is achieved through analysis of texts covering a wide range of topics. By the end of the course, students are expected to achieve upper intermediate level of proficiency.', 'Native speaker. Priority enrollment will be given to declared NMC majors/specialists.', 1, '{"operator": "OR", "items": ["NML110Y1"]}'::jsonb),
    ('NML211H1', 'Arabic Poetry: the Abbasid Period', '24S', 'Read the classics in the original Arabic! Learn how to decipher a poem on your own and how to identify the meters. We will read famous and lesser-known Arabic poems composed between 750-1258 CE, including poems by Abu Nuwas, Abu al-Atahiya, al-Buhturi, al-Mutanabbi, Abu Firas, al-Maʿarri, as well as various muwashshahat. Themes include love, piety, battle, carousing, poverty, and grief. We will focus on close reading, historical context, and the historical development of genres and styles over time. Heritage speakers of Arabic are encouraged to register; please contact the intructor to confirm your Arabic level before the start of class.', 'NML413H1', 1, '{"operator": "AND", "items": ["NML310Y1"]}'::jsonb),
    ('NML212H1', 'Classical Arabic Prose', '24S', 'Read the classics in the original Arabic! This class surveys the rich and varied literary prose traditions in the Arabic language from early Islam to the Mamluk period, including an early Arabic version of Majnūn Laylā, the Maqāmāt, al-Jāḥiẓ, Ibn Qutayba, and stories from the 1001 Nights. The course focuses on developing reading skills specific to classical Arabic texts, and on developing an ability to analyze the themes, literary techniques, genres, and ideas within those texts. Throughout, we will seek an understanding of the historic notion of adab as a concept that overlaps with, but is also distinct from, the modern concept of literature. Heritage speakers of Arabic are encouraged to register; please contact the instructor to confirm your Arabic level before the start of class.', 'NML412H1', 1, '{"operator": "AND", "items": ["NML310Y1"]}'::jsonb),
    ('NML220Y1', 'Introductory Aramaic', '72S', 'Introduction to Aramaic grammar. Readings from biblical Aramaic.', null, 1, '{"operator": "AND", "items": ["NML250Y1"]}'::jsonb),
    ('NML230H1', 'Elementary Coptic I', '48S', 'Introduces the student to the last stage of the Egyptian language, written mostly in Greek characters. The course will first concentrate on the grammar of the language and go on to read short texts.', null, 1, null::jsonb),
    ('NML231H1', 'Elementary Coptic II', '48S', 'A continuation of  NML230H1.', null, 1, null::jsonb),
    ('NML240Y1', 'Introduction to Middle Egyptian', '72S', 'This course introduces students to the hieroglyphic script and the classical form of the Ancient Egyptian language. After the basic elements of grammar are mastered, the class will begin reading simple hieroglyphic texts.', null, 1, null::jsonb),
    ('NML250Y1', 'Introductory Biblical Hebrew', '24T/72S', 'An introduction to biblical Hebrew prose. Grammar and selected texts. For students with no previous knowledge of Hebrew.', 'Those who have completed Grade 8 Hebrew (or Grade 6 in Israel)', 1, null::jsonb),
    ('NML255H1', 'Intermediate Modern Hebrew I', '48L', 'Intensive study of written and spoken Hebrew.', 'Those who have completed Grade 8 Hebrew (or Ulpan level 2 in Israel),  MHB255H1', 1, '{"operator": "OR", "items": ["MHB156H1", "NML156H1"]}'::jsonb),
    ('NML256H1', 'Intermediate Modern Hebrew II', '48L', 'Continued intensive study of written and spoken Hebrew.', 'Those who have completed Grade 8 Hebrew (or Ulpan level 2 in Israel),  MHB256H1', 1, '{"operator": "OR", "items": ["NML255H1", "MHB255H1"]}'::jsonb),
    ('NML260Y1', 'Introductory Persian', '72L/24T', 'This course is for students who have minimal or no prior knowledge of Persian focusing on reading, writing and conversation. Students start by learning how to write and pronounce the sound and alphabet, how to connect letters to form basic vocabulary in Persian in order to express basic ideas orally and in writing; then they develop their language comprehension through expanding their vocabulary and grammar. By the end of the course, students'' skills in listening, speaking, reading, and writing in Persian improves and they should be able to read, write and translate sentences in Persian at intermediate low level.', 'Native speakers,  PRS210Y5,  PRS210H5,  PRS211H5', 1, null::jsonb),
    ('NML270Y1', 'Introductory Turkish', '96L', 'This course is designed to provide an introduction to Turkish for learners with no previous experience with the language. A variety of speaking, listening, reading, and writing activities will be included to develop both spoken and written language skills. By the end of the course, students will be able to carry out basic conversations in Turkish in everyday social encounters, have a grasp of the basics of the Turkish grammar, and understand elementary texts such as simple excerpts from news articles or literary works. They will also have gained a basic understanding of the cultural contexts in which Turkish is spoken.', 'Native speakers', 1, null::jsonb),
    ('NML305Y1', 'Introduction to Akkadian', '48S', 'Introduction to Old Babylonian. Grammar and the reading of selected texts.', null, 1, null::jsonb),
    ('NML310Y1', 'Intermediate Standard Arabic II', '96L', 'This course assumes active knowledge of the content covered in  NML210Y1. As the course progresses, students are introduced to increasingly complex morphological and syntactic patterns of Arabic. This is achieved through analysis of texts covering a wide range of genres. By the end of the course, students are expected to achieve advanced level of proficiency.', 'Native speakers. Priority enrollment will be given to declared NMC majors/specialists.', 1, '{"operator": "OR", "items": ["NML210Y1"]}'::jsonb),
    ('NML320H1', ' Targum - Aramaic Bible Translations', '36S', 'This course is an intensive study of various Aramaic Bible translations (Targumim) to the Pentateuch: Onkelos, Pseudo-Jonathan, Neophyti, Samaritan and Syriac (both transliterated into Hebrew letters), and Fragment Targumim. A comparative study of the Targumim will be made in reference to vocabulary, syntax, verb usage, and translation strategies. We will address their relationship to the Palestinian midrashim. Students will learn to use the online Comprehensive Aramaic Lexicon and the relevant dictionaries and grammars. The texts studied will be from legal sections of the Pentateuch, generally from Deuteronomy on levirate marriage or war captives, Exodus on abortion and personal injury, as well as narrative sections from Genesis such as the Garden of Eden, the binding of Isaac, and the accounts of the Matriarchs.', null, 2, '{"operator": "OR", "items": ["NML220Y1"]}'::jsonb),
    ('NML340Y1', 'Intermediate Middle Egyptian', '72S', 'A continuation of  NML240Y1, in which the student is exposed to a wide range of hieroglyphic texts in the Middle Egyptian dialect. Sources of historical, literary, religious, and economic significance will be studied. The grammar and syntax covered in  NML240Y1 are reviewed intensively.', null, 1, '{"operator": "AND", "items": ["NML240Y1"]}'::jsonb),
    ('NML350H1', 'Intermediate Biblical Hebrew I', '48S', 'A continuation of the study of ancient Hebrew grammar and texts. Focus is given to covering a wide variety of genres, e.g., narrative, chronicle, genealogy, oracle, prayer, hymn, and proverb.', null, 1, '{"operator": "AND", "items": ["NML250Y1"]}'::jsonb),
    ('NML351H1', 'Intermediate Biblical Hebrew II', '48S', 'A continuation of the study of ancient Hebrew grammar and texts. Focus is given to covering a wide variety of genres, e.g., narrative, chronicle, genealogy, oracle, prayer, hymn, and proverb.', null, 1, '{"operator": "AND", "items": ["NML350H1"]}'::jsonb),
    ('NML355H1', 'Advanced Modern Hebrew I', '48S', 'Advanced intensive study of written and spoken Hebrew.', 'OAC Hebrew,  MHB355H1', 1, '{"operator": "OR", "items": ["MHB256H1", "NML256H1"]}'::jsonb),
    ('NML356H1', 'Advanced Modern Hebrew II', '48S', 'Continued advanced intensive study of written and spoken Hebrew.', 'OAC Hebrew,  MHB356H1', 1, '{"operator": "OR", "items": ["NML355H1", "MHB355H1"]}'::jsonb),
    ('NML357H1', 'Legends of the Jews (Aggadah)', '24S', 'This course is an introduction to the exegetical methods of the rabbinic sages in their analysis of biblical texts, with special attention to issues of intertextuality. After a quick overview of the genres of midrashic literature, we shall examine the midrashic methods used to transition from the biblical text to the midrash. Our main focus will be on Original Sin in the Garden of Eden and its repercussions. Our primary texts will be Bereishit Rabbah, Avot de Rabbi Natan, and Alphabeta deBen Sirah. We shall follow these midrashim in other midrash collections such as Midrash HaGadol, Tanhuma, Bereishit Rabbati, and Aggadat Bereishit. The motif of Original Sin has had significant reverberations in Judaism and Christianity and societies influenced by these traditions.', null, 2, null::jsonb),
    ('NML358H1', 'Middle Hebrew: Mishnah and Tosefta', '24S', 'This course introduces Mishnah and Tosefta which are two of the three foundational documents of Middle Hebrew I from the Tannaitic period ending circa 250 CE in the Galilee. In addition to studying specific features of this level of Hebrew (e.g. syntax, grammar, vocabulary), we shall examine these compositions independently and analyze their interaction (textuality and intertextuality). Students will read recent scholarly literature on these documents and their relationship to each other and to orality. Students will be introduced to the manuscripts of these documents and the variant readings will be studied philologically. Decisions on original readings will be made. Finally, we shall explore redaction and source critical issues allowing identifications of anonymous statements with specific authorities (sages). The Tractate may vary from year to year.', null, 2, null::jsonb),
    ('NML359Y1', 'Eastern Aramaic – Babylonian Talmud', '72S', 'This course introduces the student to Talmudic texts through selections from a particular tractate for representative study. We shall study the Mishnah of the chapter in preparation for the Talmud. Recognition of the dialogic structure of the legal discussions centered on the Mishnah and its elucidation is emphasized. The classical commentaries (Rashi, Tosafot, R. Hananel), the use of dictionaries, concordances, biographies of sages, parallels and other sources will gradually become familiar to the student as aids in understanding the text under consideration. A brief presentation of the essential features of Babylonian Aramaic will be included in the course to facilitate study. Students will also be taught to make use of the Bar Ilan Responsa Project, the Lieberman database, and the Friedberg Jewish Manuscript Society database. We shall also discuss redactional issues as they appear.', null, 2, null::jsonb),
    ('NML360Y1', 'Intermediate Persian', '96L', 'This course is an intermediate/advanced level of Persian language for students who passed  NML260Y1 or demonstrate commensurate Persian skills. The course continues to develop students'' Persian language knowledge by focusing on more complex readings, writing, grammatical structure, translation, audio/visual, and conversational activities such as group discussion, language games, movies, dialogue, and playing roles at an advanced level. By the end of this course, students are able to reach the intermediate high/advanced level of proficiency in Persian. The course also serves as preparation for courses on classical and contemporary Persian literature.', 'Native speakers,  PRS310H5', 1, null::jsonb),
    ('NML362Y1', 'Middle Persian (Pahlavi)', '48L', 'An introduction to the grammar and syntax of Middle Persian, or Pahlavi, language; the special script it was written in; and the connections of Pahlavi to Old Persian and New Persian languages. Knowledge of Pahlavi provides access to the most important Zoroastrian religious texts, and the epic and wisdom literature composed during the period of the Sasanian empire (3rd–7th centuries CE) and early Islamic Iran (8th–10th centuries CE). Students will read excerpts, in the original Pahlavi, from such works as Arda Wiraz Namag (Book of the Righteous Wiraz, describing his journey to heaven and hell), Karnamag i Ardakhshir i Pabagan (Chronicle of Ardakhshir, Son of Pabag, narrating the deeds of the first Sasanian king), and Bundahishn (Primordial Creation, on Zoroastrian cosmology).', null, 1, null::jsonb),
    ('NML370Y1', 'Intermediate Turkish', '96L', 'This course is designed for students who have already completed  NML270Y1 Introductory Turkish or have an equivalent level of proficiency in Turkish. It aims to expand students'' communicative skills, grammatical knowledge, and vocabulary. A variety of intermediate-level speaking, listening, reading, and writing activities will be included to further develop both spoken and written language skills. By the end of the course, students will be able to read, understand, and translate various authentic texts of intermediate difficulty. They will be able to write short essays and talk about a wide range of general topics. They will also have gained a deeper understanding of the cultural contexts in which Turkish is spoken. The course also serves as a preparation for the advanced study of Turkish.', 'Advanced speakers of Turkish', 1, '{"operator": "OR", "items": ["NML270Y1"]}'::jsonb),
    ('NML371H1', 'Conversational Turkish: Oral Communication in Context', '24S', 'This course is designed for students who wish to consolidate their communicative and conversational skills in Turkish. Emphasis is placed on improving listening and speaking skills in diverse formal and informal contexts to prepare the students for real-life oral communication situations. Students will gain experience with different styles and registers while also improving their grasp of the Turkish culture.', 'Permission of instructor required for native speakers', 1, '{"operator": "OR", "items": ["NML270Y1"]}'::jsonb),
    ('NML372H1', 'Turkish Language through Television, Film, and Media', '24S', 'This dynamic Turkish language course aims to enhance students'' proficiency through Turkish television series which have gained significant international popularity in recent years and through Turkish films from both classical and modern “Yeşilçam”, the Turkish cinema industry. The course will also familiarize the students with the use of the Turkish language in traditional and social media. By the end of the course, students will have improved their receptive, expressive, and interactional skills in spoken and written modalities.', 'Native speakers', 1, '{"operator": "AND", "items": ["NML270Y1"]}'::jsonb),
    ('NML380H1', 'Introduction to Ge''ez (Classical Ethiopic)', '36L', 'This course covers the essentials of Ge''ez (Classical Ethiopic) grammar, and introduces students to Ge''ez texts of elementary to intermediate difficulty. Designed for students with no previous knowledge of Ge''ez.', null, 1, '{"operator": "OR", "items": ["NML110Y1", "NML220Y1", "NML250Y1"]}'::jsonb),
    ('NML381H1', 'Intermediate Ge''ez', '36L', 'This course continues the study of Ge''ez (Classical Ethiopic) grammar and progresses to a survey of classical Ge''ez literature. Linguistic connections to Amharic and Tigrinye will also be introduced.', null, 1, '{"operator": "OR", "items": ["NML380H1"]}'::jsonb),
    ('NML405Y1', 'Selected Standard Babylonian Texts', '48S', 'This intermediate Akkadian course is devoted to the study of the literary Akkadian dialect of the late second and first millennia, usually known as Standard Babylonian. Students will read excerpts of literary texts and royal inscriptions in R. Borger''s Babylonisch-Assyrische Lesestücke and eventually proceed to more ambitious compositions such as The Annals of Sennacherib and Enuma Elish. Students are also expected to deepen their knowledge of the NeoAssyrian cuneiform script. (Offered in alternate years)', null, 1, '{"operator": "AND", "items": ["NML305Y1"]}'::jsonb),
    ('NML410Y1', 'Advanced Standard Arabic', '96S', 'This course assumes active knowledge of the content covered in NML310Y. Its goal is to strengthen the students reading and writing skills, refine their knowledge of syntax and morphological patterns, and enrich their cultural background. This is achieved through analysis of sophisticated authentic texts covering a wide range of genres. In addition, Classical Arabic literary texts will be incrementally introduced. By the end of the course, students are expected to reach a superior level of proficiency.', 'Native speakers.', 1, '{"operator": "OR", "items": ["NML310Y1"]}'::jsonb),
    ('NML411H1', 'Media Arabic', '24S', 'This course familiarizes advanced students of Arabic with structural properties, styles, and discourse features of the language used in the Arabic media. Class time is devoted to analysis of authentic texts covering a wide range of topics and drawn from various online media outlets.', 'Native speakers of Arabic must obtain permission of instructor.', 1, '{"operator": "OR", "items": ["NML310Y1"]}'::jsonb),
    ('NML415H1', 'The Arabic Short Story', '24S', 'This course examines the origins and development of the modern Arabic short story as a literary genre by reading selected works in Arabic of major figures in the genre. The course historicizes the emergence of the short story, exploring the genre''s consolidation as a major literary form in Arabic in the early 20th century. As part of an exploration of modern narrative in Arabic, students will read literary criticism that theorizes the emergence of modern Arabic narrative prose, paying close attention to questions of language, form, style and theme. The course also focuses on issues such as innovations in narrative technique, plot structure, complexity of characterization, and point of view. Authors include Mahmud Tahir Lashin, Yusif Idris, Zakariyya Tamir, Ghada al-Samman, Hanan al-Shaykh, and Fu''ad al-Takarli.', null, 1, '{"operator": "OR", "items": ["NML310Y1"]}'::jsonb),
    ('NML420Y1', 'Western Aramaic – Jerusalem Talmud', '72S', 'The Talmud of the Land of Israel, also called Talmud Yerushalmi or Palestinian Talmud, is written in a mixture of Jewish Western Aramaic and Middle Hebrew. It is the principal document of the Land of Israel in Late Antiquity. The course examines the legal argumentation, terminology and language which differ from those of the Babylonian Talmud. Recognition of the dialogical structure of the legal discussions concerning the Mishnah and its elucidation will be emphasized. Terminology, grammar, and syntax of Western Aramaic will be addressed. We shall also investigate when the text uses Hebrew versus Aramaic. Students will be taught the use of the Bar Ilan Responsa Project and the Lieberman bibliographic database. Close attention will be paid to its relationship to Tosefta.', null, 2, null::jsonb),
    ('NML421Y1', 'Classical Syriac', '48S', 'This course is primarily a reading course in Syriac literature with reference to specific points in grammar and syntax as contrasted with Aramaic. The texts are read with reference to the history of Syriac literature.', null, 1, '{"operator": "AND", "items": ["NML220Y1"]}'::jsonb),
    ('NML440H1', 'Ancient Egyptian Historical Texts', '36S', 'This is an advanced language seminar that introduces the student to the analysis, in terms of both language/grammar and content, of Ancient Egyptian texts of historical significance. Texts from the periods of the Old Kingdom up to the Late Period will be studied, and all texts will be read in the (mostly Middle Egyptian) original. Particular attention will be paid to the cultural and social context of the texts, and questions such as how to best define "historical texts," and to what extent literary texts may be used as historical sources, will be discussed.', null, 1, '{"operator": "AND", "items": ["NML340Y1"]}'::jsonb),
    ('NML441H1', 'Ancient Egyptian Religious and Funerary Texts', '36S', 'This is an advanced language seminar that introduces the student to the analysis, in terms of both language/grammar and content, of texts that elucidate ancient Egyptian religious conceptions. Texts from all periods of Pharaonic history will be studied and all texts will be read in the original. While the focus will be on texts from funerary contexts, for which the most complete sources can be found, cultic, magical, and theological sources will also be studied.', null, 1, '{"operator": "AND", "items": ["NML340Y1"]}'::jsonb),
    ('NML442Y1', 'Late Egyptian Texts', '72S', 'The course introduces students to the Late Egyptian dialect attested from the New Kingdom and spanning the period from ca. 1300 to 700 BCE. Students will be introduced to grammar, syntax, and orthography through readings of original texts; these will include stories, letters, business documents, and formal inscriptions. Standard grammars and dictionaries are supplemented by the instructor''s notes and handouts. Students will also be provided a basic introduction to the hieratic script through contemporary manuscripts.', null, 1, '{"operator": "AND", "items": ["NML240Y1"]}'::jsonb),
    ('NML443H1', 'Demotic I', '24L/24S', 'Demotic refers to both a stage of the ancient Egyptian language and the associated cursive script, which was in use for over a millennium (from the 7th century BCE to the 5th century CE). Various types of texts were written in Demotic, ranging from epic tales, scientific treatises, and religious texts to court documents, letters, and tax receipts. This course aims to introduce students to Demotic grammar and script. A small selection of original texts will be read once the grammar review is completed.', null, 1, '{"operator": "OR", "items": ["NML340Y1", "NML442Y1"]}'::jsonb),
    ('NML444H1', 'Demotic II', '36S', 'The course aims at improving reading proficiency in Demotic by studying a wide array of different text genres in original, including literary, para-literary, religious and documentary texts written in early, middle, and late Demotic. This will familiarize students with the grammatical, paleographical, and orthographical developments of the language.', null, 1, '{"operator": "AND", "items": ["NML443H1"]}'::jsonb),
    ('NML450H1', 'Advanced Biblical Hebrew', '24S', 'Continuation of the study of Biblical Hebrew language. Combination of reading more advanced texts and Hebrew composition exercises. Introduction to the standard reference works for advanced study of the phonology, morphology, syntax, and semantics of Biblical Hebrew.', null, 1, '{"operator": "OR", "items": ["NML350H1", "NML351H1"]}'::jsonb),
    ('NML452H1', 'Halakhic Midrashim', '36S', 'Halakhic Midrash, the rabbinic continuation of biblical law, is written in Middle Hebrew I and is one of the three major literary creations of the Tannaitic period. It is an important part of ancient Jewish biblical interpretation which often differs from sectarian interpretation as found in Qumran. A study of the terminology and methodology indicates the existence of two midrashic systems: Devei R. Akiba and Devei R. Ishmael. This course familiarizes students with the methodology and terminology of these two midrashic schools. We will examine the scholarly debate concerning the exact time in which the halakhic midrashim were composed and redacted as well as the transfer of terminology and material between the schools. Sections from all the midrash halakhah (Mekhiltot, Sifra and Sifre) are studied and compared to other tannaitic materials.', null, 2, null::jsonb),
    ('NML455H1', 'Modern Hebrew Poetry', '24S', 'This course is designed for the advanced students of Modern Hebrew who wish to pursue the study of Hebrew literature. We will examine the way in which this literature relates to ideas of land, homeland, peoplehood, and religious identities. We will continue with Yehuda Amihai''s poetry with particular attention to his love poetry. Our major concentration will be on Ḥaim Naḥman Bialik''s poetry and include at least one of his major epic poems. We shall focus on what makes Amihai and Bialik national poets. Our method of poetic analysis will include an inter-textual examination of the sources of poetic inspiration. Students will be taught to use the Bar Ilan Responsa Project as an aid to tracking allusions. We will also use historical Hebrew dictionaries.', null, 1, null::jsonb),
    ('NML456H1', 'Modern Hebrew Prose', '24S', 'This course is designed to introduce advanced students of Modern Hebrew to modern prose written primarily in today''s state of Israel. To this end we will spend two weeks looking at the motifs and styles available in contemporary children''s literature with an eye to their use of biblical allusions. This serves as background to a study of short stories by the Nobel laureate Agnon. The sources of the stories will be studied from the perspective of intertextuality where the source is both inspirational and in turn explicated by the novelist. The use of online search engines and databases will facilitate this analysis. The course teaches advanced reading skills in prose literature in Hebrew with emphasis on interpreting the texts, close readings, and tracking allusions. Use will be made of historical Hebrew dictionaries.', null, 1, null::jsonb),
    ('NML459H1', 'Readings in Second Temple Period Texts', '24S', 'This course provides an advanced investigation of selected issues in ancient Jewish texts stemming from the Second Temple Period (5th cent. BCE 1st cent. CE), and includes comparative study of biblical writings, apocrypha and pseudepigrapha, the Dead Sea Scrolls, and writings of ancient Jewish historians and philosophers. The specific topic for the course varies from one semester to another. The course has a strong research and writing component.', null, 2, '{"operator": "OR", "items": ["NML350H1", "NML351H1"]}'::jsonb),
    ('NML460H1', 'Advanced Persian I', '36S', 'This course is designed for students who have already completed  NML360Y1 Intermediate Persian or have an equivalent level of proficiency in Persian. This course aims to develop students'' abilities at an advanced level, with a focus on complex reading materials including historical, socio-political, media and journalistic texts. Students will improve their reading comprehension, strengthen writing skills, and advance speaking and listening skills through class discussions and oral presentations.', 'Native Speakers', 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML461H1', 'Modern Persian Poetry', '36S', 'This course examines Persian literature, mainly modern Persian poetry from the 19th to the 21st centuries, focusing on linguistics and literary approaches in contemporary poetry. The course includes a brief overview of different factors which shaped modern Persian poetry, then concentrates on the works of well-known modern poets who had great influence on establishing and developing Persian contemporary poets such as Nima Yushij, Ahmad Shamlu, Mehdi Akhavan Sales, Sohrab Sepehri, Forugh Farrokhzad, Hushang Ebtehaj, Simin Behbahani, and Mohammad Reza Shafi''i-Kadkani. After presenting a short biography and the works of each poet, students read selected poems of each poet and discuss the structure, poetic styles, figures of speech, themes and motifs in the poems. (Conducted in Persian)', null, 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML462H1', 'Modern Persian Prose', '36S', 'This course examines contemporary Persian prose, focusing on fiction, especially the novel and short story. After an overview of different genres of prose writing, the main elements of a story, such as plot, scene, character, theme, topic, point of view, and conflict, are discussed. The literary knowledge and abilities of students will be developed by analyzing different genres of prose writing, especially Persian short stories. At the end of this course students will be able to examine and analyze any form of story-writing and compose their own short stories. (Conducted in Persian.)', null, 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML463H1', 'Advanced Persian II', '36S', 'This course is designed for students who have already completed  NML460H1 Advance Persian I or have an equivalent level of proficiency in Persian. Its goal is to strengthen the students reading and writing skills and enrich their cultural and literary background. This is achieved through analysis of sophisticated authentic literary texts covering a wide range of literary genres.', 'Native Speakers', 1, '{"operator": "AND", "items": ["NML460H1"]}'::jsonb),
    ('NML464H1', 'Old Persian', '24L/24S', 'This course will survey the language, main epigraphical texts, historical context, and political ideology of the Old Persian inscriptions of the Achaemenid Empire (550–330 BCE). The Old Persian version of the famous inscriptions of Darius I in Bisotun will be read in the original, cuneiform script, linguistically analyzed, commented, and translated into English. By this training, students will be able to comfortably read the entire inscriptional corpus in Old Persian. By the end of the year, they will have acquired a strong understanding of the simplified Old Persian cuneiform script, the main phonological, morphological and syntactical features of the Old Persian language, and its connections with the Middle and modern Persian languages.', 'NML464Y1', 1, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}]}'::jsonb),
    ('NML465Y1', 'Avestan', '48L', 'This course surveys the grammar and syntax of the language of the Young Avestan corpus, belonging to the Old Iranian linguistic group. The Avesta was a compendium of Zoroastrian texts composed orally in northern Iran and Central Asia in two dialects spoken in different periods: Old Avestan (2nd millennium BCE) and Young Avestan (1st millennium BCE). Most foundational texts of Zoroastrianism were composed in Young Avestan language, which attests a more simplified grammar than Old Avestan and in this regard is closer to Old Persian. Knowledge of Young Avestan provides access to the mythical and ritual context of pre-Islamic Iran and Central Asia. Students will be introduced to the main phonological, morphological, and syntactical features of the Young Avestan language; its script; its most important texts; and its connections with Old Persian and Middle Persian, or Pahlavi.', null, 1, null::jsonb),
    ('NML466H1', 'Theory and Practice of Translation from and into Persian', '24S', 'An introduction to theories and techniques involved in English/Persian translation, focusing on translation practice and theoretical discussions on linguistic, cognitive, socio-political, and cultural aspects of translation. Through analysis and application of translation theory, students practice the art of translation and develop awareness of issues that translators face.', null, 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML467H1', 'Persian Literature: The Epic Tradition', '36S', 'Selected representative readings from the iconic masterpieces of classical heroic and romantic epic poetry, including the Persian national epic, Shahnameh, or Book of Kings; the magisterial ode of Khaqani on the ruins of a Sasanian palace; and tales from the Khamseh, or Quintet, of Nezami about the star-crossed lovers Laili and Majnun and the world-conqueror Iskandar, or Alexander the Great. Emphasis is on close reading and analysis of the linguistic and literary content and style of these works, and discussion of their historical and cultural backgrounds. All readings are in the original Persian. During the course, students will acquire essential skills in the technical requirements of classical Persian poetry, such as prosody, rhyme, and poetic devices.', 'NML460Y1', 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML468H1', 'Persian Literature: Ethical, Erotic, and Mystical', '36S', 'The companion course to  NML467H1 (Persian Literature: The Epic Tradition). Selected representative readings from the ethical works of Sa''di (Bustan and Gulistan); the mystical parable Mantiq al-tayr of ''Attar and the Masnavi-i ma''navi of Rumi; and the ghazals, or mystico-erotic lyrical poems, of Rumi and Hafiz. Emphasis is on close reading and analysis of the linguistic and literary content and style of these works, and discussion of their historical, cultural, and religious backgrounds. All readings are in the original Persian. During the course, students will acquire essential skills related to the technical requirements of classical Persian poetry, such as prosody, rhyme, and poetic devices, as well as an understanding of the key concepts and terminology of Persian Sufism.', 'NML460Y1', 1, '{"operator": "AND", "items": ["NML360Y1"]}'::jsonb),
    ('NML470Y1', 'Advanced Turkish', '96L', 'This course is designed for students who have already completed  NML370Y1 Intermediate Turkish or have an equivalent level of proficiency in Turkish. It aims to build upon the existing competence of the students in Turkish and to further improve their four skills through a variety of advanced speaking, listening, reading, and writing activities. By the end of this comprehensive course, students will be able to read, understand and translate various authentic texts of different genres such as literary works. They will be able to write essays on a wide range of topics. They will demonstrate the ability to express themselves both orally and in writing through complex grammatical structures and a rich vocabulary. They will also have gained thorough understanding of the social and cultural contexts in which Turkish is spoken. The course will enable students to pursue independent studies in Turkish.', null, 1, '{"operator": "AND", "items": ["NML370Y1"]}'::jsonb),
    ('NML471H1', 'Selected Readings in Turkish Literature', '24S', 'This course focuses on the analysis of representative examples of both poetry and prose from various periods of Turkish literature. Students will gain familiarity with different literary genres, themes, and traditions. Focusing on major works, the course will enhance students'' understanding of the cultural context in which the literature was produced. It will also help students further enrich their vocabulary and improve their grasp of grammatical phenomena.', 'NML490H1 (Topics in Near and Middle Eastern Languages: Readings From Modern Turkish Literature and Media), offered in Fall 2021', 1, '{"operator": "AND", "items": ["NML370Y1"]}'::jsonb),
    ('NML490H1', 'Topics in Near and Middle Eastern Languages', '36S', 'An advanced language seminar organized around grammatical issues or texts selected by the instructor.', null, 1, null::jsonb),
    ('PCJ200H1', 'Introduction to Peace, Conflict and Justice', '24L/12T', 'This course introduces students to the theories, concepts, histories, and actors that are fundamental to the field of peace, conflict, and justice. Students will discuss meanings, causes, obstacles, and sustainability of peace and justice through the discussion of historical and contemporary cases from around the world. Stemming from the interdisciplinary aspect of the field, students will learn a wide range of theoretical, empirical, and policy-oriented perspectives on thematic topics such as protection and violation of human rights, social and economic inequalities, and causes of violence and oppression. This course is intended for first year PCJ students and it serves as a gateway for all other courses offered in the PCJ program. This course is a requirement for PCJ majors and specialists.', null, 3, null::jsonb),
    ('PCJ210H1', 'Research Methods in Peace, Conflict and Justice', '24L/12T', 'This course introduces students to key research methods employed in the study of peace, conflict and justice. It considers both qualitative, quantitative, and mixed-methods research frameworks prominent in PCJ research drawn from a range of disciplines and approaches. Some methods explored in this course might include: descriptive analysis, correlational studies, bivariate or multivariate regression models, surveys, interviews, focus groups, and country case studies. The class teaches students how to read, understand and critique these frameworks and the scholarship they influence/produce. Concepts of internal and external validity, inductive and deductive reasoning, and ethics in research will also be covered. This course is a requirement for PCJ majors and specialists.', null, 3, null::jsonb),
    ('PCJ299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCJ299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCJ310H1', 'Data and Applications in PCJ', '24L/12T', 'The goal of this course is to introduce students to data literacy and applications in the topics of peace, conflict, and justice. The course is broadly divided into two parts. The first part will introduce data in the context of peace, conflict, and justice studies and outline the research process. Students will learn advanced quantitative research designs and will work with fundamental descriptive statistics tools. Students will work with different datasets, learn how to summarize data for different types of variables through graphs and tables, and explore measures of association between variables. In the second part of the course, students will work on data projects related to peace, conflict, and justice. Students will also design their own research relevant in PCJ. This course is a requirement for PCJ Specialists.', 'PCJ260H1', 3, '{"operator": "AND", "items": ["PCJ200H1", "PCJ210H1"]}'::jsonb),
    ('PCJ350H1', 'The Violence of Inequality: Conflict Dynamics and Power Asymmetries', '24L/12T', 'This course builds on various multi-disciplinary approaches to explore how inequalities shape violence, conflict, and post-conflict dynamics. It teaches students to understand and engage critically in debates in the field and to discover connections between the power structures that shape the emergence of violent conflicts, their dynamics, and their legacies. In addition, this course will offer students practical tools to analyze the intersection of conflict and inequality, as well as the implications of that intersection for pursuing peace. This course is a requirement for PCJ majors and specialists.', 'PCJ261H1', 3, '{"operator": "AND", "items": ["PCJ200H1", "PCJ210H1"]}'::jsonb),
    ('PCJ360H1', 'Topics in Peace, Conflict and Justice', '24L', 'This course explores selected issues in the field of Peace, Conflict ands Justice. Topics may vary from year to year. Through a suite of recent readings, students will strive to critically examine implications and challenges of, and solutions to the issues being studied. Please visit the Trudeau Centre for Peace, Conflict and Justice website for current offering information.', null, 3, '{"operator": "OR", "items": ["PCJ260Y1", {"operator": "AND", "items": ["PCJ260H1", "PCJ261H1"]}]}'::jsonb),
    ('PCJ361H1', 'Special Topics in Peace, Conflict and Justice Studies', '24S', 'An exploration of selected issues in the field of Peace, Conflict and Justice involving an overseas and/or practicum component.', 'PCS361H1,  UNI361Y1', null, null::jsonb),
    ('PCJ361Y1', 'Special Topics in Peace and Conflict Studies', '48S', 'An exploration of selected issues in the field of Peace, Conflict and Justice involving an overseas and/or practicum component.', 'PCS361H1,  PCS361Y1,  UNI361Y1', 3, '{"operator": "AND", "items": ["PCJ260Y1"]}'::jsonb),
    ('PCJ362H1', 'Experiential Learning in PCJ', '12T/24S', 'This course provides students an opportunity to learn by providing valuable services to local, national, or international organizations. This model of experiential learning is called organization partner experiences, in which students work in teams on a project that is of relevance to the partner organization. The overarching theme in this course is inclusion through access to public services. Access to public services such as education, health, and public provision of services is one of the most important ways in which disadvantaged populations experience upward socioeconomic mobility. Students will gain insights about inequality of access to public service, conduct critical analysis of current issues, and produce deliverables to understand issues of socio-economic inequality in societies around the world.', null, 3, '{"operator": "AND", "items": ["PCJ200H1", "PCJ210H1", "PCJ350H1"]}'::jsonb),
    ('PCJ380H1', 'Justice Institutions: Crime, Violence, and Insecurity', '24S', 'This course examines the role of institutions that respond to crime and violence. We study the role of institutional actors centering on criminal justice: we focus in particular on criminal justice institutions, but also community organizations, government agencies, international organizations, journalists, and others–in identifying, naming, and acting upon crime and violence. We also study the strategies these institutions adopt in responding to crime, violence, and insecurity, along with evidence about how they do so and outcomes of their interventions. Finally, we attend to the relationship between criminal justice and other social outcomes, including health and well-being, collective memory, skepticism, social movements, and civic participation. Throughout the course we rely on a wide range of materials, so that in most weeks students will engage with a combination of perspectives, including social science research, legal materials, testimonies, official documents, and journalistic accounts.', null, 3, '{"operator": "AND", "items": ["PCJ200H1", "PCJ210H1"]}'::jsonb),
    ('PCJ399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCJ399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCJ410H1', 'Research Paper Seminar in PCJ', '24S', 'This course guides each student through their own individual research project, embedded in an interactive group learning process, to offer an applied introduction to research methods for peace, conflict and justice studies. Students work through the research in the field of peace, conflict and justice studies, such as: identifying a research question, learning how to write a critical literature review, developing a rigorous research design, and applying quantitative, qualitative, or mixed methods to answering research inquires. The final deliverable is a draft of a research proposal or an empirical research-based paper. This course is a requirement for PCJ Specialists and open to PCJ Majors with approval from the Director.', null, 3, '{"operator": "AND", "items": ["PCJ200H1", "PCJ210H1", "PCJ350H1"]}'::jsonb),
    ('PCJ444H1', 'Special Topics in Peace and Conflict Studies', null, 'Topics vary annually. The objective of the course is to explore emerging issues in Peace and Conflict Studies. The focus of the course will be on a specific topic, rather than a broad survey of the field.', 'PCS444H1', 3, '{"operator": "AND", "items": ["PCJ260Y1", "PCJ360Y1"]}'::jsonb),
    ('PCJ460H1', 'Advanced Topics in Peace, Conflict and Justice', '24S', 'This course explores selected issues in the field of Peace, Conflict and Justice. Topics may vary from year to year. Through a suite of recent readings, students will strive to critically examine implications and challenges of, and solutions to the issues being studied. Please visit the Trudeau Centre for Peace, Conflict and Justice website for current offering information.', null, 3, '{"operator": "AND", "items": ["PCJ360H1", "PCJ362H1"]}'::jsonb),
    ('PCJ461H1', 'Research Methods in Peace, Conflict and Justice', '48S', 'This course guides each student through their own individual research project, embedded in an interactive group learning process, in order to offer an applied introduction to research methods for peace, conflict and justice studies. Students work through the full research process, including: identifying a research question, learning how to conduct effective literature reviews, developing a rigorous research design, and applying quantitative and qualitative methods to answering questions. Rather than conducting research independently or studying research methods in isolation, the course combines the two: students learn collectively about the different steps in the research process while simultaneously applying those steps to their own research project. This is then complemented by presenting that research and discussing different research projects in class, so as to receive continuous feedback and be exposed to a variety of research methods and approaches.', null, 3, null::jsonb),
    ('PCJ499H1', 'Peace and Conflict Studies Independent Study Course', null, 'This course is designed to provide students with the opportunity to explore topics not covered in the curriculum, or to develop a more detailed focus on topics covered. Approval of the program director is required. The student must obtain written agreement of the instructor who will supervise the independent study, submit the proposal to and obtain approval from the director and program administrator, who will then add the student to the course. Not eligible for CR/NCR option. Applications are due two weeks before course enrolment deadlines.', 'PCS499H1', 3, '{"operator": "OR", "items": ["PCJ260Y1", {"operator": "AND", "items": ["PCJ260H1", "PCJ261H1"]}]}'::jsonb),
    ('PCL102H1', 'The Art of Drug Discovery', '24L', 'This course introduces students to the processes and strategies for discovering new drugs with a special focus on current and emerging approaches for the rational design of drugs that are both effective and safe.', null, 4, null::jsonb),
    ('PCL200H1', 'Drugs & the Brain', '24L', 'Lectures introduce students to prescribed and illicit drugs that affect the brain. Lectures cover drug pharmacology and explain how drugs alter mood, perception, cognition, and arousal by affecting different aspects of brain function. The societal impact of these prescribed and illicit drugs is also discussed. Note: This course is not intended for upper-year students in Life Sciences. Upper-year Life Science students interested in this content should look into  PCL475H1 and/or  PCL476H1 as the more appropriate choice.', 'PSY396H1,  PSYC62H3', 4, null::jsonb),
    ('PCL201H1', 'Introduction to Pharmacology and Pharmacokinetic Principles', '36L/6T', 'A general introduction to the principles of pharmacology and pharmacokinetics. Topics include chemical (drug) absorption, distribution, biotransformation, elimination; the calculation of dosages and pharmacokinetic parameters, variability in drug response, adverse drug reactions and special interest topics.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO130H1", "BIOA01H3", "BIO152H5"]}, {"credits": 6.0, "department": null}]}'::jsonb),
    ('PCL218H1', 'Cannabis the Drug', '24L', 'There is a critical need for a breadth of understanding regarding its mechanism of action, pharmacological effects and its potential benefits and harms (short- and long-term). Students will gain a breadth of understanding in cannabis-related topics including pharmacology and toxicology, its role in mental health and addictions, medical use, drug policy and new drug development that stems from increased access to cannabis constituents. They will learn to differentiate myths and anecdotes from evidence-based knowledge. Going forward it is imperative that students spanning basic sciences through business, arts and engineering have a comprehensive understanding of these topics.  PCL218H1 will give students for a variety of academic backgrounds a basic understanding of the health implications of cannabis which have broad implications for both our professional and personal lives.', null, 4, null::jsonb),
    ('PCL297H1', 'Research Experience in Pharmacology & Toxicology I', '60P', 'A formal opportunity to gain hands-on experience and develop their skills within a research laboratory setting. Students will have a chance to become familiar and efficient at good lab practices, develop critical thinking and evaluation skills while applying their knowledge and developing trouble shooting skills to practical research questions. Students are required to participate in active research for the equivalent of a minimum of 60 hours of laboratory time. This course is Pass/Fail. Not eligible for CR/NCR option. NOTE: students are required to secure their own supervisor for the course. Permission of Faculty Supervisor and Department required. Additional student information resources and enrollment form for the course can be found on the Pharmacology & Toxicology website here: https://pharmtox.utoronto.ca/undergraduate-courses', null, 4, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('PCL298H1', 'Research Experience in Pharmacology & Toxicology II', '60P', 'Following experience from  PCL297H1, this follow up course provides students an opportunity to expand their hands-on experience and skill set within a research laboratory setting. This course is only open to students who have completed  PCL297H1 and wish to continue their research opportunity with the same supervisor. Students will continue to develop good lab practices, critical thinking and evaluation skills while applying their knowledge and trouble shooting skills to practical research questions. Students are required to participate in active research for the equivalent of a minimum of 60 hours of laboratory time. Not eligible for CR/NCR option. NOTE: students are required to secure their own supervisor for the course. Permission of Faculty Supervisor and Department required. Additional student information resources and enrollment form for the course can be found on the Pharmacology & Toxicology website here: https://pharmtox.utoronto.ca/undergraduate-courses', null, 4, '{"operator": "AND", "items": ["PCL297H1"]}'::jsonb),
    ('PCL299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCL299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCL302H1', 'Pharmacodynamic Principles', '36L', 'Topics include biological action of drugs on membranes, enzymes, receptors, neural and hormonal systems, transmission and modulation.', 'PHC300H1,  PHC301H1', 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1"]}'::jsonb),
    ('PCL345H1', 'Experimental Approaches in Drug Discovery', '24L', 'Lecturers use their own research to demonstrate how they approach a biological question. The lectures emphasize why one approach is chosen over other possible approaches, and explain the strengths and limitations of techniques. Following the one-hour lecture there is an interactive discussion of the experimental approach covered in the lecture.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PSL300H1", "PSL301H1", "BIO270H1", "BIO271H1"]}, {"credits": 9.0, "department": null}]}'::jsonb),
    ('PCL367H1', 'Drug Development Pipeline I: In vitro', '8T/40P', 'This course will provide a learning experience that simulates the process, techniques, analysis and evaluation methods used for early-stage in vitro drug development. Modules will build on the student''s fundamental knowledge and will simulate and illustrate the thought processes and techniques that are used during new drug development in academic research institutes, clinical research organizations and pharmaceutical and biotechnology companies worldwide. Modules include target screening, cytotoxicity assays, transcriptional activation testing and metabolizing enzyme identification experiments. This experience will allow students to leverage their learned knowledge to improve their employability in this area, while honing their critical thinking and analytical skills. (Approximate Lab Materials Fee: $27)', null, 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PCL368H1', 'Drug Development Pipeline II: In vivo', '8T/40P', 'This course will provide a learning experience that parallels and simulates the process, protocols, methods and evaluation tools used for later-stage in vivo drug development. Modules will build on the student''s fundamental knowledge and simulate the thought processes and techniques used during drug development in research institutes, clinical research organizations and pharmaceutical and biotechnology companies worldwide. Modules will include pharmacokinetic and pharmacogenetic screening approaches in model systems and humans, and students will participate in Randomized Controlled Trial (RCT) studies. Students will also gain insight into current large-data computational research approaches in the pharmaceutical industry, broaching topics such as data science and bioinformatics. This experience will allow students to leverage their learned skills and knowledge to improve their comprehension and employability in this area, while honing critical thinking and analytical skills. (Approximate Lab Materials Fee: $27)', null, 4, '{"operator": "AND", "items": ["PSL300H1", "PSL301H1", "PCL201H1", "PCL302H1"]}'::jsonb),
    ('PCL376H1', 'Experimental Design and Data Analysis for Pharmacology and Toxicology', '30L/6T', 'This course includes lectures focused on experimental design and the analysis of pharmacological and toxicological data. Topics include: principles of experimental design, data analysis and statistical tests appropriate for each type, use of computing statistical packages, analysis of dose-response and time-response curves and analysis of receptor binding assays. Practical applications and problem sets will be taken up in class and in tutorials. Not offered every year.', null, 4, '{"operator": "AND", "items": ["PCL201H1"]}'::jsonb),
    ('PCL381H1', 'Molecular Toxicology Foundations', '24L/24T', 'This course introduces toxicology principles and the molecular basis underlying the toxicity of drugs and other chemicals. Lectures cover modulators of toxicity, toxicant-target interactions and the sequence of events that occur at a molecular level leading to impaired cell function.', 'PCL481H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BIO130H1", "BIOA01H3", "BIO152H5"]}, "PCL201H1"]}'::jsonb),
    ('PCL382H1', 'Integrative Toxicology', '24L/12T', 'The routes and toxicokinetics/time course of toxicological insults disrupts and damages tissues and organs resulting in adverse outcomes, worsening clinical outcomes and triggering new pathologies and disorder. This course engages students in comprehensive and broad organ and system-based toxicology and its effects on human health.', null, 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1", "PCL381H1"]}'::jsonb),
    ('PCL386H1', 'Pharmacology of Cancer Signaling', '24L', 'This course will expand on both classical and cutting edge pharmacological strategies proposed to mitigate the consequences of altered signal transduction in cancer. Students will have the opportunity to develop knowledge on these molecular events and how they can be targeted to improve clinical outcomes. Students will integrate lecture material with assigned readings and assignments.', 'PCL486H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1", {"operator": "AND", "items": ["CHM361H5", "CHM362H5"]}]}, {"credits": 9.0, "department": null}]}'::jsonb),
    ('PCL389H1', 'Understanding the Role of Pharmacology and Toxicology in Society', '24L', 'This service learning course explores issues surrounding the effects that pharmaceuticals and chemicals have in society. Specifically, it integrates pharmacology and toxicology with social, health and political issues as they relate to drug abuse and addiction. Students are required to interact and work with community partners during the semester (approx. 20hrs). Classroom discussions will integrate community experiences with lecture material. Not eligible for CR/NCR option.', null, 4, '{"operator": "AND", "items": ["PCL201H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PCL397Y0', 'Research Abroad in Pharmacology and Toxicology', '200P', 'An independent research project in a pharmacology and/or toxicology laboratory in an approved partner university. This international research experience will be supervised by a faculty member at the partner institution and will allow students to develop critical thinking and evaluation skills while applying their knowledge and trouble shooting skills to practical research questions. Information regarding eligibility, application process and upcoming information session dates can be found on the Department of Pharmacology and Toxicology website here:  PCL397Y0 Website. Not eligible for CR/NCR option. Contact undergrad.pharmtox@utoronto.ca for more information.', null, 4, '{"operator": "AND", "items": ["PCL201H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PCL397Y1', 'Research Abroad in Pharmacology and Toxicology', '200P', 'An independent research project in a pharmacology and/or toxicology research laboratory for inbound exchange students coming to the University of Toronto from an approved partner university. This research experience will be supervised by a faculty member and will allow students to develop critical thinking, communication and evaluation skills while applying their knowledge and trouble shooting skills within leading edge research questions. Information regarding eligibility, application process and upcoming information session dates can be found on the Department of Pharmacology and Toxicology website here:  PCL397Y1 Website. Not eligible for CR/NCR option. Contact undergrad.pharmtox@utoronto.ca or the Centre for International Experience https://internationalexperience.utoronto.ca/ for more information.', null, 4, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}]}'::jsonb),
    ('PCL399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCL399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PCL402H1', 'Pharmacology and Toxicology in Drug Development', '24L/12T', 'This course provides the basic principles of drug development, with a primary focus on the application of fundamental principles of pharmacology and toxicology to the design of preclinical assays and early phase clinical trials. Students in the course will have the opportunity to engage in experiential learning in drug development projects for rare diseases.', null, 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1"]}'::jsonb),
    ('PCL469H1', 'Systems Pharmacology I', '31L/4T', 'A culmination of pharmacological principles discussing concepts of drug properties and their interactions within the body. The mechanism of action, pharmacological properties including clinical use and adverse effects of drugs acting on the autonomic nervous systems, cardiovascular, renal, respiratory, gastrointestinal and endocrine systems will be examined. Critical evaluation of primary literature and examination of clinical problem-based case studies will be integrated with lecture material through small group sessions.', 'PCL470Y1', 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1", "PSL300H1", "PSL301H1"]}'::jsonb),
    ('PCL470H1', 'Systems Pharmacology II', '31L/4T', 'A culmination of pharmacological principles discussing concepts of drug properties and their interactions within the body. The mechanism of action, pharmacological properties including clinical use and adverse effects of drugs acting on the central nervous systems and immunological system; antimicrobial and cancer chemotherapeutic agents as well as the potential therapeutic use of endogenous/herbal compounds will be examined. Critical evaluation of primary literature and examination of clinical problem-based case studies will be integrated with lecture material through small group sessions.', 'PCL470Y1', 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1", "PSL300H1", "PSL301H1", {"credits": 14.0, "department": null}]}'::jsonb),
    ('PCL472Y1', 'Project in Pharmacology', null, 'This course affords students an opportunity for hands-on research experience in a laboratory or applied pharmacology setting. Students will work under the supervision of a faculty member and will submit a final written report and oral presentation. Enrollment is limited to students in ASSPE2340/ASSPE2082 programs and requires permission from the Department of Pharmacology and Toxicology. It is the student''s responsibility to secure a placement with an approved supervisor before the course begins (a list of potential supervisors will be provided by the Department of Pharmacology and Toxicology). Students will be registered in the course once their ballot form (obtained from the Department) is signed by an approved supervisor and approved by the Department of Pharmacology and Toxicology. Eligible students will be contacted by the Department during the Winter term, occurring prior to their final year of study (i.e. 3rd year of study for most), with details and instructions to apply. Students are expected to spend approximately 200 hours towards this project but this will be project/supervisor dependent. Not eligible for CR/NCR option.', 'PCL474Y1', 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1", {"operator": "OR", "items": ["PCL367H1", "PCL368H1"]}, {"operator": "OR", "items": ["STA288H1", "STA220H1", "PSY201H1"]}]}'::jsonb),
    ('PCL474Y1', 'Project in Toxicology', null, 'This course affords students an opportunity for hands-on research experience in a laboratory or applied toxicology setting. Students will work under the supervision of a staff member and will submit a final written report and oral presentation. Enrollment is limited to students in ASSPE2340/ASSPE2573/ASSPE0605 programs and requires permission from the Department of Pharmacology and Toxicology. It is the student''s responsibility to secure a placement with an approved supervisor before the course begins (a list of potential supervisors will be provided by the Department of Pharmacology and Toxicology). Students will be registered in the course once their ballot form (obtained from the Department) is signed by an approved supervisor and approved by the Department of Pharmacology and Toxicology. Eligible students will be contacted by the Department during the Winter term, occurring prior to their final year of study (i.e. 3rd year of study for most), with details and instructions to apply. Students are expected to spend approximately 200 hours towards this project but this will be project/supervisor dependent. Not eligible for CR/NCR option.', 'PCL472Y1', 4, '{"operator": "AND", "items": ["PCL201H1", "PCL302H1", {"operator": "OR", "items": ["PCL367H1", "PCL368H1"]}, {"operator": "OR", "items": ["STA288H1", "STA220H1", "PSY201H1"]}]}'::jsonb),
    ('PCL475H1', 'Neuropsychopharmacology 1', '36L/12T', 'This course examines drugs whose primary effect is to alter the operation of the brain and mind (cognition, emotion). Key topics include the neurophysiology of: Pain, Anesthesia, Psychoactive Drug Effects, Addiction, Epilepsy, and Psychomotor Control. The brain mechanisms that mediate each of these processes or syndromes will be described along with pharmacological strategies to probe and regulate them. Chronic drug effects will be discussed to illustrate how the brain changes with ongoing exposure to different drugs.', 'PCL475Y1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}]}'::jsonb),
    ('PCL476H1', 'Neuropsychopharmacology 2', '36L/12T', 'Students will explore the major CNS neurological syndromes which may include anxiety, schizophrenia and depression/mania and their relate neurological abnormalities. Lectures will discuss major classes of drugs used to mitigate and treat these disorders, their mechanisms of action, clinical use and unwanted effects. Not offered every year.', 'PCL475Y1,  PSY396H1', 4, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, "PCL475H1"]}'::jsonb),
    ('PCL477H1', 'The DNA Damage Response in Pharmacology and Toxicology', '24L', 'Many anticancer drugs and environmental agents exert their cytotoxic effects through DNA damage. This course explores specific pharmacological and toxicological agents that damage DNA and discusses how mammalian cells respond to this DNA damage.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["BCH210H1", "BCH242Y1", {"operator": "AND", "items": ["CHM361H5", "CHM362H5"]}]}, {"credits": 9.0, "department": null}]}'::jsonb),
    ('PCL482H1', 'Toxicants of Concern', '24L', 'This course explores several contemporary topics in biomedical toxicology with an emphasis on how chemicals adversely affect human health. Lectures cover principles of toxicology and the mechanisms of toxicity of major groups of chemical toxicants and biological toxins, including heavy metals, industrial pollutants, biological toxins and nanomaterials.', 'PCL473Y1', 4, '{"operator": "AND", "items": [{"credits": 14.0, "department": null}, "PCL201H1", "PCL302H1", "PCL381H1", "PCL382H1"]}'::jsonb),
    ('PCL483H1', 'Interdisciplinary Toxicology', '24L', 'This course explores several contemporary topics in biomedical and environmental toxicology with an emphasis on the applications and methodologies within toxicology. Course content includes risk assessments, adverse drug reaction monitoring, forensics and regulator toxicology.', 'PCL473Y1', 4, '{"operator": "AND", "items": ["PCL482H1"]}'::jsonb),
    ('PCL484H1', 'Seminars in Pharmacokinetics and Toxicokinetics', '24S', 'Each week a scientist affiliated with the Department of Pharmacology and Toxicology will discuss the application of pharmacokinetic and/or toxicokinetic principles to their research. This area of study plays an important role in clinical medicine and drug development', null, 4, '{"operator": "AND", "items": ["PCL201H1"]}'::jsonb),
    ('PCL490H1', 'Advanced Topics in Pharmacology and Toxicology', '12L/12S', 'An opportunity to expand on innovative and unique topics in Pharmacology and Toxicology that are not already extensively addressed. The course will reveal the dynamic nature of the field and the diverse interests of our faculty. Students will be introduced to leading edge topics and research within the discipline of Pharmacology and Toxicology.', null, 4, '{"operator": "AND", "items": ["PCL302H1", {"operator": "OR", "items": ["STA288H1", "STA220H1", "PSY201H1"]}, {"credits": 14.0, "department": null}]}'::jsonb),
    ('PCL497H1', 'Advanced Research in Pharmacology or Biomedical Toxicology', '60P', 'Following experience from  PCL472Y1 or  PCL474Y1, this course provides students an opportunity to continue to expand and develop their research skills and knowledge within a research laboratory or applied pharmacology setting. Students will develop advanced collaboration skills, good lab practices, scientific literacy, critical thinking and evaluation skills while applying their knowledge and trouble shooting skills to practical research questions. Written and oral communication skills as well as laboratory skills will comprise course assessments. Students are required to participate in active research for the equivalent of a minimum of 60 hours of laboratory time. NOTE: As this is an opportunity to continue their experience within the same  PCL472Y1/ PCL474Y1 research laboratory/supervisor. Not eligible for CR/NCR option.', 'PCL498Y1', 4, '{"operator": "OR", "items": ["PCL472Y1", "PCL474Y1"]}'::jsonb),
    ('PCL498Y1', 'Advanced Research in Pharmacology or Biomedical Toxicology', '200P', 'Following experience from  PCL472Y1 or  PCL474Y1, this course provides students an opportunity to continue to expand and develop their research skills and knowledge within a research laboratory or applied pharmacology setting. Students will develop advanced collaboration skills, good lab practices, scientific literacy, critical thinking and evaluation skills while applying their knowledge and trouble shooting skills to practical research questions. Written and oral communication skills as well as laboratory skills will comprise course assessments. Students are required to participate in active research and related activities for the equivalent of a minimum of 200 hours of laboratory time. NOTE: As this is an opportunity to continue their research, students are required to continue within the same  PCL472Y1/ PCL474Y1 research laboratory/supervisor. Not eligible for CR/NCR option.', 'PCL497H1', 4, '{"operator": "OR", "items": ["PCL472Y1", "PCL474Y1"]}'::jsonb),
    ('PDC220H1', 'Arts & Science Internship Program - Maximizing Your Experience', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 2, and students admitted for Year 2 must successfully complete this course and receive a passing grade to gain access to the ASIP job board. The course will provide an opportunity for students to prepare for and maximize their learning and personal development through ASIP. Topics may include: self-assessment – skills, values, interests; building a career and co-op plan; skills articulation – how to identify, articulate and apply skills gained through courses and other life experiences; personal marketing documents; guided self-reflection on barriers to employment; resources and toolkits to support access for all; and co-op student panels. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 3 should enrol in  PDC230H1.', 'PDC230H1', null, null::jsonb),
    ('PDC221H1', 'Arts & Science Internship Program - Essential Skills for ASIP Success', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 2, and students admitted for Year 2 must successfully complete this course and receive a passing grade before starting their first work term. The course will help students prepare for their first work term and optimize their chances of success in the first recruitment cycle. Topics may include: ASIP guidelines and requirements, resume and cover letter tailoring, professionalism essentials, job search essentials, interview preparation, workplace rights, health and wellbeing while in ASIP, and accessibility and EDI considerations. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details.  Students who enrolled in the ASIP stream of their program in Year 3 should enrol in  PDC231H1.', 'PDC231H1', null, '{"operator": "AND", "items": ["PDC220H1"]}'::jsonb),
    ('PDC230H1', 'Arts & Science Internship Program - Maximizing Your Experience', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 3, and students admitted for Year 3 must successfully complete this course and receive a passing grade to gain access to the ASIP job board. The course will provide an opportunity for students to prepare for and maximize their learning and personal development through ASIP. Topics may include: self-assessment – skills, values, interests; building a career and co-op plan; skills articulation – how to identify, articulate and apply skills gained through courses and other life experiences; personal marketing documents; guided self-reflection on barriers to employment; resources and toolkits to support access for all; and co-op student panels. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 2 should enrol in  PDC220H1.', 'PDC220H1', null, null::jsonb),
    ('PDC231H1', 'Arts & Science Internship Program - Essential Skills for ASIP Success', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 3, and students admitted for Year 3 must successfully complete this course and receive a passing grade before starting their first work term. The course will help students prepare for their first work term and optimize their chances of success in the first recruitment cycle. Topics may include: ASIP guidelines and requirements, resume and cover letter tailoring, professionalism essentials, job search essentials, interview preparation, workplace rights, health and wellbeing while in ASIP, and accessibility and EDI considerations. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 2 should enrol in  PDC221H1.', 'PDC221H1', null, '{"operator": "AND", "items": ["PDC230H1"]}'::jsonb),
    ('PDC320H1', 'Arts & Science Internship Program - Professional Skill Development I', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 2. Students admitted for Year 2 must successfully complete this course to graduate from the ASIP Stream of their program of study. The course will help students build transferable skills essential for success in the workplace and in the evolving world of work. The course will also support and help guide students through the next recruitment cycle. Topics may include: post work-term reflection (if applicable), advanced interview skills, job search support for recruitment cycle II, and skills development modules. Skills development modules may include: design thinking, intercultural communication, problem solving, conflict resolution, universal design and ethical and sustainability-minded decision making. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 3 should enrol in  PDC330H1.', 'PDC330H1', null, '{"operator": "AND", "items": ["PDC221H1"]}'::jsonb),
    ('PDC321H1', 'Arts & Science Internship Program - Professional Skill Development II', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 2. Students admitted for Year 2 must successfully complete this course to graduate from the ASIP Stream of their program of study. The course will help students build transferable skills essential for success in the workplace and in the evolving world of work. The course will also support and help guide students through the next recruitment cycle. Topics will include: job search support for recruitment cycle II and skills development modules. Skills development modules topics will continue from  PDC320H1, with an additional focus on: Project management skills including, Problem Solving and Critical Thinking, Teamwork and Leadership, Goal Setting and Planning, professional responsibility, workplace organization skills, workplace writing and communication. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 3 should enrol in  PDC331H1.', 'PDC331H1', null, '{"operator": "AND", "items": ["PDC320H1"]}'::jsonb),
    ('PDC330H1', 'Arts & Science Internship Program - Professional Skill Development I', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 3. Students admitted for Year 3 must successfully complete this course to graduate from the ASIP Stream of their program of study. The course will help students build transferable skills essential for success in the workplace and in the evolving world of work. The course will also support and help guide students through the next recruitment cycle. Topics may include: post work-term reflection (if applicable), advanced interview skills, job search support for recruitment cycle II, and skills development modules. Skills development modules may include: design thinking, intercultural communication, problem solving, conflict resolution, universal design and ethical and sustainability-minded decision making. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 2 should enrol in  PDC320H1.', 'PDC320H1', null, null::jsonb),
    ('PDC331H1', 'Arts & Science Internship Program - Professional Skill Development II', null, 'This course is a mandatory component of the Arts & Science Internship Program (ASIP) for students admitted to the ASIP stream of their program for Year 3. Students admitted for Year 3 must successfully complete this course to graduate from the ASIP Stream of their program of study. The course will help students build transferable skills essential for success in the workplace and in the evolving world of work. The course will also support and help guide students through the next recruitment cycle. Topics will include: job search support for recruitment cycle II and skills development modules. Skill development topics will continue from  PDC330H1, with an additional focus on: Project management skills including, Problem Solving and Critical Thinking, Teamwork and Leadership, Goal Setting and Planning, professional responsibility, workplace organization skills, workplace writing and communication. This course does not carry credit weight and is evaluated as Credit/No Credit. No tuition fee is associated, however an ancillary fee will be assessed. Refer to the ASIP Fees & Financial Aid website for further details. Students who enrolled in the ASIP stream of their program in Year 2 should enrol in  PDC321H1.', 'PDC321H1', null, '{"operator": "AND", "items": ["PDC330H1"]}'::jsonb),
    ('PHC230H1', 'Pharmaceutics 1', '36L/12T', 'This course introduces the key concepts in the design, manufacture, and use of efficacious dosage forms. The characteristics of different delivery routes are discussed. The course focuses on the role of pharmaceutics in drug development, and the role of anatomy and physiology in the conception and design of effective dosage forms. Topics covered include biopharmaceutical considerations, pharmaceutical solutions, sterilization theories and techniques, complexation and solubility enhancement, pre-formulation, colloids and dispersions, powders and micromeritics, and solid-state properties. Students will gain an appreciation of how the properties of drug components (such as pH, salt concentration, co-solvents, sterility, colloids, dispersions, powders, and solids) determine the stability, solubility, and efficacy of drug products.', 'PHM141H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}]}'::jsonb),
    ('PHC300H1', 'Molecular Pharmacology 1', '24L/12T', 'Structural and mechanistic determinants of drug action at the molecular level. Topics include the physical-chemical properties of drugs per se as they relate to therapeutic intervention and the biophysical and biochemical properties of enzymes and nucleic acids that underlie and are affected by their interactions with drugs.', 'PCL302H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}]}'::jsonb),
    ('PHC301H1', 'Molecular Pharmacology 2', '36L/12T', 'Structural and mechanistic determinants of drug action via macromolecules that effect cellular signalling. Neurohumoral receptors and other signalling proteins are grouped according to their structure and mechanism of action. Native properties and their modulation by drugs are discussed in the context of basic principles of molecular pharmacology.', 'PCL302H1,  PHM140H1', 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "BCH210H1"]}'::jsonb),
    ('PHC320H1', 'Chemistry and Technologies in Drug Discovery', '36L', 'This course provides interdisciplinary learning related to the chemistry of drugs and technologies of drug discovery as they are related to small molecules and biologics, their mechanisms of action, and the latest trends in the field of pharmaceuticals. Various important concepts such as structure-activity relationships, drug-like properties, computer modelling, combinatorial chemistry, small molecule drugs, biologics and related aspects in relation to new drugs will be covered. Novel concepts such as artificial intelligence in drug discovery will be introduced. After completing this course, students may practice entry-level medicinal chemistry with sound synthetic chemistry acquired from other chemistry courses, or take advanced courses in medicinal chemistry, drug discovery, and specialized courses in drug development. Students will also have a deeper understanding of drug discovery and development.', null, 4, '{"operator": "AND", "items": ["BCH210H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}]}'::jsonb),
    ('PHC330H1', 'Pharmaceutics 2', '36L/12T', 'This course provides an understanding of advanced topics in pharmaceutics. It involves a detailed examination of the material properties of pharmaceuticals and the role of cellular processes in the delivery of a drug to its site of action. Selected topics include thermodynamic characterization of drug solubility, diffusion measurement and its use in pharmaceutics, liposomal drug delivery, excipient consideration and selection for liquid dosage forms, polymeric materials in pharmaceutical applications, rheology and its applicability to liquid drug vehicles, bioequivalence determination of dermatological dosage forms, and an introduction on the impact of physiochemical properties on dermatological dosage forms.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": [{"operator": "AND", "items": ["CHM135H1", "CHM136H1"]}, "CHM151Y1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}]}'::jsonb),
    ('PHC331H1', 'Establishing the Bioequivalence of Pharmaceutical Products', '48L', 'This course will introduce the practical and regulatory design elements and consideration of human clinical trials for the purposes of demonstrating bioequivalence between drug products. The principles discussed are currently used by generic and innovator drug companies in many countries. Students will learn about the regulations, methods, techniques, pharmacokinetics, and biostatistics involved in creating bioequivalence studies. The course has a heavy mathematical emphasis, with a large component dedicated to mathematical modeling (non-compartmental and compartmental pharmacokinetic modeling, and biostatistics). Also discussed are clinical trial sample size determination, bioequivalence study design elements, clinical study protocol and final report writing, disaster recovery and outlier analysis, and design of steady-state studies. A module is also included on developing and improving interview skills. After taking this course, students will understand the steps required to set up single-dose and steady-state pilot and pivotal bioequivalence trials using parallel, crossover, and semi-replicate designs, and be well-poised for entry-level scientific positions in industry.', null, 4, '{"operator": "AND", "items": ["BCH210H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1"]}, "PHC230H1", "PHC330H1"]}'::jsonb),
    ('PHC340Y1', 'Pharmaceutical Chemistry Laboratory', '24L/96P', 'This course will introduce students to theoretical and applied concepts in pharmaceutical chemistry, in research, development, and manufacturing contexts. The course is designed with lectures and laboratories covering major areas in pharmaceutical chemistry, which have been carefully scheduled together to link concepts discussed during lectures to practical hands-on activities. The course covers selected topics pertinent to drug development such as acid/base equilibria, buffer preparation, drug solubility, drug polymorphs and salt selection, pKa, and co-solvency. The course also examines characterizing properties of common liquid, semi-solid and solid drug vehicles, such as viscosity, degradation kinetics/stability, diffusivity, tonicity, particle size distribution, and powder flowability. Emphasis is placed on the process of drug manufacture. Laboratory equipment used is commonly found in formulation labs, pharmacies, pharmaceutical research laboratories, and pharmaceutical manufacturing facilities. A lecture module on ethics and academic integrity will discuss cutting-edge applications of ethics in research, and issues arising when complex scientific solutions are proposed to regulatory bodies and to the public eye.', null, 4, '{"operator": "AND", "items": [{"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}, {"operator": "OR", "items": ["CHM220H1", "CHM222H1"]}, "CHM223H1", "BCH210H1"]}'::jsonb),
    ('PHC401H1', 'Drug Transport across Biological Membranes', '24L', 'The goal of this course is to provide students with knowledge of the molecular processes involved in drug transport across biological cell membranes with emphasis on their physiological and clinical significance. This course is restricted to Pharmaceutical Chemistry Specialist program students.', 'JFK1122H', 4, '{"operator": "AND", "items": ["PHC301H1"]}'::jsonb),
    ('PHC420H1', 'Application of Medicinal Chemistry to Pharmacology', '24L', 'This online course will build upon basic pharmacology and medicinal chemistry to make links between the basic sciences and demonstrate how basic principles can be used to improve clinical therapy. It will also include a critical evaluation of evidence for specific mechanisms and therapies. Topics covered include the effect of metabolism on drug response and factors that influence drug metabolism and kinetics; interactions of drugs with receptors, genetic differences in response, and mechanisms of tolerance; antimicrobials and antineoplastics; autocoids, antihistamines, vasopressin, anticoagulants, iron, estrogens, androgens, and the use of drugs in the perinatal period; antithyroid drugs, drugs to treat diabetes, and corticosteroids; eicosanoids, antihyperlipidemic drugs, and vitamins; drugs affecting bone metabolism, cholinergic agonists and antagonists; adrenoreceptor agonists and antagonists, agents affecting muscles and movement; opioids; CNS organization; anticonvulsants, anesthetics, and anxiolytics; antipsychotics, antidepressants, inotropic agents, antiarrhythmic drugs, diuretics; anti-inflammatory drugs, respiratory drugs, immune system organization; drugs to treat acid-peptic disorders, intestinal motility disorders, and inflammatory bowel disease; and adverse drug reactions and poisoning. An emphasis is placed on developing critical reasoning and evaluation skills to discern between standard of care and complementary therapies that have been developed in the past showing poor safety and/or efficacy, with poor regard to the scientific process. This course is restricted to Pharmaceutical Chemistry specialist program students.', 'PHM240H1', 4, '{"operator": "AND", "items": ["PHC301H1", "PHC320H1"]}'::jsonb),
    ('PHC421H1', 'Biomolecular Interactions and Thermodynamics I', '36L', 'This course will consider many of the topics presented in the first half in much greater detail including a rigorous examination of the interpretation of experimental data. This course is intended for students whose research or interest is in the thermodynamics of biological molecules. This course is restricted to Pharmaceutical Chemistry specialist program students.', 'PHM1130H', 4, null::jsonb),
    ('PHC430H1', 'Recent Developments in Dosage Form Design', '24L', 'Introduction to controlled drug delivery: Mechanisms and kinetics of controlled drug release. Fundamental theories and mathematical tools for the design of modern dosage forms. Development and applications of controlled drug delivery dosage forms. This course is restricted to Pharmaceutical Chemistry specialist program students.', 'PHM324H1, PHM1109H', 4, null::jsonb),
    ('PHC431H1', 'Latest Developments in Drug Discovery', '24L', 'In-depth discussion of implementation of pharmaceutical sciences in drug development strategies. Students will apply fundamental principles of pharmaceutics and drug delivery to current problems in the pharmaceutical industry. This course is restricted to Pharmaceutical Chemistry specialist program students.', 'JFK1120H', 4, null::jsonb),
    ('PHC432H1', 'Nanomedicines in Oncology', '24L', 'This course covers a range of topics that pertain to the development and application of nanomedicines in oncology. Students will gain an understanding of the biological barriers to drug delivery in oncology as well as the tremendous heterogeneity in cancer and the challenge this presents for treatment. The concepts of passive and active targeting of nanomedicines will be covered with critical assessment of the enhanced permeability and retention effect. A detailed overview of the most advanced nanotechnology-platforms for drug delivery (i.e., liposomes, block copolymer micelles and polymer-drug conjugates) will be provided with additional discussion of new emerging platforms. The integration of imaging in drug development and development of theranostics and therapeutic-diagnostic pairs will also be discussed. Special emphasis on critical evaluation of scientific literature and pre-clinical/clinical studies will be made throughout the course. *Note* This course is offered in alternating years.', null, 4, '{"operator": "AND", "items": ["PHC230H1", "PHC330H1"]}'::jsonb),
    ('PHC435H1', 'Pharmaceutical Data Acquisition and Analysis', '22L/26P', 'This course introduces students to theoretical and applied concepts in designing and implementing electronic circuitry, for the purpose of collecting and analyzing experimental data in pharmaceutics and other contexts. The course discusses introductory circuit design, with an emphasis on how common components work in scientific and pharmaceutical manufacturing instrumentation. Practical and mathematical aspects of circuit design are discussed (e.g., Ohm''s Law, voltage dividers, analog vs. digital signals). There is a heavy emphasis on programming in C++ in the Arduino IDE which will complement learning activities. Specific topics include power calculations, logic gates, capacitance, microprocessor pin functionality, switching strategies for higher powder devices (relays, transistors, MOSFETs), process control (on/off and PID controllers), and operational amplifiers. Data acquisition, smoothing, filtering, and logging strategies are also discussed. Each section has planned practical activities where circuits are built, programmed, and tested. After taking this course, students will be better equipped to build their own control circuits for undergraduate research projects and other applications.', null, 5, '{"operator": "AND", "items": ["BCH210H1", {"operator": "OR", "items": ["CHM247H1", "CHM249H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1"]}, "PHC340Y1"]}'::jsonb),
    ('PHC460H1', 'Fundamentals of Drug Discovery', '24L', 'Lectures by scientists from academia and industry, and student seminars based on journal articles dealing with strategies for discovering new drugs for therapy and diagnosis. This course is restricted to Pharmaceutical Chemistry specialist program students.', null, 4, '{"operator": "AND", "items": ["BIO120H1", "BIO130H1", "PHC301H1"]}'::jsonb),
    ('PHC462H1', 'Clinical Drug Development', '24L', 'This course is designed to broaden student''s understanding of the development and licensing of new drugs and how scientific principles, ethics, governmental regulations and commercial considerations are coordinated for designing clinical trails. The format involves lectures, group discussion and student presentations. This course is restricted to Pharmaceutical Chemistry specialist program students.', 'JFK1120H', 3, '{"operator": "AND", "items": ["PHC230H1", "PHC301H1", "PHC340Y1"]}'::jsonb),
    ('PHC470H1', 'Global Pharmaceutical Policy', '24L/2T', 'This course is designed for students who are interested in the critical analysis of global health policy and the interrelationship between global and domestic policy issues. The course will introduce students generally to the basic concepts and issues in global health with a particular focus on pharmaceutical policy. We will address key issues in health and discuss core institutional and transnational actors, how governments in different jurisdictions manage public health responsibilities, the tension between economic imperatives and health objectives, global obligations, and pressure from special interest groups. More narrowly, we will analyze a breadth of complex policies questions. Examples include: the research and development global divide, policial issues influences on pharmaceutical policy, how global commitments, such as membership in the World Trade Organization, conflict with or correspond to domestic policy directions and national sovereignty. Guest speakers will lead some sessions. This course will consist of lectures, guest discussions, case studies and student-led presentations. This is restricted to students in the Pharmaceutical Chemistry specialist program.', 'PHM320H1, PHM1124H', 3, null::jsonb),
    ('PHC489Y1', 'Pharmaceutical Chemistry Research', '165P', 'This course will provide research experience under the supervision of a Departmental staff member. The goal is to deepen the student''s understanding of the scientific basis and practical techniques relevant to modern pharmaceutical development. This course is restricted to Pharmaceutical Chemistry specialist program students. Not eligible for CR/NCR option.', null, 4, null::jsonb),
    ('PHL100Y1', 'Ancient Wisdom, Modern Insights: A Historical Introduction to Philosophy', '48L/24T', 'An introduction to the central branches of philosophy, such as logic, theory of knowledge, metaphysics, ethics, and political philosophy. Writings from the central figures in the history of Western and non-Western philosophy, as well as contemporary philosophers, may be considered. Note:  PHL100Y1 and  PHL101Y1 are both broad introductions to philosophy, and each is appropriate for students with no prior experience with the subject.', 'PHL101Y1,  PHL201H1,  PHLA10H3,  PHLA11H3,  PHL101H5,  PHL102H5,  PHL105Y5', 2, null::jsonb),
    ('PHL101Y1', 'What Should I Believe? An Introduction to Philosophical Issues', '48L/24T', 'An introduction to some of the central problems of philosophy. Examples of questions that may be considered include: What is sound reasoning? What can we know? What is ultimately real? Is morality rational? Do humans have free will? Is there a God? What is consciousness? Should we fear death? What is justice? Note:  PHL100Y1 and  PHL101Y1 are both broad introductions to philosophy, and each is appropriate for students with no prior experience with the subject.', 'PHL100Y1,  PHL201H1,  PHLA10H3,  PHLA11H3,  PHL101H5,  PHL102H5,  PHL105Y5', 2, null::jsonb),
    ('PHL196H1', 'Philosophy, Film, and Social Criticism', '48S', 'This course will critically examine the role of cinema in relation to selected topics and themes in social and political philosophy; these will vary from year to year, but may include race, ethnic and cultural ''other''-ness, class, social conflict, citizenship, cosmopolitanism, and human rights. Films will be screened in class and discussed against the background of focused critical and philosophical readings. Restricted to first-year students. Not eligible for CR/NCR option.', null, 1, null::jsonb),
    ('PHL197H1', 'Introduction to Philosophical Anthropology', '24S', 'Philosophical anthropology is the subject that poses the most fundamental questions about human nature and the human condition. Taking as its point of departure the most up-to-date scientific understanding of human nature, from anthropology broadly conceived, it goes on to inquire, in a disciplined fashion, about the implications of these views for perennial philosophical questions about human rationality, morality, the possibility of progress, the existence of god and the meaning of life. This course will examine one or more topics in this domain, as a more general introduction to the discipline. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PHL198H1', 'Philosophy of Time', '24S', 'The passage of time is a fundamental aspect of human experience: we are born, we grow older, and eventually we pass away. During our lives our experience of the past, present, and future are distinct. We can influence the world in the present and the future, but it does not seem that we can influence the past. We have hopes about the future, memories of the past, and experiences of the present. In this seminar we will explore insights from contemporary philosophy and physics concerning the nature of the passage of time. Questions to be considered may include the following: What does it mean to say that time passes? Does time really pass at all? How do we experience time? Why can we influence the future but not the past? Is it possible to travel backward in time? Is time even real? What is time? Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHL199H1', 'Ethics and Fiction', '24S', 'The goal of this seminar is to investigate selected ethical questions via works of fiction, considering how, and with what effect, fiction functions as an ethical medium. We will reflect on what fiction can teach us about pressing challenges of the human condition; themes to be discussed will vary from year to year, but may include choice and responsibility, freedom, friendship, empathy, integrity, and our relation to the divine and to death. Genres studied may range over novels, short stories, plays, and narrative poetry. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('PHL200Y1', 'Ancient Philosophy', '72L', 'Central texts of the pre-Socratics, Plato, Aristotle, and post-Aristotelian philosophy.', 'PHLB31H3,  PHL202H5', 2, null::jsonb),
    ('PHL201H1', 'Introductory Philosophy', '36L', 'An introduction to philosophy focusing on the connections among its main branches: logic, theory of knowledge, metaphysics, and ethics. This course is intended for those with little or no philosophy background but who have completed Year 1 in any area of study.', 'PHL100Y1,  PHL101Y1, or more than 1.0 PHL course', 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('PHL205H1', 'Early Medieval Philosophy', '36L', 'A study of issues such as the relations of reason and faith, the being and the nature of God, and the problem of universals, in the writings of such philosophers as Augustine, Boethius, Anselm and Abelard.', null, 2, null::jsonb),
    ('PHL206H1', 'Later Medieval Philosophy', '36L', 'A study of issues such as the relations of reason and faith, the being and the nature of God, and the structure of the universe, in the writings of such philosophers as Aquinas and Ockham.', null, 2, null::jsonb),
    ('PHL210Y1', '17th-and 18th-Century Philosophy', '72L', 'Central texts of such philosophers as Hobbes, Descartes, Spinoza, Leibniz, Locke, Berkeley, Hume, and Kant.', 'PHLB35H3,  PHL210Y5', 2, null::jsonb),
    ('PHL217H1', 'Introduction to Continental Philosophy', '36L', 'An introduction to some of the post-Hegelian thinkers who inspired the various philosophical movements broadly referred to as continental, such as phenomenology, existentialism, deconstruction, and post-modernism. Questions include the will, faith, death, existence, history and politics, rationality and its limits, encountering an other. Authors studied may include: Kierkegaard, Schopenhauer, Nietzsche, Marx, Freud, Heidegger, Sartre.', null, 2, null::jsonb),
    ('PHL232H1', 'Knowledge and Reality', '36L', 'An introduction to issues in the fundamental branches of philosophy: metaphysics, which considers the overall framework of reality; epistemology, or the theory of knowledge; and related problems in the philosophy of science. Topics in metaphysics may include: mind and body, causality, space and time, God, freedom and determinism; topics in epistemology may include perception, evidence, belief, truth, skepticism.', 'PHLB20H3,  PHLB60H3', 2, null::jsonb),
    ('PHL233H1', 'Philosophy for Scientists', '24L/12T', 'An introduction to philosophy tailored for students with backgrounds in mathematics and science. Topics include causation, explanation, the relation between scientific and mathematical theories and reality, the role of mathematics in scientific theories, the relevance of scientific and mathematical discoveries to ''big'' traditional philosophical questions such as the nature of consciousness, whether we have free will, and the meaning of life.', null, 2, null::jsonb),
    ('PHL235H1', 'Philosophy of Religion', '36L', 'Some central issues in the philosophy of religion such as the nature of religion and religious faith, arguments for the existence of God, the problem of evil, varieties of religious experience, religion and human autonomy.', 'PHL235H5', 2, null::jsonb),
    ('PHL236H1', 'Buddhist Philosophy', '36L', 'This course is an introduction to topics, schools, and figures in Buddhist philosophy. Texts to be read (in English translation) will range from the Pāli Canon (attributed directly to the Buddha) via Sanskrit and Tibetan Buddhist schools to contemporary Buddhist reflections. Themes and topics will be selected from those prominent in Buddhist texts: emptiness, impermanence, and non-selfhood; the theory of inference; perception and epistemology; philosophy of language; and philosophy of action. Texts and authors to be studied will standardly include the Pāli Canon, and one or more among Nāgārjuna, Vasubandhu, Dharmakīrti, Milarepa and contemporary Buddhist thinkers.', null, 2, null::jsonb),
    ('PHL237H1', 'Introduction to Chinese Philosophy', '36L', 'A historical introduction to Chinese philosophy, covering selected figures and texts from the Warring States period through the Qīng dynasty. Schools of thought covered include Confucianism, Mohism, Daoism, Legalism, "Profound Learning," Neo-Confucianism, and "Evidential Learning." Texts and thinkers include the Confucian Analects, Mòzǐ, Mèngzǐ, Xúnzǐ, Dàodéjīng, Zhuāngzǐ, Hán Fēi, Guō Xiàng, Zhū Xī, Wáng Yángmíng, and Dài Zhèn.', 'EAS241H1', 2, null::jsonb),
    ('PHL238H1', 'Reason and Irrationality', '36L', 'How does one live one''s life without falling victim to various forms of irrationality? This course offers theoretical insight and practical guidance regarding norms of rationality and how we can live by them. Topics to be addressed include: informal logic; criteria for the assessment of arguments; common fallacies; truth and noncontradiction as norms; cognitive biases; "thinking fast and slow" and behavioral economics; conspiracy theories; and media ethics.', 'TRN200Y1,  PHL247H1,  PHL145H5,  PHL238H5,  PHL247H5', 2, null::jsonb),
    ('PHL239H1', 'Introduction to South Asian Philosophy', '36L', 'An introduction to the main schools, thinkers, and topics in the philosophical thought of the Sanskrit world, covering various topics, from epistemology to philosophy of religion. Students will get acquainted with one of the world''s richest philosophical traditions and its challenges.', null, 2, null::jsonb),
    ('PHL240H1', 'Persons, Minds and Bodies', '36L', 'Consciousness and its relation to the body; personal identity and survival; knowledge of other minds; psychological events and behaviour.', 'PHLB81H3', 2, null::jsonb),
    ('PHL243H1', 'Philosophy of Human Sexuality', '36L', 'Philosophical issues about sex and sexual identity in the light of biological, psychological and ethical theories of sex and gender; the concept of gender; male and female sex roles; perverse sex; sexual liberation; love and sexuality.', 'PHLB12H3,  PHL243H5', 2, null::jsonb),
    ('PHL244H1', 'Human Nature', '36L', 'Aspects of human nature, e.g., emotion, instincts, motivation. Theories of human nature, e.g., behaviourism, psychoanalysis.', 'PHLB91H3,  PHL244H5', 2, null::jsonb),
    ('PHL245H1', 'Modern Symbolic Logic', '36L', 'An introduction to formal deductive logic. Semantics, symbolization, and techniques of natural deduction in sentential logic. Symbolization, natural deduction, and models in monadic predicate logic. Symbolization and natural deduction with polyadic predicates. Introduction to advanced concepts in first-order logic, such as operations, identity, and models.', 'PHLB50H3,  PHL245H5', 2, null::jsonb),
    ('PHL246H1', 'Probability and Inductive Logic', '36L', 'The elements of axiomatic probability theory and its main interpretations (frequency, logical, and subjective). Reasoning with probabilities in decision-making and science.', 'PHL246H5', 2, null::jsonb),
    ('PHL255H1', 'Philosophy of Science', '24L/12T', 'This course is an introduction to contemporary topics in the philosophy of science which serves as preparation for more advanced study in general philosophy of science and philosophy of the particular sciences. Topics may include the rise and fall of logical positivism, the problem of demarcation, falsificationism, confirmation, the connection between theory and observation, the value free ideal, and the epistemic authority of scientists.', 'HPS250H1', 5, null::jsonb),
    ('PHL256H1', 'Philosophy of the Internet', '36L', 'The internet and digital technology have had a transformative impact on the economy, society and politics, art and culture, and everyday life. This course explores the fascinating, often urgent, new philosophical questions raised by these changes as well as the way they invite a rethinking of many older philosophical questions. Topics to be addressed may include ethical problems relating to artificial intelligence and algorithms; identity through social media; digital ownership and privacy; and collective/distributed knowledge in its relation to information, among others.', null, 2, null::jsonb),
    ('PHL265H1', 'Introduction to Political Philosophy', '36L', 'An introduction to central issues in political philosophy, e.g., political and social justice, liberty and the criteria of good government. The writings of contemporary political philosophers, as well as major figures in the history of philosophy, may be considered.', 'PHLB17H3,  PHL265H5', 3, null::jsonb),
    ('PHL268H1', 'Philosophy and Social Criticism', '36L', 'Is the objective of philosophy to understand and interpret the world, or to change it? A study of theorists who have taken philosophy to be a tool for social criticism. Topics studied may include feminism, critical race theory, anti-consumerism, the critique of mass society, new social movements and conservative cultural criticism.', null, 3, null::jsonb),
    ('PHL269H1', 'Philosophy of Race', '24L/12T', 'What is the meaning of race? How does it affect political philosophy? Is there an ethics of race? These are some of the questions that will be covered in this course on the critical philosophy of race. Students will be introduced to problems concerning the metaphysics of race, race and political injustice, ethics and recognition, race and aesthetic critique, and others.', null, 3, null::jsonb),
    ('PHL271H1', 'Law and Morality', '36L', 'Justifications for the legal enforcement of morality; particular ethical issues arising out of the intersection of law and morality, such as punishment, freedom of expression and censorship, autonomy and paternalism, constitutional protection of human rights.', 'PHLB11H3,  PHL271H5', 3, null::jsonb),
    ('PHL273H1', 'Environmental Ethics', '36L', 'A study of environmental issues raising questions of concern to moral and political philosophers, such as property rights, responsibility for future generations, and the interaction of human beings with the rest of nature. Typical issues: sustainable development, alternative energy, the preservation of wilderness areas, animal rights.', 'PHLB02H3,  PHL273H5', 3, null::jsonb),
    ('PHL275H1', 'Introduction to Ethics', '36L', 'An introduction to central issues in ethics or moral philosophy, such as the objectivity of values, the nature of moral judgements, rights and duties, the virtues, and consequentialism. Readings may be drawn from a variety of contemporary and historical sources.', 'PHLB07H3,  PHL275H5', 2, null::jsonb),
    ('PHL276H1', 'Philosophy of Sports', '24L/12T', 'Sports play a complex role in contemporary society. They offer recreational participants a source of meaning in life and professional participants a livelihood. They inspire intense devotion from fans. They are a crucible for debates about fair play, medical enhancement, sex, gender, race, and sexuality. This course will explore the nature and ethics of sports.', null, 3, null::jsonb),
    ('PHL277H1', 'Ethics and Data', '24L/12T', 'An introduction to fundamental ethical problems raised by “Big Data.” Topics may include: fairness in data collection; algorithmic discrimination; data privacy; and moral puzzles stemming from the application of machine learning to everyday decision-making.', null, 2, null::jsonb),
    ('PHL281H1', 'Bioethics', '36L', 'An introduction to the study of moral and legal problems in medical practice and in biomedical research; the development of health policy. Topics include: concepts of health and disease, patient rights, informed consent, allocation of scarce resources, euthanasia, abortion, genetic and reproductive technologies, human research, and mental health.', 'PHLB09H3,  PHL283H5', 3, null::jsonb),
    ('PHL285H1', 'Aesthetics', '36L', 'An historical and systematic introduction to the main questions in the philosophy of art and beauty from Plato to the present. These include the relation between art and beauty, the nature of aesthetic experience, definitions and theories of art, the criteria of excellence in the arts, and the function of art criticism.', 'PHLB03H3,  PHL285H5', 1, null::jsonb),
    ('PHL295H1', 'Business Ethics', '36L', 'Philosophical issues in ethics, social theory, and theories of human nature insofar as they bear on contemporary conduct of business. Issues include: Does business have moral responsibilities? Can social costs and benefits be calculated? Does modern business life determine human nature or the other way around? Do political ideas and institutions such as democracy have a role within business?', 'PHLB06H3,  PHL295H5', 3, null::jsonb),
    ('PHL299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL301H1', 'Early Greek Philosophy', '36L', 'A study of selected Greek philosophers before Plato. Topics may include the Pre-Socratic natural philosophers, Parmenides and the Eleatics, and the so-called sophistic movement.', null, 2, '{"operator": "AND", "items": ["PHL200Y1"]}'::jsonb),
    ('PHL302H1', 'Ancient Philosophy After Aristotle', '36L', 'A study of selected themes in post-Aristotelian philosophy. Topics may include Stoicism, Epicureanism, Neoplatonism, and various forms of scepticism.', null, 2, '{"operator": "AND", "items": ["PHL200Y1"]}'::jsonb),
    ('PHL303H1', 'Plato', '36L', 'Selected metaphysical, epistemological, and ethical themes in Plato''s dialogues.', 'PHL301H5', 2, '{"operator": "AND", "items": ["PHL200Y1"]}'::jsonb),
    ('PHL304H1', 'Aristotle', '36L', 'Selected anthropological, ethical and metaphysical themes in the works of Aristotle.', 'PHL302H5', 2, '{"operator": "AND", "items": ["PHL200Y1"]}'::jsonb),
    ('PHL305H1', 'Classical Islamic Philosophy', '36L', 'An introduction to the major thinkers in classical Islamic philosophy, with emphasis placed on developing a properly philosophical understanding of the issues and arguments. Topics include the existence of God; creation and causality; human nature and knowledge; the nature of ethical obligations; and the constitution of the ideal political state.', null, 2, '{"operator": "AND", "items": ["PHL200Y1", {"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL306H1', 'Post-Classical Islamic Philosophy', '36L', 'An advanced introduction to philosophical movements in the Islamic world in the wake of Avicenna. Topics include developments in metaphysics, epistemology, philosophy of mind, value theory, and philosophical methodology from the 12th to the 17th century that arose in response to new social, political, religious, and scientific currents.', null, 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL307H1', 'Augustine', '36L', 'Central themes in St. Augustine''s Christian philosophy, such as the problem of evil, the interior way to God, the goal of human life and the meaning of history.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL200Y1", "PHL205H1"]}]}'::jsonb),
    ('PHL308H1', 'Aquinas', '36L', 'Philosophical innovations that St. Thomas Aquinas made in the course of constructing a systematic theology: essence and existence, the Five Ways, separate intelligences, the human soul and ethics.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL200Y1", "PHL205H1", "PHL206H1"]}]}'::jsonb),
    ('PHL309H1', 'Topics in Medieval Philosophy', '36L', 'Study of a major philosophical figure from the medieval period, such as Anselm, Abelard, Bonaventure, Maimonides, Avicenna, Duns Scotus, William of Ockham; or consideration of a central philosophical topic in a variety of medieval authors, for example, universals, individuation, the existence of God, free will and free choice, eternity and creation.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL200Y1", "PHL205H1", "PHL206H1"]}]}'::jsonb),
    ('PHL310H1', 'The Rationalists', '36L', 'Central philosophical problems in philosophers such as Descartes, Spinoza, Leibniz, and their contemporaries.', 'PHLC35H3', 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL311H1', 'The Empiricists', '36L', 'Central philosophical problems in philosophers such as Locke, Berkeley, Hume, and their contemporaries.', 'PHLC36H3', 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL313H1', 'Topics in 17th and 18th Century Philosophy', '36L', 'Central philosophical problems arising in the early modern period.', 'PHL313H5', 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL314H1', 'Kant', '36L', 'A systematic study of The Critique of Pure Reason.', 'PHLC37H3,  PHL314H5', 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL315H1', 'Topics in 19th-Century Philosophy', '36L', 'Central philosophical problems arising in the 19th century.', 'PHL315H5', 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL316H1', 'Hegel', '36L', 'An examination of Hegel''s project of absolute knowing, its philosophical assumptions, and its implications for history, science and experience.', null, 2, '{"operator": "AND", "items": ["PHL210Y1"]}'::jsonb),
    ('PHL317H1', 'Marx and Marxism', '36L', 'An examination of some of the leading themes in the philosophy of Karl Marx. Developments of Marxist philosophy by later thinkers, and critics of Marxism, may also be considered.', null, 2, null::jsonb),
    ('PHL319H1', 'Philosophy and Psychoanalytic Theory', '36L', 'A study of the fundamentals of psychoanalytic theory from a philosophical perspective, focusing on the works of Freud and others. Topics include mind (conscious and unconscious), instinctual drives, mechanisms of defence, the structure of personality, civilization, the nature of conscience, and the status of psychoanalysis.', null, 2, null::jsonb),
    ('PHL320H1', 'Phenomenology', '36L', 'Phenomenology is a method used in the analysis of human awareness and subjectivity. It has been applied in the social sciences, in the humanities, and in philosophy. Texts studied are from Husserl and later practitioners, e.g., Heidegger, Sartre, Merleau-Ponty, Gurwitsch, and Ricoeur.', null, 2, '{"operator": "OR", "items": ["PHL210Y1", "PHL217H1"]}'::jsonb),
    ('PHL321H1', 'Heidegger', '36L', 'Some work from the 1920s (either Being and Time or contemporary lectures) and selections from Heidegger''s later work on poetry, technology, and history are studied. Heidegger''s position within phenomenology and within the broader history of thought is charted.', null, 2, '{"operator": "AND", "items": ["PHL217H1"]}'::jsonb),
    ('PHL323H1', 'Social and Cultural Theory', '36L', 'A study of philosophical approaches to understanding various aspects of contemporary culture and/or society. Topics may include theories of modernity, capitalism and consumerism, architecture and design, cultural pluralism, globalization, media and internet.', null, 3, null::jsonb),
    ('PHL325H1', 'Early Analytic Philosophy', '36L', 'An examination of some of the classic texts of early analytic philosophy, concentrating on the work of Frege, Russell, and Wittgenstein.', 'PHLC43H3,  PHL325H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}]}'::jsonb),
    ('PHL327H1', 'Ethics and Religion in Sanskrit Philosophy', '36L', 'This course covers topics in Sanskrit philosophy, with a special focus on ethics and/or philosophy of religion. Students will investigate specific primary texts (in translation) and will learn how to recognize and analyze the philosophical arguments they contain. Example texts and ideas include: theology and atheism in various Sanskrit schools (with selected readings from Dharmakīrti, Udayana, Rāmānuja etc.); the place of ethics in Sanskrit philosophy and beyond (with selected readings from Śāntideva, B.K. Matilal and epic and juridical texts).', null, 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL328H1', 'Metaphysics and Epistemology in Sanskrit Philosophy', '36L', 'This course covers topics in Sanskrit philosophy, with a special focus on metaphysics and epistemology (and related issues in philosophy of language and logic). Students will investigate specific primary texts (in translation) and will learn how to recognize and analyze the philosophical arguments they contain. Example texts and ideas include: the Upaniṣads, the Mahābhārata, the Buddhist dialogues, the Nyāya- and Vaiśeṣika-sūtra, the works of Dignāga, and others.', null, 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": null}]}'::jsonb),
    ('PHL329H1', 'Topics in 20th Century Continental Philosophy', '36L', 'Selected topics and themes in continental philosophy of the 20th century, drawing on such approaches as hermeneutics, phenomenology, critical theory, structuralism, deconstruction, feminism, psychoanalysis, and post-colonial theory. Authors and texts will vary, but may include such authors as: Adorno, Arendt, Benjamin, Bloch, Deleuze, Derrida, Fanon, Foucault, Freud, Gadamer, Habermas, Heidegger, Irigaray, Kristeva, Lacan, Levi-Strauss, Levinas, Merleau-Ponty.', 'PHL322H1,  PHL324H5', 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, "PHL217H1", {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL330H1', 'Contemporary Continental Philosophy', '36L', 'A discussion of selected problems and debates in recent Continental philosophy. Authors and texts will vary, but may include such authors as: Giorgio Agamben, Alain Badiou, Étienne Balibar, Judith Butler, Jacques Derrida, Catherine Malabou, Achille Mbembe, Quentin Meillassoux, Jean-Luc Nancy, Jacques Rancière, Gayatri Spivak, Slavoj Žižek, Sylvia Wynter.', null, 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, "PHL217H1", {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL331H1', 'Metaphysics', '36L', 'Historical and systematic approaches to topics in metaphysics, such as the nature of reality, substance and existence, necessity and possibility, causality, universals and particulars.', 'PHLC60H3,  PHL332H5', 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}, {"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}]}'::jsonb),
    ('PHL332H1', 'Epistemology', '36L', 'Historical and systematic approaches to topics in the theory of knowledge, such as truth, belief, justification, perception, a priori knowledge, certitude, skepticism, other minds.', 'PHLC20H3,  PHL333H5', 2, '{"operator": "OR", "items": ["PHL232H1", "PHL233H1"]}'::jsonb),
    ('PHL333H1', 'Puzzles and Paradoxes', '36L', 'Time travel, truth, infinity, rational decision making: each of these topics gives rise to philosophical puzzles and paradoxes. In this class we''ll consider a variety of such paradoxes. Using logic and other philosophical tools, we''ll show how these paradoxes can lead to deep and important philosophical conclusions.', 'PHLB55H3', 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": null}, {"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}]}'::jsonb),
    ('PHL334H1', 'Mind and Language in Chinese Thought', null, 'Issues in the philosophy of mind and language played a crucial role in the philosophical discourse of classical China. This course will guide students in reconstructing this role and exploring its philosophical significance by interpreting and critically evaluating selected early Chinese philosophical texts that treat mind, language, and interrelated aspects of psychology. Topics to be discussed include the nature and functions of names and speech; the role of "correcting names"; semantic theory and argumentation; perception and knowledge; the role of language in knowledge and action; and the ontological grounds of linguistic distinctions. Texts to be discussed include the Analects, Guǎnzǐ, Mòzǐ, Mèngzǐ, Dàodéjīng, Xúnzǐ, Zhuāngzǐ, and Annals of Mr. Lǚ.', 'EAS338H1', 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}, "PHL237H1"]}'::jsonb),
    ('PHL335H1', 'Issues in Philosophy of Religion', '36L', 'Some specific problem(s) in the philosophy of religion, such as the relationship of religious faith and religious belief, the ontological argument for the existence of God, theories about divine transcendence, the philosophical presuppositions of religious doctrines, the modern critique of religion.', null, 2, null::jsonb),
    ('PHL337H1', 'Classical Chinese Ethics', '36L', 'This course explores and critiques personal and social ethical ideals as presented in early Chinese Confucian, Mohist, and Daoist writings and considers their relevance to issues in contemporary ethics. Major texts discussed include the Analects, Mèngzǐ, Xúnzǐ, Mòzǐ, Dàodéjīng, and Zhuāngzǐ. Central questions examined include: What is the way (dào)? What standards can guide us in following the way? What grounds can we have for confidence that these are the correct standards? What kind of person should we strive to be? What is virtue (dé)? What values take priority in a life of virtue? How does the person of virtue act?', null, 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"credits": 1.5, "department": "PHL"}, "PHL237H1"]}'::jsonb),
    ('PHL338H1', 'Jewish Philosophy', '36L', 'A selection of texts and issues in Jewish philosophy, for example, Maimonides'' Guide of the Perplexed, Buber''s The Prophetic Faith, prophecy and revelation, Divine Command and morality, creation and eternity, the historical dimension of Jewish thought.', null, 2, null::jsonb),
    ('PHL340H1', 'Issues in Philosophy of Mind', '36L', 'Typical issues include: the mind-brain identity theory; intentionality and the mental; personal identity.', 'PHLC95H3,  PHL340H5', 2, '{"operator": "OR", "items": ["COG250Y1", "PHL240H1"]}'::jsonb),
    ('PHL341H1', 'Freedom, Responsibility, and Human Action', '36L', 'Human action, and the nature of freedom and responsibility in the light of contemporary knowledge concerning the causation of behaviour.', 'PHL341H5', 2, '{"operator": "OR", "items": ["PHL210Y1", "PHL232H1", "PHL233H1", "PHL240H1"]}'::jsonb),
    ('PHL342H1', 'Minds and Machines', '36L', 'An investigation of philosophical questions raised by contemporary cognitive science and artificial intelligence (AI). Possible topics to be addressed: whether machines could think and be conscious; the computational theory of mind; embodied cognition and the extended mind hypothesis; the "singularity"; and moral and political implications of machine learning research.', null, 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["COG250Y1", {"credits": 1.5, "department": "PHL"}]}]}'::jsonb),
    ('PHL344H1', 'Philosophy of Emotions', '36L', 'A survey of philosophical topics related to the emotions, from a range of philosophical perspectives. Questions to be considered may include the following: What exactly is an emotion? Are emotions feelings? What emotions are there, and how are they shaped by culture and society? How are emotions related to reason, the brain and the body? What role do -- and should -- the emotions play in decision-making? Can an emotion be morally right or wrong, and what makes it so?', null, 2, '{"operator": "OR", "items": ["PHL240H1", "PHL244H1", "PHL342H1"]}'::jsonb),
    ('PHL345H1', 'Intermediate Logic', '36L', 'A continuation of  PHL245H1, requiring no other prior knowledge of philosophy or mathematics. First-order logic, including basic metalogical results such as soundness and completeness. An introduction to basic set theory and metalogic. Topics may include the Loewenheim-Skolem theorems for first-order logic, Goedel''s incompleteness theorems.', 'PHLC51H3,  PHL345H5', 2, '{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}'::jsonb),
    ('PHL347H1', 'Modal Logic and Philosophical Applications of Logic', '36L', 'Formal study of the concepts of necessity and possibility, modal, propositional and quantificational logic, possible-worlds semantics, and the metaphysics of modality. Other topics may include counterfactuals, truth, vagueness, epistemic logic, temporal logic, or non-classical logic.', 'PHL347H5', 2, '{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}'::jsonb),
    ('PHL348H1', 'Logic and Computation', '36L', 'Topics will include Kurt Gödel''s celebrated incompleteness theorems, the technical ideas and methods involved in proving them, their relation to the abstract theory of computation, and their philosophical implications. Are there mathematical truths that cannot be known? Are mathematical concepts such as number and set indeterminate to some extent? Are there limits to what can be modeled formally?', 'MAT309H1/ CSC438H1', 2, '{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}'::jsonb),
    ('PHL349H1', 'Set Theory', '36L', 'An introduction to set theory emphasizing its philosophical relevance as a unifying framework for mathematics and logic. Topics examined may include the paradoxes of the ''naïve'' conception of sets and their resolution through axiomatization, the construction of natural numbers and real numbers in set theory, equivalents of the axiom of choice, and model theory.', null, 2, '{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}'::jsonb),
    ('PHL351H1', 'Philosophy of Language', '36L', 'The nature of language as a system of human communication, theories of meaning and meaningfulness, the relation of language to the world and to the human mind.', 'PHLC80H3,  PHL350H5', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}]}'::jsonb),
    ('PHL354H1', 'Philosophy of Mathematics', '36L', 'Platonism versus nominalism, the relation between logic and mathematics, implications of Gödel''s theorem, formalism and intuitionism.', 'PHL346H1,  PHL346H5,  PHL344H5,  PHL354H5', 2, '{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}'::jsonb),
    ('PHL355H1', 'Philosophy of Natural Science', '36L', 'The structure and methods of science: explanation, methodology, realism and instrumentalism.', 'PHL355H5', 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"operator": "OR", "items": [{"operator": "AND", "items": ["PHL255H1", {"credits": 1.0, "department": "PHL"}]}, {"operator": "AND", "items": [{"credits": 1.5, "department": "PHL"}, "HPS250H1"]}]}]}'::jsonb),
    ('PHL356H1', 'Philosophy of Physics', '36L', 'Introduction to philosophical issues which arise in modern physics, especially in relativity and quantum mechanics. This course will be accessible to students without a significant background in physics, but with an interest in the philosophical challenges that modern physics poses.', null, 5, null::jsonb),
    ('PHL357H1', 'Philosophy of Biology', '36L', 'Philosophical issues in the foundations of biology, e.g., the nature of life, evolutionary theory; controversies about natural selection; competing mechanisms, units of selection; the place of teleology in biology; biological puzzles about sex and sexual reproduction; the problem of species; genetics and reductionism; sociobiology; natural and artificial life.', 'PHL357H5', 2, '{"operator": "AND", "items": [{"credits": 7.5, "department": null}, {"operator": "OR", "items": [{"operator": "AND", "items": ["PHL255H1", {"credits": 1.0, "department": "PHL"}]}, {"operator": "AND", "items": [{"credits": 1.5, "department": "PHL"}, "HPS250H1"]}, {"credits": 1.5, "department": null}]}]}'::jsonb),
    ('PHL358H1', 'Philosophy of Psychiatry', '36L', 'An advanced introduction to topics at the intersection of philosophy and psychiatry. Topics may include: what makes something a psychiatric disease? What can psychiatric syndromes tell us about the nature of moods and decision-making? Do some psychiatric patients act with less agency, and should they have less moral or criminal responsibility?', null, 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": [{"credits": 1.5, "department": "PHL"}, {"operator": "AND", "items": [{"credits": 1.0, "department": "PHL"}, "PSY240H1"]}]}]}'::jsonb),
    ('PHL362H1', 'Philosophy of History', '36L', 'Typical questions include: Has history any meaning? Can there be general theories of history? How are the findings of historians related to the theories of metaphysics and of science? Is history deterministic? Must the historian make value judgements? Is history science or an art? Are there historical forces or spirits of an epoch?', null, 2, null::jsonb),
    ('PHL365H1', 'Political Philosophy', '36L', 'A study of some of the central problems of political philosophy, addressed by historical and contemporary political theorists.', 'PHLC92H3', 2, '{"operator": "OR", "items": ["PHL265H1", "POL200Y1"]}'::jsonb),
    ('PHL366H1', 'Topics in Political Philosophy', '39L', 'A focused examination of a selected issue in political philosophy.', null, 2, '{"operator": "OR", "items": ["PHL265H1", "POL200Y1"]}'::jsonb),
    ('PHL367H1', 'Philosophy of Feminism', '36L', 'Selected issues and topics in the philosophy of feminism.', 'PHLC13H3,  PHL367H5', 2, '{"operator": "OR", "items": ["PHL265H1", "PHL268H1"]}'::jsonb),
    ('PHL369H1', 'Philosophy of Race, Gender, and Capitalism', '36L', 'How should our understanding of capitalism be shaped by the realities of racial domination and gender oppression? What are the different accounts of justice and injustice that would emerge from trying to think through these three phenomena together? Or are they really one phenomenon? This course will survey the complex philosophical debates, both historical and contemporary, concerning the specificities and interrelationships between race, gender, and capitalism.', 'PHLC13H3,  PHL367H5', 2, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"operator": "OR", "items": ["PHL265H1", "PHL268H1", "PHL269H1"]}, {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL370H1', 'Issues in Philosophy of Law', '36L', 'Major issues in philosophy of law, such as legal positivism and its critics, law and liberalism, feminist critiques of law, punishment and responsibility.', 'PHL370H5', 2, '{"operator": "AND", "items": ["PHL271H1"]}'::jsonb),
    ('PHL373H1', 'Issues in Environmental Ethics', '36L', 'An intermediate-level examination of key issues in environmental philosophy, such as the ethics of animal welfare, duties to future generations, deep ecology, ecofeminism, sustainable development and international justice.', null, 2, '{"operator": "AND", "items": ["PHL273H1"]}'::jsonb),
    ('PHL375H1', 'Ethics', '36L', 'An intermediate-level study of selected issues in moral philosophy, or of influential contemporary or historical works in ethical theory.', 'PHLC05H3', 2, '{"operator": "AND", "items": ["PHL275H1"]}'::jsonb),
    ('PHL376H1', 'Topics in Moral Philosophy', '36L', 'A focused examination of a selected issue in moral philosophy.', 'PHLC06H3', 2, '{"operator": "AND", "items": ["PHL275H1"]}'::jsonb),
    ('PHL377H1', 'Ethical Issues in Big Data', '36L', 'An intermediate-level treatment of fundamental ethical problems arising in "Big Data" and artificial intelligence. Formal tools from economics and statistics will be applied to emerging ethical technology issues such as model transparency, data bias, and privacy. Broader political issues such as the geopolitics of AI may also be covered.', null, 2, '{"operator": "AND", "items": [{"credits": 9.0, "department": null}, {"credits": 1.5, "department": "PHL"}, {"operator": "OR", "items": ["PHL273H1", "PHL275H1", "PHL281H1", "PHL295H1"]}]}'::jsonb),
    ('PHL378H1', 'War and Morality', '36L', 'Moral and political issues concerning warfare: the theory of the just war, pacifism, moral constraints on the conduct of war, war as an instrument of foreign policy, the strategy of deterrence. Special attention to the implications of nuclear weapons.', null, 2, '{"operator": "OR", "items": ["PHL265H1", "PHL275H1"]}'::jsonb),
    ('PHL380H1', 'Global Bioethics', '36L', 'An intermediate-level study of moral problems that arise in international contexts, including issues of special interest in bioethics: moral universalism and relativism; global distributive justice; poverty relief and international aid; international health disparities; globalization and health; HIV/AIDS; intellectual property and access to essential medicines; clinical trials in developing countries; exploitation and the 10/90 gap.', null, 2, '{"operator": "AND", "items": ["PHL281H1"]}'::jsonb),
    ('PHL381H1', 'Ethics and Medical Research', '36L', 'An intermediate-level study of problems in biomedical and behavioural research with human subjects: informed voluntary consent, risk and benefit, experimental therapy, randomized clinical trials, research codes and legal issues, dependent groups (human embryos, children, the aged, hospital patients, the dying, prisoners, the mentally ill.', null, 2, '{"operator": "AND", "items": ["PHL281H1"]}'::jsonb),
    ('PHL382H1', 'Ethics: Death and Dying', '36L', 'An intermediate-level study of moral and legal problems, including the philosophical significance of death, the high-tech prolongation of life, definition and determination of death, suicide, active and passive euthanasia, the withholding of treatment, palliative care and the control of pain, living wills; recent judicial decisions.', null, 2, '{"operator": "AND", "items": ["PHL281H1"]}'::jsonb),
    ('PHL383H1', 'Ethics and Mental Health', '36L', 'An intermediate-level study of moral and legal problems, including the concepts of mental health and illness, mental competence, dangerousness and psychiatric confidentiality, mental institutionalization, involuntary treatment and behaviour control, controversial therapies; legal issues: the Mental Health Act, involuntary commitment, the insanity defence.', null, 2, '{"operator": "AND", "items": ["PHL281H1"]}'::jsonb),
    ('PHL384H1', 'Ethics, Genetics and Reproduction', '36L', 'An intermediate-level study of moral and legal problems, including the ontological and moral status of the human embryo and fetus; human newborn, carrier and prenatal genetic screening for genetic defect, genetic therapy; the reproductive technologies (e.g., artificial insemination, in vitro fertilization); recent legislative proposals and judicial decisions.', null, 2, '{"operator": "AND", "items": ["PHL281H1"]}'::jsonb),
    ('PHL385H1', 'Issues in Aesthetics', '36L', 'Selected topics in the philosophy of art. Such issues as the following are discussed: whether different arts require different aesthetic principles; relations between art and language; the adequacy of traditional aesthetics to recent developments in the arts; art as an institution.', 'PHLC03H3', 1, null::jsonb),
    ('PHL388H1', 'Literature and Philosophy', '36L', 'An examination of the interplays and tensions between literature and philosophy. Possible themes include: the ''literary'' expression of philosophical ideas; the ancient ''quarrel of the poets and philosophers''; the relation of form to content in philosophical writing, and the immense variety of philosophical genres (e.g. aphorism, essai, confession, treatise, dialogue, manifesto, meditation, etc.); the philosophical content and significance of certain ''literary'' works and forms; and philosophical problems regarding translation, adaptation, and interpretation. Topics and texts will vary according to instructor.', null, 1, '{"operator": "AND", "items": [{"credits": 8.0, "department": null}, {"credits": 1.5, "department": "PHL"}]}'::jsonb),
    ('PHL394H1', 'Markets and Morals', '36L', 'A study of the standards that can be used to judge the performance of economic systems, e.g., efficiency, fairness, maximization, along with the different institutional mechanisms that can be used to organize economic activity, e.g., markets or hierarchies, public or private ownership.', null, 3, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL265H1", "PHL275H1", "POL200Y1"]}]}'::jsonb),
    ('PHL395H1', 'Issues in Business Ethics', '36L', 'A focused examination of moral issues that arise in the conduct of business, in areas such as accounting and finance, corporate governance, human resources, environmental conduct, business lobbying and regulatory compliance.', null, 3, '{"operator": "AND", "items": ["PHL295H1"]}'::jsonb),
    ('PHL398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHL400H1', 'Seminar in Ancient/Medieval Philosophy', '36S', 'Advanced discussion of the principal figures and themes in ancient and/or medieval philosophy.', null, null, '{"operator": "AND", "items": ["PHL200Y1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL401H1', 'Seminar in the History of Philosophy', '36S', 'Advanced study of some of the principal figures in a particular historical, philosophical tradition.', null, null, '{"operator": "OR", "items": ["PHL200Y1", "PHL210Y1"]}'::jsonb),
    ('PHL402H1', 'Seminar in Early Modern Philosophy', '36S', 'Advanced discussion of the principal figures and themes in the philosophy of the 17th and/or 18th centuries.', null, null, '{"operator": "AND", "items": ["PHL210Y1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL403H1', 'Seminar in 19th-Century Philosophy', '36S', 'Advanced discussion of some principal figures and themes in 19th century philosophy.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL210Y1", "PHL217H1", "PHL315H1", "PHL316H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL404H1', 'Seminar in Epistemology', '36S', 'Typical problems include the nature of knowledge and belief; perception; theories of truth and necessity; skepticism.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL232H1", "PHL233H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL405H1', 'Seminar in Philosophy of Mind', '36S', 'Advanced study of a problem in the philosophy of mind.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL240H1", "PHL342H1", "COG250Y1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL406H1', 'Seminar in Metaphysics', '36S', 'Typical problems include causality and determinism; ontological categories; mind and body; the objectivity of space and time.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": "PHL"}, {"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}]}'::jsonb),
    ('PHL407H1', 'Seminar in Ethics', '36S', 'Advanced discussion of issues in moral philosophy, including issues of applied ethics.', null, null, '{"operator": "AND", "items": ["PHL275H1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL408H1', 'Seminar in Philosophy', '36S', 'Topics vary but bridge two or more areas or traditions of philosophy.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL409H1', 'New Books Seminar', '36S', 'Advanced study of key philosophical works published within the last five years.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL410H1', 'Seminar in Continental Philosophy', '36S', 'Advanced study of recent philosophical discussions within the continental tradition.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL217H1", "PHL315H1", "PHL316H1", "PHL319H1", "PHL320H1", "PHL321H1", "PHL322H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL411H1', 'Seminar in Analytic Philosophy', '36S', 'Advanced study of some topic of current philosophical interest within the analytic tradition.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL412H1', 'Seminar in Political Philosophy', '36S', 'Advanced study of some topic in social or political philosophy.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL265H1", "PHL271H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL413H1', 'Seminar in Applied Ethics', '36S', 'Advanced study of some topic in an area of applied ethics, including bioethics, environmental ethics, and so on.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL271H1", "PHL273H1", "PHL275H1", "PHL281H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL414H1', 'Seminar in Philosophy of Religion', '36S', 'Advanced study of topics in the philosophy of religion.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL235H1", "PHL335H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL416H1', 'Seminar in Philosophy of Law', '36S', 'Advanced discussion of issues in the philosophy of law.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL265H1", "PHL271H1"]}, {"operator": "OR", "items": ["PHL365H1", "PHL370H1", "PHL375H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL417H1', 'Seminar in History of Analytic Philosophy', '36S', 'Advanced study of a figure or topic from the history of analytic philosophy.', null, 2, '{"operator": "AND", "items": ["PHL325H1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL418H1', 'Seminar in Sanskrit Philosophy', '36S', 'Advanced study of one or more topics in Sanskrit Philosophy.', null, 2, '{"operator": "AND", "items": [{"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL440H1', 'Clinical Bioethics', '36S', 'Advanced study of topics in bioethics, taught in conjunction with clinical bioethicists associated with the health care organization partners of the University of Toronto Joint Centre for Bioethics.', null, null, '{"operator": "AND", "items": ["PHL281H1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL445H1', 'Metalogic', '36S', 'A continuation of  PHL345H1, this is a course in the mathematical study of logic, also known as metalogic. We will investigate and prove theorems about logical systems. Topics covered may include: important results in metalogic, second and higher-order logic, or lambda-calculus.', 'PHL445H5;  PHLD51H3', 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL345H1", "MAT309H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL446H1', 'Seminar in Decision Theory', '36S', 'Decision theory studies what one ought to do when some more or less desirable outcomes of one''s actions depend on external facts about which one is uncertain. Uncertainty is characterized in terms of probabilities, desires are characterized in terms of utilities, and together they determine the expected utility of one''s actions. This course introduces these notions and their mathematical representations, as well as critically reflects on philosophical questions such as whether one should always take the action that maximize one''s expected utility, whether uncertainty is subjective or objective, and why uncertainty does, or ought to, obey the laws of probability.', null, 2, '{"operator": "AND", "items": ["PHL246H1", {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL447H1', 'Seminar in Philosophical Logic', '36S', 'Advanced discussion of some topic in philosophical logic.', null, 2, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL246H1", "PHL345H1", "PHL347H1", "PHL445H1", "MAT309H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL451H1', 'Seminar in Philosophy of Language', '36S', 'Advanced study of some topic in the philosophy of language.', null, null, '{"operator": "AND", "items": [{"credits": 4.0, "department": "PHL"}, {"operator": "OR", "items": ["PHL245H1", "MAT157Y1"]}, {"operator": "OR", "items": ["PHL232H1", "PHL233H1", "PHL240H1"]}]}'::jsonb),
    ('PHL455H1', 'Seminar in Philosophy of Science', '36S', 'Advanced study of some area or problem in the philosophy of science.', null, null, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHL355H1", "PHL357H1", "HPS250H1"]}, {"credits": 4.0, "department": "PHL"}]}'::jsonb),
    ('PHL470H1', 'Advanced Bioethics', '36S', 'Philosophical exploration of the foundations and methodology of bioethics. Offered jointly with PHL2145H.', null, null, '{"operator": "AND", "items": ["PHL281H1", {"operator": "OR", "items": ["PHL380H1", "PHL381H1", "PHL382H1", "PHL383H1", "PHL384H1"]}]}'::jsonb),
    ('PHL471H1', 'Advanced Topics in Greek Philosophy', '36S', 'Advanced Topics in Greek Philosophy', null, null, '{"operator": "AND", "items": ["PHL200Y1"]}'::jsonb),
