    ('PHL489Y1', 'Advanced Topics in Philosophy: Socrates Project', null, 'Socrates Project Seminar. The Socrates Project Seminar allows exceptional senior undergraduate students to become teaching assistants for a 1st year PHL course. In addition to grading and leading tutorials, Socrates Project students enroll in  PHL489Y1 as a condition of their employment. Students are expected to apply for the Socrates Project in March prior to the start of the Fall/Winter term. Admission to the Socrates Project is limited to students enrolled in a Philosophy or Bioethics program. A minimum of 80% in PHL courses is required. Information about the Socrates Project including the application form can be found at https://philosophy.utoronto.ca/st-george/undergraduate-at-st-george/socrates-project-undergraduate-tas/', null, null, null::jsonb),
    ('PHL490Y1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHL495H1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHL496H1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHL497H1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHL498H1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHL499H1', 'Individual Studies', null, 'Individual Studies. Not eligible for CR/NCR option. Students must complete an Individual Study application form (found on the Department of Philosophy website) in consultation with their proposed faculty supervisor. The application form must be submitted to the Undergraduate Administrator by the first day of classes.', null, null, null::jsonb),
    ('PHS103H1', 'Introduction to Public Health', '24L/24T', 'This course introduces students to basic Canadian public health-related concepts, significant aspects of the historical development of public health in Canada, and a selection of topics illustrating the broad and evolving nature of this field. In addition, it helps students explore the contributions that various disciplines/fields offer to public health in Canada.', 'PHS100H1', 3, null::jsonb),
    ('PHS300H1', 'HIV Prevention Research', '24L', 'This course examines HIV prevention research across the full spectrum of sciences concerned with prevention of HIV and sexual health, including basic science, clinical science, epidemiology, behavioural science, social science, and legal, policy, economic analysis, and cultural theory. Examples are borrowed from efforts across the globe. The course highlights prevention research related to key populations at risk of HIV infection and transmission. The course focuses on challenges and issues, with the goal of stimulating critical thinking and engagement with topics. Some material will be presented by Guest Lecturers who are experts in the areas, allowing students to learn from and interact with these experts and to hear about their current research as well as their career paths. It is expected that at the end of this course students will have an advanced appreciation of the history and future and underlying values and ethics of effective HIV prevention research, including future possibilities and challenges. One ancillary aim is to encourage students to compare and contrast HIV Prevention with prevention research in adjacent areas (e.g., HCV, HPV).', null, 3, null::jsonb),
    ('PHY100H1', 'The Magic of Physics', '24L/12T', 'This course provides a survey of Physics, including both Classical and Modern Physics. It is designed for non-scientists, and assumes no background in either science or mathematics. The approach to the course is broad rather than deep. We will concentrate on the concepts underlying such fascinating topics as planetary motion, chaos, the nature of light, time travel, black holes, matter waves, Schrodinger''s cat, quarks, and climate change. We will uncover the wonders of the classical and the quantum worlds courtesy of Galileo, Newton, Maxwell, Einstein, Heisenberg and many others. ( PHY100H1 is primarily intended as a Breadth Requirement course for students in the Humanities and Social Sciences with no university-level background in physics. Any student with university-level credit in physics, including students with secondary school transfer credits in physics is ineligible to take this course).', 'Any PHY course taken previously or concurrently (except  PHY196H1/  PHY197H1/  PHY198H1/  PHY199H1/  PHY202H1/  PHY205H1/  PHY207H1)', 5, null::jsonb),
    ('PHY131H1', 'Introduction to Physics I', '36L/20P', 'A first university physics course primarily for students not intending to pursue a Specialist or Major program in Physical or Mathematical Sciences. Topics include: classical kinematics & dynamics, momentum, energy, force, friction, work, power, angular momentum, oscillations, waves, sound. Lab kit fees of $52 may apply.', 'PHY151H1', 5, null::jsonb),
    ('PHY132H1', 'Introduction to Physics II', '36L/20P', 'The second university physics course primarily for students not intending to pursue a Specialist or Major program in Physical or Mathematical Sciences. Topics include: electricity, magnetism, light, optics, special relativity. Lab kit fees of $52 may apply.', 'PHY152H1', 5, '{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}'::jsonb),
    ('PHY151H1', 'Foundations of Physics I', '36L/30P', 'The first physics course in many of the Specialist and Major Programs in Physical Sciences. It provides an introduction to the concepts, approaches and tools the physicist uses to describe the physical world while laying the foundation for classical and modern mechanics. Topics include: mathematics of physics, energy, momentum, conservation laws, kinematics, dynamics, and special relativity.', 'PHY131H1', 5, null::jsonb),
    ('PHY152H1', 'Foundations of Physics II', '36L/30P', 'The concept of fields will be introduced and discussed in the context of gravity and electricity. Topics include rotational motion, oscillations, waves, electricity and magnetism.', 'PHY132H1', 5, '{"operator": "OR", "items": ["PHY131H1", "PHY151H1", "PHY180H1"]}'::jsonb),
    ('PHY189H1', 'Introduction to Research Methods in the Physical and Mathematical Sciences', '24P/24S', 'This course is an introduction to research challenges and methods in physical and mathematical sciences. Topics include documenting scientific work, literature searches, building a basic measurement system, mathematical modelling and measurement of simple physical systems, basic computational analysis of data, debugging (measurements, analysis, code, ...), evaluating uncertainties, ethical and social issues in science, and communicating scientific work orally and in writing.', null, 5, null::jsonb),
    ('PHY196H1', 'Emergence in Nature', '24S', 'The universe is not a rigid clockwork, but neither is it formless and random. Instead, it is filled with highly organized, evolved structures that have somehow emerged from simple rules of physics. Examples range from the structure of galaxies to the pattern of ripples on windblown sand, to biological and even social processes. These phenomena exist in spite of the universal tendency towards disorder. How is this possible? Self-organization challenges the usual reductionistic scientific method, and begs the question of whether we can ever really understand or predict truly complex systems. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY197H1', 'Modern Physics for the Curious', '24S', 'Have you wondered about the origin and workings of the natural world around us? Have you found physical science interesting but inaccessible because it was too full of math and jargon? Have you felt a pull to become more science-literate? If so, this seminar course is for you -- or for anyone interested in understanding more about the universe, including our planet, seen through the lens of modern physics. Ideas on the menu will include: particle physics, space and time, relativity, black holes, quantum physics, unification forces, string theory, and big bang cosmology. The intriguing story of these integrated phenomena unfolds over a wide distance and a long time. Students from diverse academic backgrounds are warmly welcome. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY198H1', 'Physics at the Cutting Edge', '24L/12S', 'A limited enrollment seminar course for First Year Science students interested in current research in Physics. Students will meet active researchers studying the universe from the centre of the earth to the edge of the cosmos. Topics may range from string theory to experimental biological physics, from climate change to quantum computing, from superconductivity to earthquakes. The course may involve both individual and group work, essays and oral presentations. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, '{"operator": "AND", "items": ["PHY151H1"]}'::jsonb),
    ('PHY199H1', 'Dark Matter and Dark Energy are the New Black', '24S', 'It is now 90 years since astronomers found the first evidence for a form of matter that wasn''t part of the stars in our galaxies, but rather is "dark" and has a gravitational attraction to ordinary matter. Other lines of evidence lead us to believe that there is six times more dark matter than the ordinary matter we are familiar with. Despite this, we have no credible, direct evidence for what this dark matter might be. It is one of the biggest puzzles in particle physics and cosmology. In the last decade, we have also discovered that something else is going on – the universe appears to be filled with "dark energy" that causes the expansion of our universe to speed up instead of slowdown. We will discuss what we know about the hypotheses of dark matter and dark energy, and the debates about what might really be going on. Are we seeing science in crisis, with a revolution just around the corner, or is this just the "normal science" talked about by Kuhn and other philosophers of science? Participants will be expected to participate in seminar-style discussions, as well as take the lead on at least one topic of discussion. Restricted to first-year students. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY202H1', 'The Physics of Science Fiction and Gaming', '24L/12T', 'The physics of time travel, teleportation, levitation, invisibility, special effects, and other physics related topics found in literature, film, and gaming. The course will analyze the realism of physical phenomena in these media, and consider the impact of these concepts on science and society. ( PHY202H1 is primarily intended as a Breadth Requirement course for students in the Humanities and Social Sciences with no university-level background in physics. Any student with university-level credit in physics, including students with secondary school transfer credits in physics is ineligible to take this course).', 'Any PHY course taken previously or concurrently (except  PHY196H1/  PHY197H1/  PHY198H1/  PHY199H1/  PHY100H1/  PHY205H1/  PHY207H1).', 5, null::jsonb),
    ('PHY205H1', 'The Physics of Everyday Life', '24L/12T', 'An introduction to the physics of everyday life. This conceptual course looks at everyday objects to learn about the basis for our modern technological world. Topics may include anything from automobiles to weather. ( PHY205H1 is primarily intended as a Breadth Requirement course for students in the Humanities and Social Sciences with no university-level background in physics. Any student with university-level credit in physics, including students with secondary school transfer credits in physics is ineligible to take this course).', 'Any PHY course taken previously or concurrently (except  PHY196H1/  PHY197H1/  PHY198H1/  PHY199H1/  PHY100H1/  PHY202H1/  PHY207H1).', 5, null::jsonb),
    ('PHY207H1', 'The Physics of Music', '24L/12T', 'An online course intended to provide non-science students with a basic understanding of the science behind sound and music. Topics include oscillations, waves, human hearing and perception of music, musical scales, musical instruments, recording and storing sound digitally, producing sound and broadcasting. Lectures will be delivered via the web and mandatory tutorials will require live webinar participation. The final exam will require attendance on the St. George campus. (PHY207H1 is primarily intended as a Breadth Requirement course for students with no university-level background in physics. Any student with university-level credit in physics, including students with secondary school transfer credits in physics is ineligible to take this course).', 'Any PHY course taken previously or concurrently (except  PHY196H1/  PHY197H1/  PHY198H1/  PHY199H1/  PHY100H1/  PHY202H1/  PHY205H1).', 5, null::jsonb),
    ('PHY224H1', 'Practical Physics I', '72P', 'Develops the core practical experimental and computational skills necessary to do physics. Students tackle simple physics questions involving mathematical models, computational simulations and solutions, experimental measurements, data and uncertainty analysis.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY231H1', 'Physics of Living Systems', '24L/18P', 'An introductory course for students interested in understanding the physical phenomena occurring in biological systems and the applications of physics in life sciences. Topics may include physical processes inside living cells and systems, medical physics and imaging.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY250H1', 'Electricity and Magnetism', '24L/12T', 'An introductory course in Electromagnetism. Topics include: Point charges, Coulomb''s law, electrostatic field and potential, Gauss''s Law, conductors, electrostatic energy, magnetostatics, Ampere''s Law, Biot-Savart Law, the Lorentz Force Law, Faraday''s Law, Maxwell''s equations in free space.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY252H1', 'Thermal Physics', '24L/12T', 'The quantum statistical basis of macroscopic systems; definition of entropy in terms of the number of accessible states of a many particle system leading to simple expressions for absolute temperature, the canonical distribution, and the laws of thermodynamics. Specific effects of quantum statistics at high densities and low temperatures.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY254H1', 'Classical Mechanics', '24L/12T', 'The course analyzes the linear, nonlinear and chaotic behaviour of classical mechanical systems such as harmonic oscillators, rotating bodies, and central field systems. The course will develop the analytical and numerical tools to solve such systems and determine their basic properties. The course will include mathematical analysis, numerical exercises using Python, and participatory demonstrations of mechanical systems.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY256H1', 'Introduction to Quantum Physics', '24L/12T', 'Failures of classical physics; the Quantum revolution; Stern-Gerlach effect; harmonic oscillator; uncertainty principle; interference packets; scattering and tunneling in one-dimension.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY131H1", "PHY151H1"]}, {"operator": "OR", "items": ["PHY132H1", "PHY152H1"]}, {"operator": "OR", "items": [{"operator": "AND", "items": ["MAT135H1", "MAT136H1"]}, "MAT137Y1", "MAT157Y1"]}]}'::jsonb),
    ('PHY299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY324H1', 'Practical Physics II', '72P', 'A modular practical course that further develops the core experimental and computational skills necessary to do physics. Modules include: experimental skills building, computational tools in data and uncertainty analysis, and independent experimental projects.', null, 5, '{"operator": "AND", "items": ["PHY224H1", {"operator": "OR", "items": ["PHY231H1", "PHY250H1", "PHY252H1", "PHY254H1", "PHY256H1"]}]}'::jsonb),
    ('PHY331H1', 'Introduction to Biological Physics', '24L/18P', 'A course for students interested in a deeper understanding of physical phenomena occurring in biological systems. Thermodynamics, diffusion, entropic forces, fluids, biological applications.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY252H1", "CHM222H1"]}, {"operator": "OR", "items": ["PHY231H1", "PHY250H1", "PHY254H1", "PHY256H1"]}]}'::jsonb),
    ('PHY350H1', 'Electromagnetic Theory', '24L/12T', 'This course builds upon the knowledge and tools developed in  PHY250H1. Topics include: solving Poisson and Laplace equations via method of images and separation of variables, multipole expansion for electrostatics, atomic dipoles and polarizability, polarization in dielectrics, multipole expansion in magnetostatics, magnetic dipoles, magnetization in matter, Maxwell''s equations in matter, conservation laws in electrodynamics, and electromagnetic waves.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["MAT244H1", "MAT267H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, "PHY250H1"]}'::jsonb),
    ('PHY354H1', 'Advanced Classical Mechanics', '24L/12T', 'Symmetry and conservation laws, stability and instability, generalized coordinates, Hamilton''s principle, Hamilton''s equations, phase space, Liouville''s theorem, canonical transformations, Poisson brackets, Noether''s theorem.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["MAT244H1", "MAT267H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, "PHY254H1"]}'::jsonb),
    ('PHY356H1', 'Quantum Mechanics I', '24L/12T', 'The general structure of wave mechanics; eigenfunctions and eigenvalues; operators; orbital angular momentum; spherical harmonics; central potential; separation of variables; hydrogen atom; Dirac notation; operator methods; harmonic oscillator and spin.', 'CHM326H1', 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, "PHY250H1", {"operator": "OR", "items": ["PHY256H1", {"operator": "AND", "items": ["CHM222H1", "CHM223H1"]}]}]}'::jsonb),
    ('PHY357H1', 'Nuclear and Particle Physics', '24L/12T', 'The subatomic particles; nuclei, baryons and mesons, quarks, leptons and bosons; the structure of nuclei and hadronic matter; symmetries and conservation laws; fundamental forces and interactions, electromagnetic, weak, and strong; a selection of other topics: CP violation, nuclear models, standard model, proton decay, supergravity, nuclear and particle astrophysics. This course is not a prerequisite for any PHY400-level course.', null, 5, '{"operator": "AND", "items": ["PHY356H1"]}'::jsonb),
    ('PHY358H1', 'Quantum Materials: from Atoms to Crystals', '24L/12T', 'This course covers the most important iconic quantum systems, from the hydrogen atom through to solid state systems, focusing on how quantum mechanics is applied and determines physical properties of atoms, molecules, and crystals. It begins with the hydrogen atom, including orbital and spin angular momentum, spin-orbit coupling, and effects of the magnetic field, and then extends to systems of two identical particles: bosons vs. fermions and the helium atom with two electrons. Other topics include spin singlets and triplets, entanglement, perturbation theory, the effects of electron-electron interactions and diatomic molecules. For crystals, the course covers Fermi gases, Fermi surfaces, crystal structure, the reciprocal lattice, the nearly-free electron model, energy bands, and topology using low-dimensional models.', null, 5, '{"operator": "AND", "items": ["PHY356H1"]}'::jsonb),
    ('PHY365H1', 'Quantum Information', '24L/12T', 'Introduction to quantum computing; Quantum states of multi-particle systems and Entanglement; Quantum Algorithms; Quantum Information Processing Technologies; Quantum error correction.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY256H1", "PHY294H1", "CHM223H1", "ECE330H1"]}, {"operator": "OR", "items": ["MAT223H1", "MAT240H1"]}]}'::jsonb),
    ('PHY371Y1', 'Supervised Study in Physics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore interdisciplinary fields not available in the regular syllabus. Consult the department web pages for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY372H1', 'Supervised Study in Physics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore interdisciplinary fields not available in the regular syllabus. Consult the department web site for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY378H1', 'Undergraduate Research Project', null, 'An individual experimental or theoretical research project undertaken with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore independent research. Consult the department web site for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY379Y1', 'Undergraduate Research Project', null, 'An individual experimental or theoretical research project undertaken with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore independent research. Consult the department web site for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY385H1', 'Introductory Optics', '24L/20P', 'An introduction to the physics of light. Topics covered include: electromagnetic waves and propagation of light; the Huygens and Fermat principles; geometrical optics and optical instruments; interference of waves and diffraction; polarization; introduction to photons, lasers, and optical fibers.', 'ECE318H1', 5, '{"operator": "AND", "items": ["PHY250H1", "PHY224H1", {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('PHY392H1', 'Physics of Climate', '24L', 'This course provides an introduction to climate physics and the earth-atmosphere-ocean system. Topics include solar and terrestrial radiation; global energy balance; radiation laws; radiative transfer; atmospheric structure; convection; the meridional structure of the atmosphere; the general circulation of the atmosphere; the ocean and its circulation; and climate variability.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY250H1", "PHY252H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('PHY396Y0', 'Research Topic Abroad', null, 'Course credit for research or field studies abroad under the supervision of a faculty member. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY397Y0', 'Exchange Research Project Abroad', null, 'Course credit for research or field studies abroad under the supervision of a faculty or staff member from an exchange institution. Consult the Physics Department web pages for information about opportunities. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY398H0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY398Y0', 'Research Excursions', null, 'An instructor-supervised group project in an off-campus setting. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-excursions-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY399H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY399Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('PHY405H1', 'Electronics Lab', '12L/36P', 'Electrical circuits, networks and devices are all-pervasive in the modern world. This laboratory course is an introduction to the world of electronics. Students will learn the joys and perils of electronics, by designing, constructing and debugging circuits and devices. The course will cover topics ranging from filters and operational amplifiers to micro-controllers, and will introduce students to concepts such as impedance, transfer functions, feedback and noise.', null, 5, '{"operator": "AND", "items": ["PHY224H1", "PHY250H1"]}'::jsonb),
    ('PHY407H1', 'Computational Physics', '12L/36P', 'This is an introduction to scientific computing in physics. Students will be introduced to computational techniques used in a range of physics research areas. By considering select physics topics, students will learn basic computational methods for function analysis (computing integrals and derivatives; finding roots and extrema), resolution of linear and non-linear equations, eigenvalue problems, Fourier analysis, ODEs, PDEs and Monte Carlo techniques. As the course progresses, students will develop their skills at debugging, solution visualization, computational efficiency and accuracy. The course is based on python and will involve working on a set of computational labs throughout the semester as well as a final project.', null, 5, '{"operator": "AND", "items": ["PHY224H1", {"operator": "OR", "items": ["PHY250H1", "PHY252H1", "PHY254H1", "PHY256H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('PHY408H1', 'Time Series Analysis', '12L/24P', 'The analysis of digital sequences; filters; the Fourier Transform; windows; truncation effects; aliasing; auto and cross-correlation; stochastic processes, power spectra; least squares filtering; application to real data series and experimental design.', null, 5, '{"operator": "AND", "items": [{"operator": "OR", "items": ["PHY224H1", "ESS245H1"]}, {"operator": "OR", "items": ["PHY250H1", "PHY252H1", "PHY254H1", "PHY256H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('PHY424H1', 'Advanced Physics Laboratory', '72P', 'Experiments in this course are designed to form a bridge to current experimental research. A wide range of exciting experiments relevant to modern research in physics is available. The laboratory is normally open from 9 a.m. - 4 p.m., Monday to Friday.', null, 5, '{"operator": "AND", "items": ["PHY250H1", "PHY256H1", "PHY324H1", {"operator": "OR", "items": ["PHY350H1", "PHY354H1", "PHY356H1"]}]}'::jsonb),
    ('PHY426H1', 'Advanced Practical Physics I', '72P', 'This course is a continuation of  PHY424H1, but students have more freedom to progressively focus on specific areas of physics, do extended experiments, projects, or computational modules.', null, 5, '{"operator": "AND", "items": ["PHY424H1"]}'::jsonb),
    ('PHY428H1', 'Advanced Practical Physics II', '72P', 'This course is a continuation of  PHY426H1, but students have more freedom to progressively focus on specific areas of physics, do extended experiments, projects, or computational modules.', null, 5, '{"operator": "AND", "items": ["PHY426H1"]}'::jsonb),
    ('PHY429H1', 'Advanced Practical Physics III', '72P', 'This course is a continuation of  PHY428H1, but students have more freedom to progressively focus on specific areas of physics, do extended experiments, projects, or computational modules.', null, 5, '{"operator": "AND", "items": ["PHY428H1"]}'::jsonb),
    ('PHY431H1', 'Topics in Biological Physics', '24L/12T', 'An introduction to the physical phenomena involved in the biological processes of living cells and complex systems. Models based on physical principles applied to cellular processes will be developed. Biological computational modeling will be introduced.', null, 5, '{"operator": "AND", "items": ["PHY250H1", {"operator": "OR", "items": ["PHY252H1", "CHM222H1"]}, "PHY331H1"]}'::jsonb),
    ('PHY450H1', 'Relativistic Electrodynamics', '24L/12T', 'An introduction to relativistic electrodynamics. Topics include: special relativity, four-vectors and tensors, relativistic dynamics from the Principle of Stationary Action and Maxwell''s equations in Lorentz covariant form. Noether''s theorem for fields and the energy-momentum tensor. Fields of moving charges and electromagnetic radiation: retarded potential, Lienard-Wiechert potentials, multipole expansion, radiation reaction.', null, 5, '{"operator": "AND", "items": ["PHY350H1", "PHY354H1"]}'::jsonb),
    ('PHY452H1', 'Statistical Mechanics', '24L/12T', 'Classical and quantum statistical mechanics of noninteracting systems; the statistical basis of thermodynamics; ensembles, partition function; thermodynamic equilibrium; stability and fluctuations; formulation of quantum statistics; theory of simple gases; ideal Bose and Fermi systems.', null, 5, '{"operator": "AND", "items": ["PHY252H1", "PHY356H1"]}'::jsonb),
    ('PHY454H1', 'Continuum Mechanics', '24L/12T', 'The theory of continuous matter, including solid mechanics with a strong focus on fluid mechanics. Topics include the continuum approximation, dimensional analysis, stress, strain, the Euler and Navier-Stokes equations, vorticity, waves, instabilities, convection and turbulence.', 'PHYD37H3', 5, '{"operator": "AND", "items": ["PHY254H1", {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}, {"operator": "OR", "items": ["APM346H1", "APM351Y1"]}]}'::jsonb),
    ('PHY456H1', 'Quantum Mechanics II', '24L/12T', 'Quantum dynamics in Heisenberg and Schrödinger pictures; WKB approximation; variational method; time-independent perturbation theory; spin; addition of angular momentum; time-dependent perturbation theory; scattering.', null, 5, '{"operator": "AND", "items": ["PHY356H1"]}'::jsonb),
    ('PHY460H1', 'Nonlinear Physics', '24L/12T', 'The theory of nonlinear dynamical systems with applications to many areas of physics. Topics include stability, bifurcations, chaos, universality, maps, strange attractors and fractals. Geometric, analytical and computational methods will be developed.', null, 5, '{"operator": "AND", "items": ["PHY354H1"]}'::jsonb),
    ('PHY471Y1', 'Supervised Study in Physics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore interdisciplinary fields not available in the regular syllabus. Consult the department web pages for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY472H1', 'Supervised Study in Physics', null, 'An individual study program chosen by the student with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore interdisciplinary fields not available in the regular syllabus. Consult the department web pages for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY478H1', 'Undergraduate Research Project', null, 'An individual experimental or theoretical research project undertaken with the advice of, and under the direction of, a staff member. A student may take advantage of this course either to specialize further in a field of interest or to explore independent research. Consult the department web site for some possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY479Y1', 'Undergraduate Research Project', null, 'An individual experimental or theoretical research project undertaken with the advice of, and under the direction of, a faculty member. A student may take advantage of this course either to specialize further in a field of interest or to explore independent research. Consult the department web site for possible topics. This course may also be available in the summer. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('PHY483H1', 'Relativity Theory I', '24L/12T', 'Basis of Einstein''s theory: differential geometry, tensor analysis, gravitational physics leading to General Relativity. Theory starting from solutions of Schwarzschild, Kerr, etc.', null, 5, '{"operator": "AND", "items": ["PHY354H1"]}'::jsonb),
    ('PHY484H1', 'Relativity Theory II', '24L/12T', 'Applications of General Relativity to Astrophysics and Cosmology. Introduction to black holes, large-scale structure of the universe.', null, 5, '{"operator": "AND", "items": ["PHY483H1"]}'::jsonb),
    ('PHY485H1', 'Laser Physics', '24L', 'This course covers a broad range of advanced topics in classical optics, with the laser as a unifying theme. Topics include atom-photon interactions (absorption, radiation, and stimulated emission), how a laser works (gain, pumping, rate equation models, threshold, and gain clamping), optical resonators (their spectrum, finesse, stability, and transverse modes), propagation of Gaussian beams and paraxial rays, and the statistics of optical fields (spatial and temporal coherence). Time permitting, pulse propagation and pulsed lasers will be discussed.', null, 5, '{"operator": "AND", "items": ["PHY350H1", "PHY356H1", {"operator": "OR", "items": ["PHY385H1", "ECE318H1"]}]}'::jsonb),
    ('PHY487H1', 'Condensed Matter Physics', '24L', 'Introduction to foundational concepts of condensed matter physics in the solid state. Main topics to be covered: crystal structure, reciprocal lattice, x-ray diffraction, crystal binding, lattice vibrations, phonons and electrons in solids, Fermi surfaces, energy bands, semiconductors and magnetism. Special topics to be surveyed: superconductivity and nanoelectronic transport.', null, 5, '{"operator": "AND", "items": ["PHY250H1", "PHY252H1", "PHY356H1"]}'::jsonb),
    ('PHY489H1', 'Introduction to High Energy Physics', '24L', 'This course introduces the basics of fundamental particles and the strong, weak and electromagnetic forces that govern their interactions in the Standard Model of particle physics. Topics include relativistic kinematics, conservation laws, particle decays and scattering processes, with an emphasis on the techniques used for calculating experimental observables.', null, 5, '{"operator": "AND", "items": ["PHY356H1"]}'::jsonb),
    ('PHY491H1', 'Current Interpretations of Quantum Mechanics', '24L/24T', 'Different interpretations of quantum mechanics are presented and discussed, comparing and contrasting the various approaches to understanding the formalism of the theory.  We begin with “textbook quantum mechanics” and then discuss the Copenhagen view, operationalist quantum mechanics, hidden variable theories, Bohm-de Broglie theory, consistent histories, relational quantum mechanics, relative state approaches (many minds and many worlds), QBism, the interactional interpretation, and collapse theories.', null, 5, '{"operator": "AND", "items": ["PHY456H1"]}'::jsonb),
    ('PHY492H1', 'Advanced Atmospheric Physics', '24L/12T', 'A preparatory course for research in experimental and theoretical atmospheric physics. Content will vary from year to year. Themes may include techniques for remote sensing of the Earth''s atmosphere and surface; theoretical atmosphere-ocean dynamics; the physics of clouds, precipitation, and convection in the Earth''s atmosphere.', null, 5, '{"operator": "AND", "items": ["PHY224H1", {"operator": "OR", "items": ["PHY250H1", "PHY252H1", "PHY254H1"]}, {"operator": "OR", "items": ["MAT235Y1", "MAT237Y1", "MAT257Y1"]}]}'::jsonb),
    ('PLN420H1', 'Interdisciplinary Seminar in Planetary Science', '24S', 'Discussion of topics of current interest in planetary science with emphasis on papers published in scientific journals. This course is intended for students in the final year of the Planetary Science specialist program. Students must enrol with the course coordinator.', null, 5, null::jsonb),
    ('PLN425H1', 'Research in Planetary Science', '120P', 'Research report by student in consultation with individual staff member in Astronomy, Chemistry, Geology or Physics. This course is intended for students in the final year of the Planetary Science specialist program. Students must enrol with the course coordinator. Not eligible for CR/NCR option.', null, 5, null::jsonb),
    ('POL101H1', 'The Real World of Politics: An Introduction', '24L/12T', 'This course introduces students to compelling issues of contemporary politics through the lens of classic and important texts in political science. The course covers the politics of climate change, Indigenous rights, elections and electoral systems, terrorism, social movements and political activism, voting, democracy, and power.', 'POL101Y1', 3, null::jsonb),
    ('POL106H1', 'Contemporary Challenges to Democracy: Democracy in the Social Media Age', '24L/12T', 'This course examines the latest evidence-based research on the effects of social media on democracy. We cover surveillance capitalism, privacy, disinformation, and the often-overlooked ecological implications of data consumption. We also examine targeted digital espionage against civil society, Citizen Lab research reports, and explore solutions and alternatives to social media.', null, 3, null::jsonb),
    ('POL107H1', 'What Went Wrong? A Post Mortem of Political Disasters, Catastrophic Policy Failures, and Epic Marches of Folly', '24L/12T', 'Why do individuals, groups, and societies make repeated, and often easily predictable mistakes? Why do they persist in courses of action that produce disastrous results? Why is it that in the political world good intentions are insufficient to ensure good results? This course employs the political science analytical toolkit to answer these questions and examines an array avoidable disasters, from the local to the international.', 'POL486H1 (Topics in International Politics I: What Went Wrong? A Post Mortem of Political Disasters, Policy Failures and Marches of Folly), offered in Winter 2019 and Winter 2020;  POL487H1 (Topics in International Politics II: What Went Wrong? A Post Mortem of Political Disasters, Catastrophic Policy Failures), offered in Winter 2018', 3, null::jsonb),
    ('POL109H1', 'Might and Right: Power and Justice in International Relations', '24L/12T', 'This course explores the relationship between justice, power, and interests in the works of prominent ancient, modern, and contemporary thinkers. It adopts a problem-driven approach and engages with current controversies in international relations in light of insights from classic books. Special attention is paid to the prospects of a just world order, the causes and justifications of war, the construction of images of citizens and enemies, and the nature of duties to outsiders.', 'POL323Y1', 2, null::jsonb),
    ('POL191H1', 'First-Year Foundation Seminar:  Political Homes', '24L', 'Homes are core to our identities, shaping our beliefs, our social networks, and how we interact with the world. In turn, politics determines who has a home and who is homeless, whose home increases in value and whose mortgage gets foreclosed. Through careful consideration of evidence, we examine these processes. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL192H1', 'First-Year Foundation Seminar:  Beyond Voting: Introduction to Citizen Political Participation', '24L', 'This course introduces students to citizen political participation in democracies, with a focus on Canadian case studies. It examines theories of political participation and introduces students to a range of methods by which citizens engage in political life including social movements, political party membership, deliberative mini-publics and more. This course examines debates about the appropriate role for citizens in governance and considers barriers to equity in political participation in Canada. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL193H1', 'First-Year Foundation Seminar: Politics and the Arts', '24S', 'A study of political ideas as found in literature, plays, art works and film. Restricted to first-year students. Not eligible for CR/NCR option.', null, 2, null::jsonb),
    ('POL195H1', 'First-Year Foundation Seminar: Settler Colonialism and Enduring Indigeneity', '24S', 'This seminar explores the politics of representation in Indigenous multimedia. We study Indigenous cultural productions—memoir, documentary, graphic novel, film, poetry, music, and video games—to examine representations of settler colonialism and how Indigenous peoples endure it. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL196H1', 'First-Year Foundation Seminar: The China Challenge', '24S', 'China''s meteoric rise to great power status has triggered an intense international debate over its global implications. While many analysts see Beijing''s rise as posing a threat to global political and economic stability, Chinese leaders have argued forcefully that China''s efforts to regain its historic preeminence will result in a ''win-win" outcome for all states. This course will assess the merits of these contending positions through an historical examination of China''s 20th century renaissance. The course will begin by tracing the long period of imperial decline in the 19th century, culminating in China''s revolutionary rebirth as a Marxist state in 1949. A major focus will be on the Mao-era legacy of revolutionary diplomacy and the foreign policy consequences of its later transformation into a market-authoritarian powerhouse. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL197H1', 'First-Year Foundation Seminar: Politics and Sports: Identity, Activism, and Political Economy', '24S', 'The course aims to introduce first year students to key themes in political science – power, race, ethnicity, gender, sexuality, class, nationalism, social movements, activism, and political economy – through the lens of sports and those who participate in them. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL198H1', 'First-Year Foundation Seminar: Social Justice and the City', '24S', 'An introduction to the concept of social justice from an urban perspective. It will highlight how unequal relations of race, class, gender, sexuality, and ability operate through the urban environment, and how these conditions can be contested through political mobilization. Restricted to first-year students. Not eligible for CR/NCR option.', null, 3, null::jsonb),
    ('POL200Y1', 'Political Theory: Visions of the Just/Good Society', '48L/24T', 'A selective presentation of critical encounters between philosophy and politics, dedicated to the quest for articulation and founding of the just/good society. Among the theorists examined are Plato, Aristotle, Machiavelli, Hobbes and Locke.', 'POL200Y5/ POLC70H3/ POLC71H3', 2, null::jsonb),
    ('POL201H1', 'Politics of Development', '24L/12T', 'This course offers an introduction to the history and politics of economic and political development, starting with the Industrial Revolution and then turning to a critical analysis of the politics of economic growth, international trade, debt, state intervention, protectionism, and neo-liberalism in the global periphery, including Africa, Asia, and Latin America.', 'POL201Y1/ POLB90H3/ POLB91H3', 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL205H1', 'International Relations in the Anthropocene', '24L/12T', 'Humans have altered the planet so dramatically that some geologists have coined a new epoch: the Anthropocene. Is our study of global politics up to the challenge of human-driven environmental change? In this course, we consider multiple perspectives on IR to make sense of geopolitics on a changing planet.', null, 4, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL208H1', 'Introduction to International Relations', '24L/12T', 'This introductory course examines some key themes and issues in global politics, including interstate war, human rights, international institutions, and the evolution of the global order.', 'POL208Y1/  POL208Y5/  POL209H5/  POLB80H3/  POLB81H3', 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL212H1', 'Understanding War', '24L/12T', 'General introduction to the study of war, covering basic concepts and theories and surveying a selection of key topics and debates. Sessions revolve around a few essential readings, which must be completed before class and will serve as a basis for various in-class and in-tutorial activities including presentations, case studies, simulations, and games.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL214H1', 'Canadian Government', '24L/12T', 'An introduction to the study of Canadian government. Topics include institutions of governance: the constitution, machinery of government, charter of rights and freedom, and the electoral system.', 'POL214Y1/ POL214Y5/ POL215H5/ POL216H5/ POL224H1/ POL224Y1/ POLB50Y3', 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL218H1', 'State, Society and Power in Comparative Perspective', '24L/12T', 'This course is designed to introduce students to major issues and challenges that shape states, determine how they are governed, and how they change. The course helps to explain major events such as state transformation, democratization, authoritarian rule, civil conflict and social mobilization.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL219H1', 'Unpacking Political Systems: Institutions and Behavior in Comparative Perspective', '24L/12T', 'This course aims to unpack the institutional and behavioral variation within political systems. The goal is to expose students to the key questions and theories in comparative politics around three themes: a) the origins and effects of political institutions (federalism, electoral rules, bicameralism, courts…); b) party and electoral behavior across democracies and authoritarian regimes; and c) explaining quality of governance (issues of representation, accountability, trust, corruption). We will draw on cutting edge research and touch on current events and a variety of cases.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL220H1', 'Immigration, Multiculturalism, and Citizenship in Canada', '24L/12T', 'This course deals with three inter-related themes – immigration, multiculturalism, and citizenship – by focusing on a single unifying question: What does it mean to “belong” to the Canadian political community? Who belongs, on what terms, and to what ends? A range of materials – normative, empirical, historical, and contemporary – will be used.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL222H1', 'Introduction to Quantitative Reasoning I', '24L/12T', 'Introduces the foundation of quantitative empirical research methods - increasingly popular and important part of political science research and public policy debates - to enable students to interpret and evaluate the study results that employ these methods. Topics include quantitative study of politics and various empirical research designs.', 'POL242Y5/ ECO220Y1/ PSY201H1/ SOC202H1/ STA220H1', 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL223H1', 'Globalization and Development: Issues and Challenges', '24L/12T', 'This course examines how globalization creates opportunities and challenges to development in the Global South. Key issues considered include globalization and dynamics of inequality amongst and within nations, human rights and democratic struggles, environmental sustainability and justice, gender and racialized patterns of inequality, trade, foreign aid and poverty alleviation.', null, 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL224H1', 'Canada in Comparative Perspective', '24L/12T', 'This course introduces students to aspects of Canadian political life by comparing them with those that prevail in other advanced democracies. Themes covered will include the Canadian constitution, federalism, parties and elections, political culture and social and economic institutions and policies.', 'POL111H5/ POL214H1/ POL214Y1/ POL214Y5/ POL215H5/ POL216H5/ POL224Y1/ POLB50Y3', 3, '{"operator": "OR", "items": [{"credits": 4.0, "department": null}, {"credits": 1.0, "department": "POL"}, {"credits": 1.0, "department": "JPA"}, {"credits": 1.0, "department": "JPF"}, {"credits": 1.0, "department": "JPI"}, {"credits": 1.0, "department": "JPR"}, {"credits": 1.0, "department": "JPS"}, {"credits": 1.0, "department": "JRA"}]}'::jsonb),
    ('POL232H1', 'Introduction to Quantitative Reasoning II', '24L/12T', 'Building up on  POL222H1, students will continue to develop theoretical foundations of quantitative empirical research, such as probability theory, statistical inference, and linear regression analysis. They will also learn the basic use of statistical software and become able to conduct basic data analysis by the end of the semester.', 'POL242Y5/ GGR270H1', 3, '{"operator": "AND", "items": ["POL222H1"]}'::jsonb),
    ('POL299H1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL299Y1', 'Research Opportunity Program', null, 'Credit course for supervised participation in faculty research project. Details at https://www.artsci.utoronto.ca/current/academics/research-opportunities/research-opportunities-program. Not eligible for CR/NCR option.', null, null, null::jsonb),
    ('POL300Y0', 'Topics in Comparative Politics', '48L', 'An introduction to the field of comparative politics. Content in any given year depends on instructor. (Offered as part of the Summer Abroad Program)', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL301H1', 'Colonial Legacies and Post-Independence African Politics', '24L', 'This course highlights the critical roles of pre-colonial and colonial histories in shaping contemporary political and economic developments in Africa. It covers the emergence of colonial states, the central legacies of colonial rule, and the impact of colonialism in shaping process of state and nation building from independence to the present.', 'POL301Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL302H1', 'Politics and Society in 20th Century China', '24L', 'This course examines China''s efforts to reconstitute its political institutions following the collapse of the imperial system in 1911. Particular attention is paid to the clash between competing conceptions of political development and the rival political movements and forces that espoused them. The search for an effective and stable political order is a major focus of the course.', 'POL302Y1/ POLC16H3', 3, null::jsonb),
    ('POL303H1', 'Women in Western Political Thought', '24L', 'Examines contemporary feminist perspectives in political theory as responses to the limitations of western tradition of modern political theory.', 'POLC76H3/ POLC77H3', 2, '{"operator": "OR", "items": ["PHL265H1", "POL200Y1", "POL200Y5"]}'::jsonb),
    ('POL304H1', 'Topics in Methods', '24L', 'Various topics are taken up each year, the content of which depends on the instructor.', null, 3, '{"operator": "AND", "items": ["POL232H1"]}'::jsonb),
    ('POL305H1', 'Introduction to Latin American Politics and Societies', '24L', 'This course introduces students to histories and concepts necessary to understand developments in Latin American politics. Substantive issues will include the changing face of state sovereignty; human rights and social movements; the legacies of (neo)colonialism and indigenous resistance; neoliberalism, 21st century socialism, and beyond.', 'POL305Y1/ POL360H5/ POLC91H3/ POLC99H3', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL307H1', 'Japanese Politics', '24L', 'The politics, political economy, and international relations of Japan. The role of political parties, the bureaucracy, and private actors; economic development and stagnation; relations with the USA and regional neighbors. Contemporary challenges facing Japan, including energy policy and climate change, contributions to the liberal order, and response to geopolitical challenges.', 'POL380H1 (Topics in International Politics: Japanese Politics), offered in Winter 2020 and Winter 2021', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": "POL"}]}'::jsonb),
    ('POL309H1', 'Contemporary African Politics: Dynamics and Challenges', '24L', 'This course explores main drivers of political organization and change in contemporary Africa, focusing on how national, regional, and international factors shape institutions, patterns of participation and political change. It considers major scholarly debates in the study of African politics and political economy and develops analytical skills for comparative study of this diverse continent.', 'POL301Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL310H1', 'Nationality Building in Central Europe', '24L', 'This course is a case study of nationalism based on the experience of a stateless people in Europe called Carpatho-Rusyns. Emphasis is on how factors such as historical ideology, language, education, religion, and politics are used by the intelligentsia to create a national consciousness among the inhabitants.', 'JHP451Y1', 3, '{"operator": "AND", "items": [{"credits": 4.0, "department": null}]}'::jsonb),
    ('POL311H1', 'Law and Political Development', '24L', 'This course illuminates how political authority is constructed and contested, alongside the role that law and legal actors play in this process. Focusing on the historical development of territorial states, but also considering empires and international organizations, we will debate how these polities emerge, how they project their power and legitimate their authority, how people challenge and resist their rule, and how laws, lawyers, and judges impact these processes of political development. Throughout we will animate our discussions with an array of comparative examples – such as the medieval origins of the rule of law in Europe, the territorial expansion of the US federal state, and the political role that courts play in democratic and authoritarian states today.', 'POL378H1 (Law and Political Development), offered in Fall 2023 and 2024.', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL312H1', 'Canadian Foreign Policy', '24L', 'The literature, competing theories, basic interests and values, and instruments of Canadian foreign policy, as they have developed and performed under successive Liberal, Progressive Conservative and Conservative party governments since 1945 and especially from 2015 to 2021.', 'POL312Y1', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL314H1', 'Public Opinion and Voting', '24L', 'This course introduces students to the attitudes and behaviours of the mass public in Canada and other western democracies and how they shape elections and policy making. Themes include political participation, the mass media, and the nature of social, psychological, and economic, and elite-driven forces on public opinion and voting.', 'POLC21H3', 2, '{"operator": "AND", "items": ["POL222H1"]}'::jsonb),
    ('POL315H1', 'American Civil Liberties', '24L', 'This course offers a survey of American constitutional law in the area of civil liberties. Topics to be covered include: fundamental rights; freedoms of speech, press, and assembly; religious liberties; rights to privacy and autonomy; and due process and equal protection of the laws; sexual and familial rights.', 'POL379H1 (Civil Liberties in the United States), offered in Fall 2022, 2023, and 2024.', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL316H1', 'Contemporary Canadian Federalism', '24L', 'Constitutional, political, administrative, and financial aspects of federal-provincial relations, regionalism, and cultural dualism.', 'POL316Y1/ POL316Y5/ POL353Y5/ POLC54H3/ POLC57H3', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1"]}'::jsonb),
    ('POL317H1', 'Comparative Public Policy', '24L', 'Draws from the major theoretical traditions in public policy and policymaking of the advanced industrial world, and applies these theories in understanding the developing world context and the new challenges of global change.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL319H1', 'Elections and Voting', '24L', 'This course aims to introduce students to the essential elements for understanding the electoral process. The course will first present an introduction to the origin and objectives of elections. It will then address electoral procedures and their impact on electoral participation, party systems and the determinants of vote choice. While the overwhelming focus will be on the Canadian case, the course often draws upon examples and readings from other countries/institutional contexts to highlight important differences and similarities.', 'POL382H1 (Elections), offered in Fall 2023, and (Elections and Voting), offered in Winter 2025', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y5", "POL215H5", "POL216H5", "POL224H1"]}'::jsonb),
    ('POL320H1', 'Modern Political Thought:  Freedom and Equality', '24L/12T', 'An exploration of ideas of freedom in the rise of the modern age from the 18th and 19th centuries, from the Age of Enlightenment to the Age of Democratic Revolutions. Thinkers studied include Rousseau, Burke, and Wollstonecraft.', 'POL320Y1/ POL320Y5/ POLC73H3/ POLC74H3', 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5"]}'::jsonb),
    ('POL321H1', 'Modern Political Thought:  Progress Through History', '24L/12T', 'An exploration of modern political thought from the 19th to the beginning of the 20th centuries. Themes include the idea of progress through history and its implications for politics, as explored by thinkers such as J.S. Mill, Marx, Hegel, and Nietzsche.', 'POL320Y1/ POL320Y5/ POLC73H3/ POLC74H3', 2, '{"operator": "OR", "items": ["POL200Y1", "POL200Y5"]}'::jsonb),
    ('POL324H1', 'European Union: Politics, Institutions and Society', '24L', 'This course provides an in-depth understanding of the history, institutions, laws, and policies of the European Union (EU). We will debate alternative explanations for the political development of the EU, unearth the events and actors that have shaped European integration, and place the EU in a broader comparative perspective. We will also grapple with key social and political debates facing the EU today, such as debates concerning the democratic legitimacy of the EU, immigration and the EU''s handling of the refugee crisis, the rise of Euroskepticism and Brexit, the rule of law crisis and autocratization of some EU member states, and how the war in Ukraine has impacted the trajectory of European integration.', null, 3, '{"operator": "OR", "items": [{"credits": 1.0, "department": null}, "EUR200Y1"]}'::jsonb),
    ('POL325H1', 'Contemporary Latin American Politics', '24L', 'This course focuses on 21st century Latin American Politics. Specific attention will be paid to the ''Pink Tide'' of left of centre governments and their aftermaths; enduring legacies of resource extraction driven development models, and Latin America''s position in shifting geopolitical contexts.', 'POL305Y1/ POL360H5/ POLC91H3/ POLC99H3', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL326H1', 'The Politics of U.S. Foreign Policy', '24L', 'This course explores the making of foreign policy in the U.S. through a detailed examination of the institutions of the U.S. government involved, as well as the forces acting upon them to shape policy. After exploring theoretical approaches to the subject, it examines the evolution of the constitutional context within which U.S. foreign policy has been articulated, the bureaucracies involved in shaping policy, the impact of elections, groups and the mass media.', 'POL326Y1/ POL327Y5', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL327H1', 'U.S. Foreign Policy in a Complex World', '24L', 'This course explores the foreign policy of the U.S. through a series of regional and thematic case studies. It begins with a historical review of U.S. foreign policy in the evolution of the U.S. as a major global power, prior to WWII. Among the case studies of U.S. foreign policy included are international organization and law, terrorism, environment (climate), Latin America, Europe, Middle East, China/East Asia, Africa and Russia.', 'POL326Y1/ POL327Y5', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL328H1', 'Politics and Government in South Asia', '24L', 'This course introduces students to politics in South Asia in the period after independence from colonial rule. It focuses on India, Pakistan, Sri Lanka and Bangladesh. The themes discussed in the course are important both to South Asia as well as to a general study of politics in developing countries.', 'POL328Y1', 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1", "POL218H1"]}'::jsonb),
    ('POL329H1', 'Experiences of Conflict', '24L', 'The course reviews selected novels that deal with personal and collective experiences of conflict. It focuses on representations of how conflict is experienced. It gives students a practical understanding of the human dimension of selected major conflicts and explores possibilities for personal and social resistance to injustice and violence. Special attention is paid to questions of identity formation and moral choice in contexts of war and nationalism.', null, 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL332H1', 'Using Data to Understand Politics and Society', '24L', 'Students will learn the research tools and methods for causal inference with political and social data, including panel and temporal design, difference-in-difference, linear regression, regression discontinuity design, as well as text and network analysis, spatial statistics, and time-series analysis. This course draws from topics in the study of international relations, economics, political behavior, and statistics.', 'POL304H1 (Using Data to Understand Politics and Society), offered in Fall 2021, 2022, and Winter 2021, 2024,  ECO372H1,  STA302H1', 3, '{"operator": "AND", "items": ["POL222H1"]}'::jsonb),
    ('POL333H1', 'Global Politics and Global Political Thought', '24L', 'This course will examine three pressing contemporary topics (examples include: environmental justice and the natural world; race and identity politics; and international and cosmopolitan visions) through the theoretical and analytical lenses provided by the political thought of non-Western cultural traditions and from particular marginalized identity perspectives.', 'POL381H1 (Topics in Political Theory: Global Politics and Global Political Thought) taken in Winter 2020 (LEC0101), Winter 2021 (LEC0101), Winter 2022 (LEC0101), Winter 2023 (LEC0201)', 2, '{"operator": "AND", "items": ["POL200Y1"]}'::jsonb),
    ('POL334H1', 'Ontario and Quebec Politics', '24L', 'An examination of politics in Canada''s two most populous provinces. Drawing insights from comparative political economy scholarship, the course compares their politics in term of their distinctive historical origins, and their political economies, party systems, cultures, and relations with the federal government.', 'POLC55H3', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1"]}'::jsonb),
    ('POL336H1', 'Topics in Provincial Politics', '24L', 'Content in any given year depends on instructor.', 'POL336Y5', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1"]}'::jsonb),
    ('POL337H1', 'The Canadian Constitution', '24L', 'The moral foundations, historical events, political forces and legal ideas that have shaped the Canadian constitution; the roots, legacies, and judicial interpretation of the Constitution Act 1867, the Constitution Act 1982, and in particular the Charter of Rights and Freedoms; the constitutional framework of federalism; the politics of constitutional change; multiculturalism, ''rights talk'', and the judicialization of politics.', 'POL337Y1/ POLC68H3', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1"]}'::jsonb),
    ('POL338H1', 'Queer International Relations', '24L', 'Are States straight? How does racialized homophobia shape the international order? This course tackles these and other questions at the intersection of sexuality and IR. We examine concepts like sovereignty through a queer lens and explore issues like transphobia in right-wing populism and the institutionalization of SOGI terminology at the UN.', 'POL380H1 (Topics in International Politics: Queer IR), offered in Winter 2020 (L5101), Winter 2021 (L0201) and Winter 2022 (L0201)', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL340H1', 'International Law: Foundations', '24L', 'This course will introduce students to the primary sources of international law (treaties and customary international law) and the legal attributes of the core actors in the international system, including states, international organizations and individuals. Related topics will include governance of territory and the seas.', 'POL340Y1/ POL340Y5/ POLC38H3', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL341H1', 'International Law: Operation of the International Legal Order', '24L', 'This course will expose students to the operation of international legal order with respect to the use of armed force, the law of armed conflict, and the protection of human rights. Students will also be introduced to how dispute settlement works between states.', 'POL340Y1/ POL340Y5/ POLC38H3', 3, '{"operator": "OR", "items": ["POL208H1", "POL208Y1", "POL209H5"]}'::jsonb),
    ('POL342H1', 'Topics in Methods I', '24L', 'Content depends on instructor. This course will be used for a new or short-term 300-level methods course.', null, 3, '{"operator": "AND", "items": ["POL222H1"]}'::jsonb),
    ('POL344H1', 'Social Movements in Canada', '24L', 'This course introduces the major theoretical debates in the study of social movements through a series of Canadian case studies. Students will consider the role of protest in agenda setting, how power shapes actors'' protest tactics, and the relationship between protest and other forms of political engagement.', null, 3, '{"operator": "OR", "items": ["POL214H1", "POL215H5", "POL216H5", "POL224H1"]}'::jsonb),
    ('POL347H1', 'U.S. Government and Politics: Constitutional Structure and Development', '24L', 'This course examines the constitutional foundations of American politics—the separation of powers, federalism, and rights. Major themes include the historical origins of the American constitution, the transformation of American constitutionalism from the Civil War to the New Deal, and the struggle over the meaning of American constitutionalism in the 21st century.', 'POL203Y1/ POL203Y5/ POL386Y1/ POLC92H3/ POLC93H3', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL348H1', 'Privilege and Race in Global Perspective', '24L', 'This course considers how notions of race and privilege “travel” and how they have developed and functioned in contexts outside of a North American White/non-White categorization, where they interact with other axes of identity, including Indigeneity, ethnicity and caste.', 'POL381H1 (Topics in Political Theory: Privilege and Race in Global Perspective) taken in Winter 2019 (LEC0101), Fall 2019 (LEC0101), Fall 2020 (LEC0101), Fall 2021 (LEC0101)', 2, '{"operator": "AND", "items": ["POL200Y1"]}'::jsonb),
    ('POL349H1', 'Global Urban Politics', '24L', 'An examination of how political life is being transformed in the global urban age. Concepts such as territory, the state, citizenship, agency, sovereignty, and power will be reconsidered through a particularly urban lens.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL350H1', 'Politics of East Central Europe', '24L', 'This course examines political change in East Central Europe from the Middle Ages to the present. How are democracies created and why do they collapse? Did Eastern and Western Europe diverge politically centuries ago, or is the idea of a longstanding east-west divide largely an artefact of Cold War geopolitics?', 'POL377H1 (Topic: The Making of Modern Democracy: From the Middle Ages to the European Union) offered in Fall 2022 and 2023.', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL351H1', 'Gender, Politics, and Public Policy in Comparative Perspective', '24L', 'An introduction to gender and politics that examines women as political actors and their activities in formal and grassroots politics. The course also explores the impact of gender in public policy and how public policies shape gender relations. Cases to be drawn on include Canada, other countries in North America and Europe, and the developing world.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL352H1', 'Introduction to Qualitative Research Methods', '24L/12T', 'This course introduces students to qualitative research methods in political science (e.g., interviews, participant observation, case studies). It provides opportunities to acquire hands-on experience with these methods and prepares students to carry out their own research projects. Note:  POL352H1 cannot be used as a substitute for  POL222H1 for POL major/specialist program, or  POL232H1 for the POL specialist program.', 'ENV223H1,  POL252H1,  SOC204H1,  GGR271H1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL354H1', 'Politics and Society in Russia', '24L', 'Explores the evolution of Russian politics and society since the collapse of the Soviet Union. Major themes include political leadership, state-building, federalism and regional diversity, public opinion and political culture, civil society and protest, political economy, Russia''s behavior on the international stage, and Soviet legacies.', 'POL354Y5', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL356H1', 'Canadian Political Parties and Elections', '24L', 'The evolution and setting of Canada''s federal party system and Canadian elections. Topics include historical and theoretical perspectives, the Liberal, Conservative and New Democratic parties, third parties, leadership selection and local nominations, the representation of women and minorities in Parliament, electoral systems and election rules, campaigns, and voter behaviour.', 'POL356Y1', 3, '{"operator": "OR", "items": ["POL214H1", "POL214Y1", "POL215H5", "POL216H5", "POL224H1", "POL224Y1"]}'::jsonb),
    ('POL357H1', 'Topics in South Asian Politics', '24L', 'Selected issues in South Asian politics. Content in any given year depends on instructor.', null, 3, '{"operator": "OR", "items": ["POL201H1", "POL201Y1"]}'::jsonb),
    ('POL358H1', 'Conflicts, Minority Rights and Para-States in Europe', '24L', 'This course examines a number of unresolved issues in Europe that are largely shaped by real and perceived shortcomings in minority rights. After a section on Roma Rights in Central Europe, our focus turns to the origins and outcomes of largely separatist wars in Azerbaijan, Cyprus, Georgia, Moldova and Ukraine and the peace agreements that followed.', 'POL359Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL359H1', 'Enlarging Europe: The European Union and Its Applicants', '24L', 'European integration remains one of the most important and successful political experiments in recent history. This course looks at the historical impetus for European integration after the Second World War and to the recent trends in this process, as well as its future prospects as the Union''s borders enlarge and it confronts new challenges.', 'POL359Y1', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL360H1', 'Topics in Latin American Politics', '24L', 'Selected issues in Latin American politics. Content and instructor vary from year to year.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb),
    ('POL361H1', 'Global Political Economy', '24L', 'This course focuses on key aspects and ideas of world economic order, such as those underlying policies governing trade, capital flows, migration, and development. It also provides an orientation to understanding and explaining underlying political dynamics and their implications.', 'POLC69H3', 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}, {"operator": "OR", "items": [{"operator": "AND", "items": ["ECO101H1", "ECO102H1"]}, "ECO105Y1"]}]}'::jsonb),
    ('POL363H1', 'Canadian Political Development', '24L', 'This course introduces students to Canadian political development – an approach that shows how attention to history can illuminate and explain patterns of Canadian politics. The course introduces students to core theories and tools of a developmental approach, then applies this approach to key moments, contestations, and institutions in Canadian politics.', 'POL382H1 (Topics in Canadian Politics: Canadian Political Development), offered in Winter 2018, Winter 2019', 3, '{"operator": "OR", "items": ["POL214H1", "POL224Y1", "POL215H5", "POL216H5", "POL224H1"]}'::jsonb),
    ('POL377H1', 'Topics in Comparative Politics I', '24L', 'An introduction to the field of comparative politics. Content in any given year depends on instructor.', null, 3, '{"operator": "AND", "items": [{"credits": 1.0, "department": null}]}'::jsonb)
